package com.dropluckledger;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(DropLuckLedgerConfig.GROUP)
public interface DropLuckLedgerConfig extends Config
{
	String GROUP = "dropluckledger";

	@ConfigItem(
		keyName = "chatMessages",
		name = "Chat message for logged drops",
		description = "Shows a game message when a drop is added to your ledger, with the number of kills since the last copy",
		position = 1
	)
	default boolean chatMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "importOnLogin",
		name = "Look for history on login",
		description = "When you log in to an account that has no ledger yet, check RuneLite's saved kill counts and Loot Tracker data and offer to import them",
		position = 2
	)
	default boolean importOnLogin()
	{
		return true;
	}
}

package com.dropluckledger;

import com.dropluckledger.plugin.RuneLiteGame;
import com.dropluckledger.ui.LedgerPanel;
import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.Collection;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

/**
 * Records boss kills and drops and shows how lucky or dry the player is.  This class only connects RuneLite to
 * {@link Tracker}, which does the work.
 */
@PluginDescriptor(
	name = "Drop Luck Ledger",
	description = "Records your boss kills and drops and shows how lucky or dry you are, from the real drop tables",
	tags = {"boss", "drop", "drops", "luck", "dry", "rate", "kc", "kill", "count", "loot", "unique", "collection", "log", "pet"},
	internalName = "drop-luck-ledger"
)
public class DropLuckLedgerPlugin extends Plugin
{
	private static final String ICON_RESOURCE = "/com/dropluckledger/icon.png";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private DropLuckLedgerConfig config;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	private volatile Tracker tracker;
	private NavigationButton navButton;

	@Provides
	DropLuckLedgerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DropLuckLedgerConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		final Tracker t = new Tracker(new RuneLiteGame(client, clientThread, itemManager, configManager, chatMessageManager),
			config, getPluginDirectory(), gson, executor);
		final LedgerPanel panel = t.start();
		tracker = t;

		final BufferedImage icon = ImageUtil.loadImageResource(DropLuckLedgerPlugin.class, ICON_RESOURCE);
		navButton = NavigationButton.builder()
			.tooltip("Drop Luck Ledger")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown() throws Exception
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		final Tracker t = tracker;
		tracker = null;
		if (t != null)
		{
			t.stop();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final Tracker t = tracker;
		if (t != null)
		{
			t.onGameStateChanged(event.getGameState());
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		final Tracker t = tracker;
		if (t != null)
		{
			t.onChatMessage(event.getType(), event.getMessage());
		}
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		final Tracker t = tracker;
		if (t == null)
		{
			return;
		}
		final Collection<ItemStack> items = event.getItems();
		final int[] ids = new int[items.size()];
		final int[] quantities = new int[items.size()];
		int i = 0;
		for (ItemStack stack : items)
		{
			ids[i] = stack.getId();
			quantities[i] = stack.getQuantity();
			i++;
		}
		t.onLoot(event.getType(), event.getName(), event.getAmount(), ids, quantities, event.getMetadata());
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		final Tracker t = tracker;
		if (t != null)
		{
			t.onWidgetLoaded(event.getGroupId());
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		final Tracker t = tracker;
		if (t != null)
		{
			t.onGameTick();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		final Tracker t = tracker;
		if (t != null)
		{
			t.onScriptPostFired(event.getScriptId());
		}
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		final Tracker t = tracker;
		if (t != null)
		{
			final Future<?> write = t.flushForShutdown();
			if (write != null)
			{
				event.waitFor(write);
			}
		}
	}
}

package com.dropluckledger;

import com.dropluckledger.capture.BossIndex;
import com.dropluckledger.capture.Capture;
import com.dropluckledger.capture.KcMessages;
import com.dropluckledger.engine.Catalog;
import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.history.Backfill;
import com.dropluckledger.history.Catchup;
import com.dropluckledger.history.HistoryInput;
import com.dropluckledger.history.HistoryPlanner;
import com.dropluckledger.history.LoggedLoot;
import com.dropluckledger.ledger.BossState;
import com.dropluckledger.ledger.Ledger;
import com.dropluckledger.ledger.LedgerCodec;
import com.dropluckledger.ledger.LedgerSaver;
import com.dropluckledger.plugin.DropLog;
import com.dropluckledger.plugin.DropMessages;
import com.dropluckledger.plugin.FileStore;
import com.dropluckledger.plugin.Game;
import com.dropluckledger.plugin.GameReader;
import com.dropluckledger.plugin.HistorySources;
import com.dropluckledger.plugin.ItemIcons;
import com.dropluckledger.plugin.TrackingState;
import com.dropluckledger.ui.LedgerPanel;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.JsonParser;
import java.awt.Component;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.ScriptID;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.util.Filepath;
import net.runelite.http.api.loottracker.LootRecordType;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Everything the plugin does, once RuneLite has told it what happened: reads the boss data, keeps one ledger per account,
 * records kill counts and drops as they come, reads the game's own records when the player opens them, and drives the side
 * panel.  It only ever sees the game through {@link Game}; the plugin class turns RuneLite's events into calls on this class.
 */
final class Tracker
{
	private static final Logger log = LoggerFactory.getLogger(Tracker.class);

	private static final String DATA_RESOURCE = "/com/dropluckledger/data.json";
	private static final String COLOSSEUM = "fortis-colosseum";
	/**
	 * The game's message after each wave of the Fortis Colosseum ("Wave 5 completed! Wave duration: 2:03.60").
	 */
	private static final java.util.regex.Pattern WAVE_COMPLETED = java.util.regex.Pattern.compile("^Wave (\\d+) completed!");
	/**
	 * How often (in ticks) to look again whether the Loot Tracker plugin is on.
	 */
	private static final int LOOT_TRACKER_CHECK_TICKS = 50;
	private static final String ICON_FILE = "item-ids.json";
	private static final long SAVE_DELAY_MS = 1500;
	private static final long ICON_SAVE_PERIOD_S = 30;
	private static final long ICON_RESCAN_MS = 30L * 24 * 60 * 60 * 1000;

	private final Game game;
	private final DropLuckLedgerConfig config;
	private final Filepath dir;
	private final Gson gson;
	private final ScheduledExecutorService executor;

	/**
	 * Everything that exists once the boss data has been read.
	 */
	static final class Core
	{
		final Data data;
		final BossIndex index;
		final Ledger ledger;
		final Capture capture;
		final HistoryPlanner planner;
		final Catchup catchup;
		final LedgerSaver saver;
		final ItemIcons icons;
		final FileStore iconStore;
		final DropLog dropLog;

		Core(Filepath dir, Data data, Gson gson, ScheduledExecutorService executor, Game game)
		{
			this.data = data;
			this.index = new BossIndex(data);
			this.ledger = new Ledger(data);
			this.capture = new Capture(ledger, index);
			this.planner = new HistoryPlanner(ledger, index);
			this.catchup = new Catchup(ledger, capture, planner, index);
			this.saver = new LedgerSaver(ledger, gson, executor, SAVE_DELAY_MS);
			this.ledger.addListener(saver);
			this.icons = new ItemIcons(game);
			this.iconStore = new FileStore(dir, ICON_FILE);
			this.dropLog = new DropLog(dir, executor);
			this.capture.setLootLog((t, bossId, killNo, items, snap) ->
			{
				List<LoggedLoot.Item> all = new ArrayList<>();
				for (Capture.Stack st : items)
				{
					all.add(new LoggedLoot.Item(st.name, st.qty));
				}
				dropLog.add(new LoggedLoot(t, bossId, killNo, all, snap));
			});
		}
	}

	private volatile Core core;
	private volatile TrackingState state = TrackingState.STARTING;
	/**
	 * Counts account changes; a load that finds the number moved on gives up.
	 */
	private volatile int bindGeneration;
	private String boundKey;
	/**
	 * Held while tracking is switched on or off and while the loaded data is handed over, so a load that finishes late never
	 * leaves anything running behind a plugin that was turned off.
	 */
	private final Object lifecycle = new Object();
	private volatile ExecutorService analysis;
	private Future<?> iconSaver;
	private volatile LedgerPanel panel;

	// widgets that were opened and are read on the next game tick
	private boolean adventureLogLoaded;
	/**
	 * The ledger as it was when the Boss Kill Log opened, until the log is read; null when none opened.
	 */
	private Catchup.Stamp killLogOpened;
	private String houseOwner;
	/**
	 * Game ticks a collection log page is given to settle before it is checked: the server has the game draw a page and sends its
	 * numbers and items around the same time, sometimes just after (then the page is drawn again, or its counts change under it).  A
	 * page the player leaves sooner is not checked, so clicking quickly through the pages checks only the one stopped at.
	 */
	static final int SETTLE_TICKS = 2;
	/**
	 * The player variables a collection log page draws its counts from (the same three for every page).
	 */
	private static final int[] PAGE_COUNT_VARPS = {VarPlayerID.COLLECTION_CATEGORY_COUNT, VarPlayerID.COLLECTION_CATEGORY_COUNT2,
		VarPlayerID.COLLECTION_CATEGORY_COUNT3};

	/**
	 * A collection log page as it was drawn, waiting to settle.
	 */
	private static final class DrawnPage
	{
		final GameReader.LogPage page;
		final int tick;
		/**
		 * The ledger as it was when the page was drawn.
		 */
		final Catchup.Stamp stamp;
		/**
		 * The values of {@link #PAGE_COUNT_VARPS} when it was drawn.
		 */
		final int[] varps;

		DrawnPage(GameReader.LogPage page, int tick, Catchup.Stamp stamp, int[] varps)
		{
			this.page = page;
			this.tick = tick;
			this.stamp = stamp;
			this.varps = varps;
		}
	}

	private DrawnPage drawnPage;
	private boolean offeredHistory;
	private boolean scanChecked;
	/**
	 * Whether RuneLite's Loot Tracker plugin is on, looked at every few ticks.
	 */
	private boolean lootTrackerOn = true;
	private int lootTrackerCheckedTick = Integer.MIN_VALUE / 2;
	/**
	 * The last Fortis Colosseum wave completed (0: none since the last claim): the wave a claim is made at.
	 */
	private int colosseumWave;

	/**
	 * @param dir      the plugin's data folder
	 * @param executor RuneLite's shared background threads
	 */
	Tracker(Game game, DropLuckLedgerConfig config, Filepath dir, Gson gson, ScheduledExecutorService executor)
	{
		this.game = game;
		this.config = config;
		this.dir = dir;
		this.gson = gson;
		this.executor = executor;
	}

	// ------------------------------------------------------------------ lifecycle

	// for the tests
	TrackingState state()
	{
		return state;
	}

	Core core()
	{
		return core;
	}

	LedgerPanel panel()
	{
		return panel;
	}

	LedgerPanel.Host host()
	{
		return new PanelHost();
	}

	/**
	 * Builds the side panel and starts reading the boss data in the background.
	 *
	 * @return the side panel, to put in RuneLite's toolbar
	 */
	LedgerPanel start()
	{
		final ExecutorService owner;
		synchronized (lifecycle)
		{
			state = TrackingState.STARTING;
			boundKey = null;
			offeredHistory = false;
			scanChecked = false;
			owner = Executors.newSingleThreadExecutor(r ->
			{
				Thread t = new Thread(r, "drop-luck-ledger-analysis");
				t.setDaemon(true);
				return t;
			});
			analysis = owner;
		}
		final LedgerPanel p = new LedgerPanel(new PanelHost(), owner);
		panel = p;
		executor.execute(() -> load(owner));
		return p;
	}

	/**
	 * Stops recording and writes what is waiting to disk (in the background).
	 */
	void stop()
	{
		final Core c;
		synchronized (lifecycle)
		{
			bindGeneration++;
			boundKey = null;
			c = core;
			core = null;
			state = TrackingState.STARTING;
			if (iconSaver != null)
			{
				iconSaver.cancel(false);
				iconSaver = null;
			}
			if (analysis != null)
			{
				analysis.shutdownNow();
				analysis = null;
			}
		}
		final LedgerPanel p = panel;
		panel = null;
		if (p != null)
		{
			p.detach();
		}
		if (c != null)
		{
			// the last changes still waiting for the saver are written on the shared background thread
			executor.execute(() -> finish(c));
		}
	}

	/**
	 * Reads the boss data, then builds everything else.  Runs on the background thread.
	 */
	private void load(ExecutorService owner)
	{
		try
		{
			Data data;
			try (InputStream in = Tracker.class.getResourceAsStream(DATA_RESOURCE))
			{
				if (in == null)
				{
					throw new IOException("boss data is missing from the plugin");
				}
				data = Data.load(gson, in);
			}
			if (owner != analysis)
			{
				return; // tracking was switched off while the data was loading
			}
			final Core c = new Core(dir, data, gson, executor, game);
			readIcons(c);
			c.capture.setListener((bossId, item, killNo) -> onDropLogged(c, bossId, item, killNo));
			synchronized (lifecycle)
			{
				if (owner != analysis)
				{
					return;
				}
				core = c;
				iconSaver = executor.scheduleWithFixedDelay(() -> saveIcons(c), ICON_SAVE_PERIOD_S, ICON_SAVE_PERIOD_S, TimeUnit.SECONDS);
				state = TrackingState.LOGGED_OUT;
			}
			SwingUtilities.invokeLater(() ->
			{
				LedgerPanel p = panel;
				if (p != null && core == c)
				{
					p.attach(c.ledger, c.index, c.icons, c.planner);
					p.stateChanged();
				}
			});
			game.invokeLater(() ->
			{
				if (core == c && game.isLoggedIn())
				{
					bindAccount();
				}
			});
		}
		catch (IOException | RuntimeException ex)
		{
			log.warn("Drop Luck Ledger could not start", ex);
		}
	}

	/**
	 * Writes what is waiting and stops the saver (background thread).
	 */
	private void finish(Core c)
	{
		c.saver.setStore(null);
		c.ledger.removeListener(c.saver);
		c.capture.reset(); // loot still waiting for its kill-count message is logged as it is
		c.dropLog.flush();
		saveIcons(c);
	}

	// ------------------------------------------------------------------ account

	void onGameStateChanged(GameState gameState)
	{
		final Core c = core;
		if (c == null)
		{
			return;
		}
		switch (gameState)
		{
			case LOGGED_IN:
				bindAccount();
				break;
			case LOGIN_SCREEN:
				drawnPage = null;
				requestBind(null, TrackingState.LOGGED_OUT);
				break;
			case LOADING:
				houseOwner = null;
				break;
			case HOPPING:
			case CONNECTION_LOST:
				// the server sends the player's values afresh: a page drawn before is not checked against them
				houseOwner = null;
				drawnPage = null;
				break;
			case LOGGING_IN:
				drawnPage = null;
				c.capture.reset();
				colosseumWave = 0;
				break;
			default:
				break;
		}
	}

	/**
	 * Decides which ledger is in use from the account that is logged in and the kind of world.
	 */
	void bindAccount()
	{
		final long hash = game.accountHash();
		if (!game.isStandardWorld())
		{
			requestBind(null, TrackingState.PAUSED);
		}
		else if (hash == -1L)
		{
			requestBind(null, TrackingState.LOGGED_OUT);
		}
		else
		{
			requestBind(Long.toString(hash), TrackingState.LOADING);
		}
	}

	/**
	 * Switches to the ledger of another account (or to none).  The load happens on the background thread; events are
	 * ignored until it is done.
	 *
	 * @param key the account, or null for none
	 * @param why what to tell the player when there is none
	 */
	private void requestBind(String key, TrackingState why)
	{
		final Core c = core;
		if (c == null)
		{
			return;
		}
		if (Objects.equals(key, boundKey) && (key != null || state == why))
		{
			return;
		}
		boundKey = key;
		final int generation = ++bindGeneration;
		offeredHistory = false;
		houseOwner = null;
		adventureLogLoaded = false;
		killLogOpened = null;
		drawnPage = null;
		c.capture.reset();
		c.catchup.clear();
		// what was waiting goes to the account it came from; from now on the loot is logged for the new one (or not at all)
		c.dropLog.setAccount(key == null ? null : Long.parseLong(key));
		if (key == null)
		{
			state = why;
			executor.execute(() ->
			{
				if (generation != bindGeneration)
				{
					return;
				}
				c.saver.setStore(null);
				c.ledger.replaceWith(new Ledger(c.data));
				stateChanged();
			});
			return;
		}
		state = TrackingState.LOADING;
		stateChanged();
		executor.execute(() ->
		{
			if (generation != bindGeneration)
			{
				return;
			}
			FileStore store = new FileStore(dir, FileStore.ledgerName(Long.parseLong(key)));
			c.saver.setStore(null);
			final boolean readable = c.saver.loadInto(store);
			if (generation != bindGeneration)
			{
				return;
			}
			c.saver.setStore(store);
			if (!readable)
			{
				message("Your saved ledger could not be read, so it was set aside and you are starting from an empty one. "
					+ "The old file is in the plugin's folder (its name ends in .unreadable).");
			}
			game.invokeLater(() ->
			{
				if (generation == bindGeneration && core == c)
				{
					c.capture.reset();
					state = TrackingState.TRACKING;
					stateChanged();
					afterBind(c);
				}
			});
		});
	}

	private void stateChanged()
	{
		SwingUtilities.invokeLater(() ->
		{
			LedgerPanel p = panel;
			if (p != null)
			{
				p.stateChanged();
			}
		});
	}

	/**
	 * Client thread, once a ledger is ready: starts the item picture scan and looks for history to offer.
	 */
	private void afterBind(Core c)
	{
		if (!scanChecked)
		{
			scanChecked = true;
			if (System.currentTimeMillis() - c.icons.scannedAt() > ICON_RESCAN_MS)
			{
				Set<String> names = new LinkedHashSet<>();
				for (Boss b : c.data.bosses)
				{
					names.addAll(Catalog.defaultTracked(b));
				}
				c.icons.startScan(names);
			}
		}
		if (!offeredHistory && config.importOnLogin() && c.ledger.activeBosses().isEmpty())
		{
			offeredHistory = true;
			planHistory(c, plan ->
			{
				LedgerPanel p = panel;
				if (p != null && !plan.isEmpty())
				{
					p.offerHistory(plan);
				}
			});
		}
	}

	// ------------------------------------------------------------------ game messages and loot

	void onChatMessage(ChatMessageType type, String message)
	{
		final Core c = core;
		if (c == null || state != TrackingState.TRACKING)
		{
			return;
		}
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM && type != ChatMessageType.TRADE)
		{
			return;
		}
		final int tick = game.tickCount();
		final KcMessages.Kc kc = KcMessages.parseKillCount(message);
		if (kc != null)
		{
			c.capture.onKillCount(kc.label, kc.count, tick);
			return;
		}
		java.util.regex.Matcher wave = WAVE_COMPLETED.matcher(KcMessages.stripTags(message));
		if (wave.find())
		{
			colosseumWave = Integer.parseInt(wave.group(1));
		}
		final String logged = KcMessages.collectionLogItem(message);
		if (logged != null)
		{
			c.capture.onCollectionLog(logged, tick);
		}
		if (KcMessages.isPetMessage(message))
		{
			c.capture.onPetMessage(tick);
		}
	}

	/**
	 * Loot from a kill or an event, as RuneLite's Loot Tracker reports it.
	 *
	 * @param itemIds    the ids of the items received
	 * @param quantities how many of each (same length)
	 * @param metadata   what the Loot Tracker knows about the reward (the raid level, the delve, ...), or null
	 */
	void onLoot(LootRecordType type, String name, int amount, int[] itemIds, int[] quantities, Object metadata)
	{
		final Core c = core;
		if (c == null || state != TrackingState.TRACKING)
		{
			return;
		}
		if (type != LootRecordType.NPC && type != LootRecordType.EVENT)
		{
			return;
		}
		final String bossId = c.index.loot(name);
		if (bossId == null)
		{
			return;
		}
		List<Capture.Stack> stacks = new ArrayList<>();
		for (int i = 0; i < itemIds.length; i++)
		{
			final int id = game.canonicalItemId(itemIds[i]);
			final String item = game.itemName(id);
			if (item != null)
			{
				c.icons.learn(item, id);
				stacks.add(new Capture.Stack(item, quantities[i]));
			}
		}
		c.capture.onLoot(new Capture.Loot(name, amount, stacks, hints(bossId, stacks, metadata), game.tickCount()));
	}

	/**
	 * Boss settings the game shows along with a reward: the raid level, the raid points and the team, the delve, the wave, the
	 * player's skill levels, whether the player was the MVP, how many brothers or moons were defeated, whether the loot was the player's.
	 *
	 * @param stacks the items, named as the game names them
	 */
	Map<String, Object> hints(String bossId, List<Capture.Stack> stacks, Object metadata)
	{
		Map<String, Object> hints = new HashMap<>();
		switch (bossId)
		{
			case "chambers-of-xeric":
			{
				// the player's own points this raid, which the unique chance depends on (the game keeps them until the raid is left)
				int points = game.varp(VarPlayerID.RAIDS_PLAYERSCORE);
				if (points > 0)
				{
					hints.put("points", points);
				}
				break;
			}
			case "theatre-of-blood":
			{
				// the players in the raid, as RuneLite's own plugins count them
				int team = 0;
				for (int v : new int[] {VarbitID.TOB_CLIENT_P0, VarbitID.TOB_CLIENT_P1, VarbitID.TOB_CLIENT_P2, VarbitID.TOB_CLIENT_P3, VarbitID.TOB_CLIENT_P4})
				{
					team += Math.min(game.varbit(v), 1);
				}
				if (team > 0)
				{
					hints.put("team", team);
				}
				break;
			}
			case "tombs-of-amascut":
				// the Loot Tracker gives the raid level, the team size and the damage done
				if (metadata instanceof int[] && ((int[]) metadata).length > 0)
				{
					hints.put("raidLevel", ((int[]) metadata)[0]);
				}
				break;
			case "scurrius":
				// only the MVP (or a solo player) gets the rat meat
				hints.put("mvp", has(stacks, "Raw rat meat") ? 1 : 0);
				break;
			case "nex":
			case "the-nightmare":
				// big bones only drop for the MVP
				hints.put("mvp", has(stacks, "Big bones") ? 1 : 0);
				break;
			case "revenant-maledictus":
			{
				// a player who did not deal the most damage gets only blighted supplies
				boolean onlySupplies = !stacks.isEmpty();
				for (Capture.Stack st : stacks)
				{
					onlySupplies &= st.name.startsWith("Blighted ");
				}
				hints.put("looted", onlySupplies ? 0 : 100);
				break;
			}
			case "brutus":
			case "bryophyta":
				hints.put("members", game.isMembersWorld() ? 1 : 0);
				break;
			case "barrows":
			{
				int brothers = 0;
				for (int v : new int[] {VarbitID.BARROWS_KILLED_AHRIM, VarbitID.BARROWS_KILLED_DHAROK, VarbitID.BARROWS_KILLED_GUTHAN,
					VarbitID.BARROWS_KILLED_KARIL, VarbitID.BARROWS_KILLED_TORAG, VarbitID.BARROWS_KILLED_VERAC})
				{
					if (game.varbit(v) > 0)
					{
						brothers++;
					}
				}
				if (brothers > 0)
				{
					hints.put("brothers", brothers);
				}
				break;
			}
			case "moons-of-peril":
			{
				int blood = game.varbit(VarbitID.PMOON_BOSS_BLOOD_DEAD);
				int blue = game.varbit(VarbitID.PMOON_BOSS_BLUE_DEAD);
				int eclipse = game.varbit(VarbitID.PMOON_BOSS_ECLIPSE_DEAD);
				if (blood > 0 || blue > 0 || eclipse > 0)
				{
					hints.put("blood", blood > 0 ? 1 : 0);
					hints.put("blue", blue > 0 ? 1 : 0);
					hints.put("eclipse", eclipse > 0 ? 1 : 0);
				}
				break;
			}
			case COLOSSEUM:
				// the chest is claimed between waves: the last wave completed is the wave claimed at
				if (colosseumWave > 0)
				{
					hints.put("waves", colosseumWave);
					colosseumWave = 0;
				}
				break;
			case "doom-of-mokhaiotl":
				if (metadata instanceof Integer)
				{
					hints.put("delve", metadata);
				}
				break;
			case "tempoross":
				hints.put("fishing", game.realLevel(Skill.FISHING));
				break;
			case "hespori":
				hints.put("farming", game.realLevel(Skill.FARMING));
				break;
			default:
				break;
		}
		return hints;
	}

	private static boolean has(List<Capture.Stack> stacks, String item)
	{
		for (Capture.Stack st : stacks)
		{
			if (st.name.equalsIgnoreCase(item))
			{
				return true;
			}
		}
		return false;
	}

	private void onDropLogged(Core c, String bossId, String item, int killNo)
	{
		if (!config.chatMessages())
		{
			return;
		}
		BossState s = c.ledger.copyOf(bossId);
		game.gameMessage(DropMessages.build(c.data, bossId, s, item, killNo));
	}

	// ------------------------------------------------------------------ history from the game's own screens

	/**
	 * An interface opened.
	 */
	void onWidgetLoaded(int groupId)
	{
		switch (groupId)
		{
			case InterfaceID.MENU:
			case InterfaceID.MENU_NEW:
				adventureLogLoaded = true;
				break;
			case InterfaceID.KILL_LOG:
			{
				// the server sends the counts as the log opens: a kill the ledger takes after this is not in them
				Core c = core;
				killLogOpened = c == null ? null : c.catchup.stamp();
				break;
			}
			default:
				break;
		}
	}

	void onGameTick()
	{
		final Core c = core;
		if (c == null)
		{
			return;
		}
		if (state != TrackingState.TRACKING)
		{
			adventureLogLoaded = false;
			killLogOpened = null;
			return;
		}
		final int tick = game.tickCount();
		if (tick - lootTrackerCheckedTick >= LOOT_TRACKER_CHECK_TICKS || tick < lootTrackerCheckedTick)
		{
			lootTrackerCheckedTick = tick;
			boolean on = game.isLootTrackerOn();
			if (!on && lootTrackerOn)
			{
				message("RuneLite's Loot Tracker plugin is off, so drops are not recorded automatically (kill counts still are). "
					+ "Turn it on in RuneLite's plugin list to record drops.");
			}
			lootTrackerOn = on;
		}
		c.capture.onTick(tick, lootTrackerOn);
		if (c.icons.isScanning() && c.icons.scanTick(System.currentTimeMillis()))
		{
			saveIcons(c);
		}
		if (adventureLogLoaded)
		{
			adventureLogLoaded = false;
			String owner = GameReader.adventureLogOwner(game);
			if (owner != null)
			{
				houseOwner = owner;
			}
		}
		if (killLogOpened != null)
		{
			Catchup.Stamp opened = killLogOpened;
			killLogOpened = null;
			Map<String, Integer> kills = isMine(houseOwner) ? GameReader.killLog(game) : null;
			if (kills != null && !kills.isEmpty())
			{
				// the log comes in one piece from the server: it is checked at once, and nothing changes until the player agrees
				c.catchup.addKillLog(kills, opened);
				offerSync(c, "Boss Kill Log read");
			}
		}
		if (drawnPage != null && tick - drawnPage.tick >= SETTLE_TICKS)
		{
			DrawnPage d = drawnPage;
			drawnPage = null;
			settled(c, d);
		}
	}

	/**
	 * A collection log page has had time to settle: its items are checked against the ledger if they are the ones the game holds for
	 * the page now.
	 */
	private void settled(Core c, DrawnPage d)
	{
		GameReader.LogPage page = d.page;
		// the boss kill counts under the title, as the game holds them now
		Map<String, Integer> shown = new LinkedHashMap<>();
		for (Map.Entry<String, Integer> e : page.counts.entrySet())
		{
			if (c.index.kcShown(e.getKey()) != null)
			{
				shown.put(e.getKey(), e.getValue());
			}
		}
		Map<String, Integer> counts = GameReader.settledCounts(shown, d.varps, pageCountVarps());
		boolean countsSettled = counts.size() == shown.size();
		boolean bodyTypeSwap = game.varbit(VarbitID.COLLECTION_PLAYER_BODYTYPE) == 1;
		boolean itemsSettled = GameReader.itemsMatch(page, game.inventory(InventoryID.COLLECTION_TRANSMIT), bodyTypeSwap);
		if (!countsSettled || !itemsSettled)
		{
			log.debug("Collection Log {}: {} of {} counts settled, items {}", page.title, counts.size(), shown.size(), itemsSettled ? "settled" : "not settled");
		}
		// what settled is checked: a count that did not leaves its boss as it is, and items that did not take part at all
		if (!itemsSettled && (counts.isEmpty() || !countsSettled))
		{
			historyRead("Collection Log, " + page.title + ": it was still loading, so it was not checked. Open it again to check it.");
			return;
		}
		Collection<String> listed = itemsSettled ? page.ids.keySet() : Collections.<String>emptyList();
		if (!c.catchup.unchangedSince(d.stamp, listed, counts.keySet()))
		{
			// a kill or a drop came while the page opened (or a list was added): its numbers may be older than the ledger's
			historyRead("Collection Log, " + page.title + ": your ledger changed while it opened, so it was not checked. Open it again to check it.");
			return;
		}
		c.catchup.addPage(page.title, counts, itemsSettled ? page.items : Collections.<String, Integer>emptyMap(), listed, d.stamp);
		offerSync(c, !itemsSettled ? "Collection Log, " + page.title + ": its items were still loading, so only its kill count was checked"
			: !countsSettled ? "Collection Log, " + page.title + ": its kill count was still loading, so only its items were checked"
			: "Collection Log page read: " + page.title);
	}

	private int[] pageCountVarps()
	{
		int[] v = new int[PAGE_COUNT_VARPS.length];
		for (int i = 0; i < v.length; i++)
		{
			v[i] = game.varp(PAGE_COUNT_VARPS[i]);
		}
		return v;
	}

	/**
	 * Works out what the game's records read so far would change and offers it in the panel; when nothing would change, says the
	 * page was read.
	 *
	 * @param read what was just read, for the note when the ledger already matches
	 */
	private void offerSync(Core c, String read)
	{
		HistoryPlanner.Plan plan = c.catchup.plan();
		LedgerPanel p = panel;
		if (p == null)
		{
			return;
		}
		if (Catchup.worthShowing(plan))
		{
			String text = Catchup.describe(plan);
			SwingUtilities.invokeLater(() -> p.syncReady(plan, text));
		}
		else
		{
			historyRead(read + ". Your ledger matches it.");
		}
	}

	private void historyRead(String text)
	{
		SwingUtilities.invokeLater(() ->
		{
			LedgerPanel p = panel;
			if (p != null)
			{
				p.historyRead(text);
			}
		});
	}

	/**
	 * A game script finished running.
	 */
	void onScriptPostFired(int scriptId)
	{
		final Core c = core;
		if (c == null || state != TrackingState.TRACKING || scriptId != ScriptID.COLLECTION_DRAW_LIST)
		{
			return;
		}
		if (!ownLogOpen())
		{
			return;
		}
		GameReader.LogPage page = GameReader.collectionPage(game);
		if (page == null)
		{
			return;
		}
		for (Map.Entry<String, Integer> e : page.ids.entrySet())
		{
			c.icons.learn(e.getKey(), e.getValue());
		}
		// checked once it has settled; a page drawn again before then (the next page, or this one with its items) replaces it
		drawnPage = new DrawnPage(page, game.tickCount(), c.catchup.stamp(), pageCountVarps());
	}

	/**
	 * True when the collection log on screen is the player's own: not one opened from the book in someone else's house.
	 */
	private boolean ownLogOpen()
	{
		if (game.varbit(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 0)
		{
			return true;
		}
		return houseOwner != null && houseOwner.equals(game.playerName());
	}

	/**
	 * True unless the open adventure log belongs to another player.
	 */
	private boolean isMine(String owner)
	{
		return owner == null || owner.equals(game.playerName());
	}

	/**
	 * Gathers everything the game and RuneLite know about the player's history and works out what it would add.  Client
	 * thread; the result is handed to the callback on the Swing thread.
	 */
	private void planHistory(Core c, Consumer<HistoryPlanner.Plan> then)
	{
		game.invoke(() ->
		{
			HistoryPlanner.Plan plan;
			try
			{
				HistoryInput in = HistorySources.collect(game, gson, c.index);
				plan = c.planner.plan(in);
			}
			catch (RuntimeException ex)
			{
				log.warn("Could not gather history", ex);
				return;
			}
			SwingUtilities.invokeLater(() -> then.accept(plan));
		});
	}

	// ------------------------------------------------------------------ shutdown and icons

	/**
	 * RuneLite is closing: writes everything now.
	 *
	 * @return the write, for RuneLite to wait for, or null when there is nothing to write
	 */
	Future<?> flushForShutdown()
	{
		final Core c = core;
		if (c == null)
		{
			return null;
		}
		return executor.submit(() ->
		{
			c.saver.flushNow();
			c.dropLog.flush();
			saveIcons(c);
		});
	}

	private void readIcons(Core c)
	{
		try
		{
			String text = c.iconStore.read();
			if (text == null)
			{
				return;
			}
			JsonObject root = new JsonParser().parse(text).getAsJsonObject();
			Map<String, Integer> ids = new HashMap<>();
			JsonObject o = root.getAsJsonObject("ids");
			if (o != null)
			{
				for (Map.Entry<String, JsonElement> e : o.entrySet())
				{
					ids.put(e.getKey(), e.getValue().getAsInt());
				}
			}
			long scannedAt = root.has("scannedAt") ? root.get("scannedAt").getAsLong() : 0;
			c.icons.restore(ids, scannedAt);
		}
		catch (IOException | JsonParseException | IllegalStateException | ClassCastException | NumberFormatException ex)
		{
			log.debug("Could not read the saved item pictures; they will be found again", ex);
		}
	}

	private void saveIcons(Core c)
	{
		if (!c.icons.isDirty())
		{
			return;
		}
		try
		{
			JsonObject root = new JsonObject();
			root.addProperty("v", 1);
			root.addProperty("scannedAt", c.icons.scannedAt());
			JsonObject o = new JsonObject();
			for (Map.Entry<String, Integer> e : c.icons.snapshot().entrySet())
			{
				o.addProperty(e.getKey(), e.getValue());
			}
			root.add("ids", o);
			c.iconStore.write(gson.toJson(root));
		}
		catch (IOException | RuntimeException ex)
		{
			log.debug("Could not save the item pictures", ex);
		}
	}

	// ------------------------------------------------------------------ what the side panel can ask for

	private final class PanelHost implements LedgerPanel.Host
	{
		@Override
		public TrackingState state()
		{
			return state;
		}

		@Override
		public void planHistory(Consumer<HistoryPlanner.Plan> then)
		{
			Core c = core;
			if (c != null && state == TrackingState.TRACKING)
			{
				Tracker.this.planHistory(c, then);
			}
		}

		@Override
		public int[] applySync(HistoryPlanner.Plan plan)
		{
			Core c = core;
			if (c == null || state != TrackingState.TRACKING)
			{
				return new int[4];
			}
			int[] done = c.catchup.apply(plan);
			// pages read after the list was made make the next one
			HistoryPlanner.Plan next = c.catchup.plan();
			LedgerPanel p = panel;
			if (p != null && Catchup.worthShowing(next))
			{
				String text = Catchup.describe(next);
				SwingUtilities.invokeLater(() -> p.syncReady(next, text));
			}
			return done;
		}

		@Override
		public void dismissSync()
		{
			Core c = core;
			if (c != null)
			{
				c.catchup.clear();
			}
		}

		@Override
		public void exportBackup(Component parent)
		{
			final Core c = core;
			if (c == null)
			{
				return;
			}
			final Filepath file = game.chooseFileToSave(parent, "Export Drop Luck Ledger backup", "drop-luck-ledger-backup.json", "Ledger backup (*.json)", "json");
			if (file == null)
			{
				return;
			}
			final String json = LedgerCodec.toJson(gson, c.ledger);
			executor.execute(() ->
			{
				String result;
				try
				{
					FileStore.writeText(file, json);
					result = "Backup saved.";
				}
				catch (IOException ex)
				{
					log.warn("Could not write the backup", ex);
					result = "Could not save the backup: " + ex.getMessage();
				}
				message(result);
			});
		}

		@Override
		public void importBackup(Component parent, Consumer<Ledger> confirm)
		{
			final Core c = core;
			if (c == null)
			{
				return;
			}
			final Filepath file = game.chooseFileToOpen(parent, "Import a Drop Luck Ledger backup", "Ledger backup (*.json)", "json");
			if (file == null)
			{
				return;
			}
			executor.execute(() ->
			{
				try
				{
					Ledger backup = LedgerCodec.fromJson(c.data, FileStore.readText(file));
					SwingUtilities.invokeLater(() -> confirm.accept(backup));
				}
				catch (IOException | LedgerCodec.FormatException | RuntimeException ex)
				{
					log.debug("Could not read the backup", ex);
					message("That file is not a Drop Luck Ledger backup (" + ex.getMessage() + ").");
				}
			});
		}

		@Override
		public void replaceLedger(Ledger backup)
		{
			Core c = core;
			if (c != null && state == TrackingState.TRACKING)
			{
				executor.execute(() -> c.ledger.replaceWith(backup));
			}
		}

		@Override
		public void backfill(String bossId, String item)
		{
			final Core c = core;
			if (c == null || state != TrackingState.TRACKING)
			{
				return;
			}
			executor.execute(() ->
			{
				try
				{
					Backfill.Result r = Backfill.apply(c.ledger, c.index, bossId, item, c.dropLog.read(bossId));
					if (!r.isEmpty())
					{
						done(backfillText(item, r));
					}
				}
				catch (IOException ex)
				{
					log.warn("Could not read the drop log", ex);
				}
			});
		}

		@Override
		public void eraseDropLog()
		{
			final Core c = core;
			if (c == null || state != TrackingState.TRACKING)
			{
				return;
			}
			executor.execute(() ->
			{
				try
				{
					c.dropLog.erase();
				}
				catch (IOException ex)
				{
					log.warn("Could not delete the drop log", ex);
				}
			});
		}
	}

	/**
	 * What the drop log brought in for an item just tracked: "Tanzanite fang: 2 copies you got before you tracked it were added from
	 * the drop log, at the kills they came on."
	 */
	static String backfillText(String item, Backfill.Result r)
	{
		StringBuilder b = new StringBuilder(item).append(": ");
		if (r.added > 0)
		{
			b.append(r.added == 1 ? "1 copy" : r.added + " copies").append(" you got before you tracked it ").append(r.added == 1 ? "was" : "were")
				.append(" added from the drop log, at the kill").append(r.added == 1 ? " it" : "s they").append(" came on");
		}
		if (r.numbered > 0)
		{
			b.append(r.added > 0 ? "; " : "").append(r.numbered == 1 ? "1 copy" : r.numbered + " copies").append(" from your game history now ")
				.append(r.numbered == 1 ? "has its" : "have their").append(" kill number");
		}
		return b.append('.').toString();
	}

	/**
	 * Shows a short note at the top of the side panel that something was done.
	 */
	private void done(String text)
	{
		SwingUtilities.invokeLater(() ->
		{
			LedgerPanel p = panel;
			if (p != null)
			{
				p.showDone(text);
			}
		});
	}

	/**
	 * Shows a note at the top of the side panel.
	 */
	private void message(String text)
	{
		SwingUtilities.invokeLater(() ->
		{
			LedgerPanel p = panel;
			if (p != null)
			{
				p.showMessage(text);
			}
		});
	}
}

package com.dropluckledger.capture;

import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Data.Param;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Knows how the game names things: which boss a kill-count message or a loot event belongs to, and which mode of the boss
 * it was.  Built from the boss data plus a short list of names that differ in game.
 */
public final class BossIndex
{
	/**
	 * A kill-count label the game prints ("Chambers of Xeric Challenge Mode") and what it says about the kill.
	 */
	public static final class KcLabel
	{
		public final String bossId;
		/**
		 * The label as spelled in the boss data; used as the key for the last count seen.
		 */
		public final String label;
		/**
		 * Boss settings the label implies (for example cm=1).
		 */
		public final Map<String, Object> patch;

		KcLabel(String bossId, String label, Map<String, Object> patch)
		{
			this.bossId = bossId;
			this.label = label;
			this.patch = patch;
		}
	}

	/**
	 * Extra kill-count labels: game wording that is not in the boss data (normalised form to boss id).
	 */
	private static final String[][] KC_ALIASES = {
		{"Barrows chest", "barrows"},
		{"Barrows chests", "barrows"},
		{"Lunar Chests", "moons-of-peril"},
		{"Grotesque Guardian", "grotesque-guardians"}, // the singular, as the collection log words it
		{"Fortis Colosseum", "fortis-colosseum"},
		{"Colosseum", "fortis-colosseum"},
	};

	/**
	 * Names that loot events carry for a boss, when they are not the boss name or a kill-count label.
	 */
	private static final String[][] LOOT_ALIASES = {
		{"Dusk", "grotesque-guardians"},
		{"Dawn", "grotesque-guardians"},
		{"Crystalline Hunllef", "the-gauntlet"},
		{"Corrupted Hunllef", "the-corrupted-gauntlet"},
		{"Reward pool (Tempoross)", "tempoross"},
		{"Barrows", "barrows"},
		{"Lunar Chest", "moons-of-peril"},
		{"Fortis Colosseum", "fortis-colosseum"},
		{"Sol Heredit", "fortis-colosseum"},
		{"Vet'ion Reborn", "vetion"},
		{"Hueycoatl body", "the-hueycoatl"},
	};

	private static final String SCROLL_BOX = "Scroll box";
	private static final String CLUE_SCROLL = "Clue scroll";

	private final Data data;
	private final Map<String, KcLabel> kcByNorm = new HashMap<>();
	private final Set<String> kcAmbiguous = new HashSet<>();
	private final Map<String, String> lootByNorm = new HashMap<>();
	private final Set<String> lootAmbiguous = new HashSet<>();
	private final Map<String, List<KcLabel>> labelsOf = new LinkedHashMap<>();
	private final Map<String, List<String>> lootNamesOf = new LinkedHashMap<>();
	private final Map<String, Map<String, String>> itemsOf = new HashMap<>();
	/**
	 * Boss id to the normalised names of the other monsters whose loot is recorded under it without counting a kill.
	 */
	private final Map<String, Set<String>> extraLootOf = new HashMap<>();

	public BossIndex(Data data)
	{
		this.data = data;
		for (Boss b : data.bosses)
		{
			List<KcLabel> labels = new ArrayList<>();
			for (String label : b.kc)
			{
				KcLabel kl = new KcLabel(b.id, label, patchFor(b, label));
				labels.add(kl);
				addKc(Names.norm(label), kl);
			}
			if (labels.isEmpty())
			{
				KcLabel kl = new KcLabel(b.id, b.name, new LinkedHashMap<>());
				labels.add(kl);
				addKc(Names.norm(b.name), kl);
			}
			labelsOf.put(b.id, Collections.unmodifiableList(labels));
			addKc(Names.norm(b.name), labels.get(0)); // the page name: the main kill count
			addKc(Names.norm(stripParens(b.name)), labels.get(0));

			LinkedHashSet<String> names = new LinkedHashSet<>();
			names.add(b.name);
			names.add(stripParens(b.name));
			names.addAll(b.kc);
			lootNamesOf.put(b.id, new ArrayList<>(names));
			for (String n : names)
			{
				addLoot(Names.norm(n), b.id);
			}
		}
		for (String[] a : KC_ALIASES)
		{
			Boss b = data.boss(a[1]);
			if (b != null)
			{
				addKc(Names.norm(a[0]), labelsOf.get(b.id).get(0));
			}
		}
		for (Boss b : data.bosses)
		{
			for (String n : b.extraLoot)
			{
				addLoot(Names.norm(n), b.id);
				extraLootOf.computeIfAbsent(b.id, k -> new HashSet<>()).add(Names.norm(n));
				if (!lootNamesOf.get(b.id).contains(n))
				{
					lootNamesOf.get(b.id).add(n);
				}
			}
		}
		for (String[] a : LOOT_ALIASES)
		{
			if (data.boss(a[1]) != null)
			{
				addLoot(Names.norm(a[0]), a[1]);
				List<String> names = lootNamesOf.get(a[1]);
				if (!names.contains(a[0]))
				{
					names.add(a[0]);
				}
			}
		}
	}

	private void addKc(String norm, KcLabel kl)
	{
		if (norm.isEmpty() || kcAmbiguous.contains(norm))
		{
			return;
		}
		KcLabel old = kcByNorm.get(norm);
		if (old == null)
		{
			kcByNorm.put(norm, kl);
		}
		else if (!old.bossId.equals(kl.bossId))
		{
			kcByNorm.remove(norm);
			kcAmbiguous.add(norm);
		}
	}

	private void addLoot(String norm, String bossId)
	{
		if (norm.isEmpty() || lootAmbiguous.contains(norm))
		{
			return;
		}
		String old = lootByNorm.get(norm);
		if (old == null)
		{
			lootByNorm.put(norm, bossId);
		}
		else if (!old.equals(bossId))
		{
			lootByNorm.remove(norm);
			lootAmbiguous.add(norm);
		}
	}

	private static String stripParens(String s)
	{
		int i = s.indexOf('(');
		return i > 0 ? s.substring(0, i).trim() : s;
	}

	private static Param param(Boss b, String name)
	{
		for (Param p : b.params)
		{
			if (p.name.equals(name))
			{
				return p;
			}
		}
		return null;
	}

	/**
	 * The boss settings a kill-count label implies: awakened or not, challenge mode or not, Theatre of Blood mode.
	 */
	public static Map<String, Object> patchOf(Boss b, String label)
	{
		return patchFor(b, label);
	}

	static Map<String, Object> patchFor(Boss b, String label)
	{
		Map<String, Object> p = new LinkedHashMap<>();
		String l = label.toLowerCase(java.util.Locale.ROOT);
		Param aw = param(b, "awakened");
		if (aw != null && "bool".equals(aw.type))
		{
			p.put("awakened", l.contains("awakened") ? 1 : 0);
		}
		Param cm = param(b, "cm");
		if (cm != null && "bool".equals(cm.type))
		{
			p.put("cm", l.contains("challenge mode") ? 1 : 0);
		}
		Param mode = param(b, "mode");
		if (mode != null && "select".equals(mode.type) && mode.options != null)
		{
			String v = l.contains("hard mode") ? "hard" : l.contains("entry mode") ? "entry" : "normal";
			if (mode.options.contains(v))
			{
				p.put("mode", v);
			}
		}
		return p;
	}

	// ------------------------------------------------------------------ lookups

	/**
	 * The kill-count label for the text the game prints between "Your" and "kill count" (null = not a tracked boss).
	 */
	public KcLabel kc(String gameLabel)
	{
		String n = Names.norm(gameLabel);
		KcLabel kl = kcByNorm.get(n);
		if (kl != null)
		{
			return kl;
		}
		// "Awakened The Leviathan", "The Leviathan (Awakened)" and similar spellings of the awakened versions
		String lower = gameLabel == null ? "" : gameLabel.toLowerCase(java.util.Locale.ROOT);
		if (lower.contains("awakened"))
		{
			String rest = Names.norm(lower.replace("awakened", ""));
			KcLabel base = kcByNorm.get(rest);
			if (base != null && param(data.boss(base.bossId), "awakened") != null)
			{
				Map<String, Object> patch = new LinkedHashMap<>(base.patch);
				patch.put("awakened", 1);
				return new KcLabel(base.bossId, "Awakened " + base.label, patch);
			}
		}
		return null;
	}

	/**
	 * The words the game's screens put after the activity in a count ("Zulrah kills", "Barrows Chests opened", "Chambers of
	 * Xeric completions"), longest first.
	 */
	private static final String[] SHOWN_SUFFIXES = {" kill count", " completion count", " kills", " kill", " completions",
		" completion", " completed", " opened", " count"};

	/**
	 * The kill-count label for a count the game shows on a screen: a row of the Boss Kill Log ("Chambers of Xeric: Challenge
	 * Mode") or a line of a collection log page ("Zulrah kills", "Chambers of Xeric (CM) completions").
	 *
	 * @return null when it is not a count of a tracked boss
	 */
	public KcLabel kcShown(String shown)
	{
		if (shown == null)
		{
			return null;
		}
		String s = shown.trim();
		KcLabel kl = kc(s);
		if (kl != null)
		{
			return kl;
		}
		String lower = s.toLowerCase(java.util.Locale.ROOT);
		for (String suffix : SHOWN_SUFFIXES)
		{
			if (lower.endsWith(suffix) && lower.length() > suffix.length())
			{
				s = s.substring(0, s.length() - suffix.length()).trim();
				break;
			}
		}
		// short forms of the modes: "(CM)", "(HM)", "(Entry)"
		s = s.replaceAll("(?i)\\(\\s*cm\\s*\\)", "Challenge Mode")
			.replaceAll("(?i)\\(\\s*hm\\s*\\)", "Hard Mode")
			.replaceAll("(?i)\\(\\s*(hard|entry|expert)\\s*\\)", "$1 Mode");
		return kc(s);
	}

	/**
	 * The boss a loot event name belongs to (null = not a boss we track).
	 */
	public String loot(String lootName)
	{
		return lootByNorm.get(Names.norm(lootName));
	}

	/**
	 * True when a loot event of this name is the loot of another monster that counts for the boss (a God Wars bodyguard): it is
	 * recorded, but it is not a kill of the boss.
	 */
	public boolean isExtraLoot(String bossId, String lootName)
	{
		Set<String> s = extraLootOf.get(bossId);
		return s != null && s.contains(Names.norm(lootName));
	}

	/**
	 * Every kill-count label of a boss, in the order of the boss data (the first one is the main mode).
	 */
	public List<KcLabel> labels(String bossId)
	{
		List<KcLabel> l = labelsOf.get(bossId);
		return l == null ? Collections.emptyList() : l;
	}

	/**
	 * Normalised names that two bosses both claim (the lookups return nothing for them).
	 */
	public Set<String> ambiguousKc()
	{
		return Collections.unmodifiableSet(kcAmbiguous);
	}

	public Set<String> ambiguousLoot()
	{
		return Collections.unmodifiableSet(lootAmbiguous);
	}

	/**
	 * The boss's own name for an item the game names (exact match first, then ignoring case and punctuation).  Null when
	 * the boss has no such item.
	 */
	public String item(String bossId, String gameName)
	{
		if (gameName == null)
		{
			return null;
		}
		Boss b = data.boss(bossId);
		if (b == null)
		{
			return null;
		}
		if (b.meta().containsKey(gameName))
		{
			return gameName;
		}
		Map<String, String> flat;
		synchronized (itemsOf)
		{
			flat = itemsOf.get(bossId);
			if (flat == null)
			{
				flat = new HashMap<>();
				for (String n : b.meta().keySet())
				{
					flat.putIfAbsent(Names.flat(n), n);
				}
				// the wiki names a few items differently from the game ("Tooth half of key (moon key)" is "Tooth half of key")
				for (Data.Row r : b.allRows())
				{
					String game = r.attr("game");
					if (game != null && !game.isEmpty())
					{
						flat.putIfAbsent(Names.flat(game), r.name);
					}
				}
				itemsOf.put(bossId, flat);
			}
		}
		String found = flat.get(Names.flat(gameName));
		if (found == null && gameName.startsWith(SCROLL_BOX))
		{
			// since July 2025 monsters drop a scroll box in place of a clue scroll (once X Marks the Spot is done)
			found = flat.get(Names.flat(CLUE_SCROLL + gameName.substring(SCROLL_BOX.length())));
		}
		return found;
	}
}

package com.dropluckledger.capture;

import com.dropluckledger.capture.BossIndex.KcLabel;
import com.dropluckledger.engine.Catalog;
import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Data.Param;
import com.dropluckledger.engine.Engine;
import com.dropluckledger.ledger.BossState;
import com.dropluckledger.ledger.Drop;
import com.dropluckledger.ledger.Ledger;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Turns what the game reports (kill-count messages, loot, collection log and pet messages) into ledger entries.
 * <p>
 * The game tells the plugin the same kill in two ways, in either order: the chat line "Your X kill count is: N" and the
 * loot event.  The chat line is the better source for the kill number, so a loot event that arrives first is counted as
 * a provisional kill and corrected when the chat line follows.  A few bosses work differently, as their data says
 * ({@link Boss#lootmode}): rewards taken later that never count as kills (Tempoross), runs that only show as loot
 * (Doom of Mokhaiotl), and bosses whose loot goes to the top damage dealer only, where a kill without loot paid another player.
 * Everything here runs on the game thread, except adding the counts the player agreed to from a screen ({@link #onShownCount}); the
 * methods are synchronized, and the ledger takes care of its own locking.
 */
public final class Capture
{
	private static final Logger log = LoggerFactory.getLogger(Capture.class);

	/**
	 * How long (in game ticks, 0.6 s each) a kill-count message waits for its loot.
	 */
	static final int SHORT_WINDOW = 100;
	/**
	 * Same for raids, minigames and skilling bosses, where the reward is claimed some time after the kill count shows.
	 */
	static final int LONG_WINDOW = 3000;
	/**
	 * After a raid's kill-count message, how long a collection log or pet message still belongs to the raid: the chest is opened a
	 * minute or two after the last boss dies (the loot itself, when the Loot Tracker reports it, counts from its own tick).
	 */
	static final int RAID_REWARD_WINDOW = 1000;
	/**
	 * For a boss where a kill without loot means something (another player got it, the corpse was destroyed, the loot sacrificed):
	 * how long after the kill-count message the plugin waits for the loot before it decides there was none.  The loot appears a few
	 * ticks after the kill.
	 */
	static final int TOP_WINDOW = 50;
	/**
	 * How close (in ticks) a pet message must be to the kill it belongs to.
	 */
	static final int PET_WINDOW = 30;
	private static final int PROV_DROPS_KEPT = 20;
	/**
	 * A tick far enough in the past that nothing is near it (and subtracting it cannot overflow).
	 */
	private static final int NEVER = -1_000_000_000;

	/**
	 * Called for every drop that was written to the ledger.
	 */
	public interface Listener
	{
		void dropLogged(String bossId, String item, int killNo);
	}

	/**
	 * Told about every loot of a boss, with all its items (tracked or not), once its kill number is settled: the drop log.  Pets,
	 * which do not show in the loot, come as a loot of their own.
	 */
	public interface LootLog
	{
		/**
		 * @param t     epoch milliseconds when the loot came
		 * @param items every item, named as the game names it (a pet with the boss data's name)
		 * @param snap  for items several bosses drop, the other bosses' kill counts; null when none of the items is shared
		 */
		void loot(long t, String bossId, int killNo, List<Stack> items, Map<String, Integer> snap);
	}

	/**
	 * One item stack of a loot event, named the way the game names it.
	 */
	public static final class Stack
	{
		public final String name;
		public final int qty;

		public Stack(String name, int qty)
		{
			this.name = name;
			this.qty = qty;
		}
	}

	/**
	 * A loot event.
	 */
	public static final class Loot
	{
		public final String name;
		public final int amount;
		public final List<Stack> items;
		/**
		 * Boss settings the game revealed with the loot (delve level, skill levels, Colosseum waves), by setting name.
		 */
		public final Map<String, Object> hints;
		public final int tick;

		public Loot(String name, int amount, List<Stack> items, Map<String, Object> hints, int tick)
		{
			this.name = name;
			this.amount = amount;
			this.items = items;
			this.hints = hints == null ? Collections.emptyMap() : hints;
			this.tick = tick;
		}
	}

	private static final class Pending
	{
		final int killNo;
		final int tick;

		Pending(int killNo, int tick)
		{
			this.killNo = killNo;
			this.tick = tick;
		}
	}

	/**
	 * A loot counted as a kill of its own before its kill-count message came: logged once the message settles the kill number.
	 */
	private static final class Held
	{
		final long t;
		final int killNo;
		final List<Stack> items;
		final Map<String, Integer> snap;
		final int tick;

		Held(long t, int killNo, List<Stack> items, Map<String, Integer> snap, int tick)
		{
			this.t = t;
			this.killNo = killNo;
			this.items = items;
			this.snap = snap;
			this.tick = tick;
		}
	}

	private static final class LastKill
	{
		final String bossId;
		final int killNo;
		final int tick;

		LastKill(String bossId, int killNo, int tick)
		{
			this.bossId = bossId;
			this.killNo = killNo;
			this.tick = tick;
		}
	}

	private final Ledger ledger;
	private final Data data;
	private final BossIndex index;
	private final Map<String, List<String>> logIndex;
	private final Map<String, Pending> pending = new HashMap<>();
	/**
	 * Kills of "top damage gets the loot" bosses marked as paying another player, by boss: kill number to the tick the mark was
	 * made, so loot that turns up late can still undo it.
	 */
	private final Map<String, Map<Integer, Integer>> markedNoLoot = new HashMap<>();
	private final Set<String> secondChance = new HashSet<>();
	private LastKill lastKill;
	private int petSeenTick = NEVER;
	private Listener listener;
	private LootLog lootLog;
	private final Map<String, List<Held>> held = new HashMap<>();
	/**
	 * Pets already logged (boss, pet and kill), so that the pet message and the collection log message log it once.
	 */
	private final Set<String> petsLogged = new HashSet<>();
	/**
	 * For a boss that counts the loots of its other monsters (EXTRACOUNT: the God Wars bodyguards), by boss: the kill the loots go to
	 * (the latest one seen since login, as their drops do) and how many have come.  The count is that kill's own setting.
	 */
	private final Map<String, int[]> extraCounted = new HashMap<>();
	/**
	 * Those loots that came before the first kill seen since login: they are counted for that kill.
	 */
	private final Map<String, Integer> extraEarly = new HashMap<>();
	/**
	 * Whether RuneLite's Loot Tracker is on (as of the last tick).  Without it no loot is seen at all, so no kill is taken to have
	 * paid another player.
	 */
	private boolean lootTrackerOn;

	public Capture(Ledger ledger, BossIndex index)
	{
		this.ledger = ledger;
		this.data = ledger.data();
		this.index = index;
		this.logIndex = Catalog.logIndex(data);
	}

	public synchronized void setListener(Listener l)
	{
		this.listener = l;
	}

	public synchronized void setLootLog(LootLog l)
	{
		this.lootLog = l;
	}

	/**
	 * Forget the kills waiting for their loot (login, world hop).
	 */
	public synchronized void reset()
	{
		for (String id : new ArrayList<>(held.keySet()))
		{
			release(id, 0);
		}
		pending.clear();
		markedNoLoot.clear();
		secondChance.clear();
		extraCounted.clear();
		extraEarly.clear();
		lastKill = null;
		petSeenTick = NEVER;
	}

	/**
	 * The most the boss's EXTRACOUNT setting can be (3 bodyguards).
	 */
	private static int extraMax(Boss boss)
	{
		for (Param p : boss.params)
		{
			if (p.name.equals(boss.extraCount))
			{
				return p.max == null ? Integer.MAX_VALUE : (int) Math.round(p.max);
			}
		}
		return Integer.MAX_VALUE;
	}

	/**
	 * A kill of a boss with an EXTRACOUNT setting, seen as it happened: it starts with the loots that came before it since login (none
	 * most of the time), and the ones that come next are added to it.  For callers that hold the boss under {@link Ledger#update}.
	 */
	private void extraKillLocked(BossState s, Boss boss, String bossId, int killNo)
	{
		if (boss.extraCount == null || boss.extraCount.isEmpty())
		{
			return;
		}
		Integer early = extraEarly.remove(bossId);
		int n = Math.min(extraMax(boss), early == null ? 0 : early);
		extraCounted.put(bossId, new int[] {killNo, n});
		Map<String, Object> patch = Collections.singletonMap(boss.extraCount, (Object) n);
		Map<String, Object> defaults = Engine.defaultParams(boss);
		Ledger.setKillParamsLocked(s, killNo, patch, defaults);
		Ledger.noteReadLocked(s, boss, patch, killNo, killNo, defaults);
	}

	/**
	 * A loot of one of the boss's other monsters (a bodyguard): one more for the kill its drops go to, when that kill was seen since
	 * login, or for the next kill.  For callers that hold the boss under {@link Ledger#update}.
	 */
	private void extraLootLocked(BossState s, Boss boss, String bossId, int count)
	{
		int max = extraMax(boss);
		int[] at = extraCounted.get(bossId);
		if (at != null && at[0] == s.kc)
		{
			at[1] = Math.min(max, at[1] + count);
			Ledger.setKillParamsLocked(s, at[0], Collections.singletonMap(boss.extraCount, (Object) at[1]), Engine.defaultParams(boss));
		}
		else
		{
			extraEarly.merge(bossId, count, (a, b) -> Math.min(max, a + b));
		}
	}

	private static boolean longWindow(Boss b)
	{
		String c = b.cat == null ? "" : b.cat;
		return isRaid(b) || c.equals("Minigame") || c.equals("Minigame boss") || c.equals("Skilling boss");
	}

	private static boolean isRaid(Boss b)
	{
		return "Raid".equals(b.cat);
	}

	/**
	 * How long after the last kill a collection log or pet message still belongs to it.
	 */
	private int rewardWindow(LastKill k)
	{
		Boss b = data.boss(k.bossId);
		return b != null && isRaid(b) ? RAID_REWARD_WINDOW : PET_WINDOW;
	}

	private static int window(Boss b)
	{
		return longWindow(b) ? LONG_WINDOW : SHORT_WINDOW;
	}

	// ------------------------------------------------------------------ kill-count messages

	/**
	 * A "Your X kill count is: N" message.
	 *
	 * @param label the activity as the game wrote it
	 * @param n     the count it showed
	 */
	public synchronized void onKillCount(String label, int n, int tick)
	{
		KcLabel kl = index.kc(label);
		if (kl == null || n <= 0)
		{
			log.debug("Kill count for '{}' is not a boss in the ledger", label);
			return;
		}
		final String id = kl.bossId;
		final Boss boss = data.boss(id);
		if (boss.lootIsClaim())
		{
			return; // every claimed reward is one run; the game's own count measures something else
		}
		if (boss.decidesOnLoot())
		{
			Pending old = pending.get(id);
			if (old != null && lootTrackerOn)
			{
				decideNoLoot(id, old, tick); // the previous kill's loot never came
			}
		}
		final Map<String, Object> patch = new LinkedHashMap<>(kl.patch);
		final Boolean[] counted = {false};
		final int[] kill = {0};
		final int[] moved = {0};
		final boolean[] lootFirst = {false};
		ledger.update(id, s ->
		{
			Map<String, Integer> labels = s.labels();
			Integer prev = labels.get(kl.label);
			int cur = s.kc;
			int prov = s.provisional();
			int newKc;
			if (prev == null)
			{
				// first count seen for this label: believe the game's number, but a message always means at least one new kill
				int target = s.labelSum(kl.label) + n;
				newKc = Math.max(prov > 0 ? cur : cur + 1, target);
			}
			else
			{
				if (n <= prev)
				{
					labels.put(kl.label, n); // the game's count went down or repeated: just follow it
					return null;
				}
				newKc = cur + (n - prev) - prov;
			}
			newKc = Math.max(newKc, s.maxDropKc());
			int shift = newKc - cur;
			lootFirst[0] = prov > 0;
			moved[0] = shift;
			if (prov > 0 && shift != 0 && s.provDrops != null)
			{
				for (Drop d : s.drops)
				{
					if (s.provDrops.contains(d.id) && d.kc != null)
					{
						d.kc = Math.max(1, d.kc + shift);
					}
				}
			}
			if (prov > 0 && shift != 0)
			{
				// what the game told about the kills counted from their loot moves with them
				int firstProv = cur - prov + 1;
				if (s.seen != null)
				{
					for (Map.Entry<String, Integer> e : s.seen.entrySet())
					{
						if (e.getValue() >= firstProv)
						{
							e.setValue(Math.max(1, e.getValue() + shift));
						}
					}
				}
				if (s.liveFrom != null && s.liveFrom >= firstProv)
				{
					s.liveFrom = Math.max(1, s.liveFrom + shift);
				}
			}
			labels.put(kl.label, n);
			int gap = newKc - cur;
			s.kc = newKc;
			s.prov = null;
			s.provDrops = null;
			if (s.liveFrom == null)
			{
				s.liveFrom = newKc; // the first kill the plugin saw itself
			}
			// kills the plugin did not see (first count, missed kills) are assumed to be in the same mode as this one
			int from = prov == 0 && gap > 1 ? cur + 1 : newKc;
			Ledger.applyParamsLocked(s, from, patch, Engine.defaultParams(boss));
			Ledger.noteReadLocked(s, boss, patch, newKc, from, Engine.defaultParams(boss));
			extraKillLocked(s, boss, id, newKc);
			kill[0] = newKc;
			counted[0] = true;
			if (prov == 0)
			{
				pending.put(id, new Pending(newKc, tick));
			}
			else if (boss.decidesOnLoot() && !boss.onLoot.isEmpty())
			{
				// the loot came first: this kill's loot is already known
				Ledger.setKillParamsLocked(s, newKc, Boss.settings(boss.onLoot), Engine.defaultParams(boss));
				Ledger.noteReadLocked(s, boss, Boss.settings(boss.onLoot), newKc, newKc, Engine.defaultParams(boss));
			}
			return null;
		});
		if (counted[0])
		{
			if (lootFirst[0])
			{
				release(id, moved[0]);
			}
			killSeen(id, kill[0], tick);
		}
	}

	/**
	 * True while a kill of the boss waits for its loot (a raid's until the chest is opened): its loot will take the kill count as it
	 * then is, so the count is not changed from a screen meanwhile.
	 */
	public synchronized boolean awaitingLoot(String bossId)
	{
		return pending.containsKey(bossId);
	}

	/**
	 * What a count the game showed on screen did to the ledger.
	 */
	public static final class Raised
	{
		public final String bossId;
		/**
		 * The ledger's kill count before the count was read.
		 */
		public final int from;
		/**
		 * The ledger's kill count after.
		 */
		public final int to;

		public Raised(String bossId, int from, int to)
		{
			this.bossId = bossId;
			this.from = from;
			this.to = to;
		}
	}

	/**
	 * A kill count the game shows on a screen (the Boss Kill Log, a collection log page), which the player agreed to add.  It is not a
	 * new kill, but a count higher than the last one the ledger saw for that label means kills the plugin missed (made on another
	 * computer, or with the plugin off).  They are added at once, with no drops on them, as the next kill-count message would add them.
	 * A count the ledger already has, or a lower one, changes nothing.  May be called off the client thread.
	 *
	 * @param shown the activity as the screen wrote it ("Zulrah", "Chambers of Xeric (CM) completions")
	 * @return what changed, or null when the kill count did not
	 */
	public synchronized Raised onShownCount(String shown, int n)
	{
		KcLabel kl = index.kcShown(shown);
		if (kl == null || n <= 0)
		{
			return null;
		}
		final String id = kl.bossId;
		final Boss boss = data.boss(id);
		if (boss == null || boss.lootIsClaim())
		{
			return null; // every claimed reward is one run; the game's own count measures something else
		}
		if (pending.containsKey(id))
		{
			return null; // a kill whose loot is still to come: the next look at the screen catches up instead
		}
		BossState now = ledger.copyOf(id);
		Integer last = now.labelKc == null ? null : now.labelKc.get(kl.label);
		if (last != null && n <= last)
		{
			return null;
		}
		final Map<String, Object> defaults = Engine.defaultParams(boss);
		int[] change = ledger.update(id, s ->
		{
			int[] c = raiseLocked(s, kl.label, n);
			if (c != null)
			{
				// the kills missed are in the mode the label says (normal or awakened, challenge mode ...)
				Ledger.applyParamsLocked(s, c[0] + 1, kl.patch, defaults);
			}
			return c;
		});
		release(id, 0); // the loot counted as kills of their own keeps its kill numbers
		if (change == null)
		{
			return null;
		}
		log.debug("{}: {} kills the ledger missed, from the count on screen", id, change[1] - change[0]);
		return new Raised(id, change[0], change[1]);
	}

	/**
	 * What a count the game shows for one kill-count label makes of a boss's kill count, the same steps whether the ledger is being
	 * changed or a copy of it is being looked at: the kills since the count last seen for the label are added, or, for a label never
	 * seen, the game's count with the other labels' counts.  The labels and the kill count of the state given change.
	 *
	 * @return {kill count before, kill count after}, or null when the count adds no kill
	 */
	public static int[] raiseLocked(BossState s, String label, int n)
	{
		Map<String, Integer> labels = s.labels();
		Integer prev = labels.get(label);
		if (prev != null && n <= prev)
		{
			return null;
		}
		int cur = s.kc;
		// kills counted from their loot alone are in the game's count too
		int target = prev == null ? s.labelSum(label) + n : cur - s.provisional() + (n - prev);
		labels.put(label, n);
		s.prov = null;
		s.provDrops = null;
		if (target <= cur)
		{
			return null;
		}
		s.kc = target;
		return new int[]{cur, target};
	}

	/**
	 * Called every game tick: kills of bosses where a kill without loot means something (see {@link Boss#noLoot}) whose loot has not
	 * come within the wait are marked so.  Nothing is decided while the Loot Tracker is off, because then no loot is seen at all.
	 */
	public synchronized void onTick(int tick, boolean lootTrackerOn)
	{
		this.lootTrackerOn = lootTrackerOn;
		for (String id : new ArrayList<>(held.keySet()))
		{
			Boss b = data.boss(id);
			List<Held> hs = held.get(id);
			if (b == null || !hs.isEmpty() && tick - hs.get(hs.size() - 1).tick > window(b))
			{
				release(id, 0); // the kill-count message never came: the loot keeps the kill number it was counted at
			}
		}
		if (pending.isEmpty() && markedNoLoot.isEmpty())
		{
			return;
		}
		Iterator<Map.Entry<String, Pending>> it = pending.entrySet().iterator();
		List<Object[]> decide = new ArrayList<>();
		while (it.hasNext())
		{
			Map.Entry<String, Pending> e = it.next();
			Boss b = data.boss(e.getKey());
			Pending p = e.getValue();
			if (b == null)
			{
				it.remove();
				continue;
			}
			if (b.decidesOnLoot() && tick - p.tick > TOP_WINDOW)
			{
				it.remove();
				if (lootTrackerOn)
				{
					decide.add(new Object[] {e.getKey(), p});
				}
			}
			else if (tick - p.tick > window(b))
			{
				it.remove();
			}
		}
		for (Object[] d : decide)
		{
			decideNoLoot((String) d[0], (Pending) d[1], tick);
		}
		for (Iterator<Map.Entry<String, Map<Integer, Integer>>> bi = markedNoLoot.entrySet().iterator(); bi.hasNext(); )
		{
			Map<Integer, Integer> m = bi.next().getValue();
			m.values().removeIf(t -> tick - t > SHORT_WINDOW);
			if (m.isEmpty())
			{
				bi.remove();
			}
		}
	}

	private void decideNoLoot(String bossId, Pending p, int tick)
	{
		pending.remove(bossId);
		Boss boss = data.boss(bossId);
		if (boss == null || !boss.decidesOnLoot())
		{
			return;
		}
		ledger.update(bossId, s ->
		{
			Ledger.setKillParamsLocked(s, p.killNo, Boss.settings(boss.noLoot), Engine.defaultParams(boss));
			Ledger.noteReadLocked(s, boss, Boss.settings(boss.noLoot), p.killNo, p.killNo, Engine.defaultParams(boss));
			return null;
		});
		markedNoLoot.computeIfAbsent(bossId, k -> new HashMap<>()).put(p.killNo, tick);
		log.debug("{} kill {}: no loot came ({})", bossId, p.killNo, boss.noLoot);
	}

	// ------------------------------------------------------------------ loot

	/**
	 * Loot from a boss.  Items the player tracks are written to the ledger with the kill number.
	 */
	public void onLoot(Loot e)
	{
		final String id = index.loot(e.name);
		if (id == null)
		{
			return;
		}
		final Boss boss = data.boss(id);
		final boolean extra = boss.lootIsExtra() || index.isExtraLoot(id, e.name);
		final int kills = Math.max(1, e.amount);
		final int[] kill = {0};
		final boolean[] counted = {false};
		List<String> logged;
		synchronized (this)
		{
			logged = ledger.update(id, s ->
			{
				int killNo;
				boolean provisional = false;
				Map<String, Object> patch = hintPatch(boss, e.hints);
				if (extra)
				{
					// rewards of kills already counted (a reward cart, the bodyguards): the latest kill gets them
					killNo = Math.max(1, s.kc);
					if (boss.extraCount != null && !boss.extraCount.isEmpty() && index.isExtraLoot(id, e.name))
					{
						extraLootLocked(s, boss, id, kills);
					}
				}
				else if (boss.lootIsClaim())
				{
					s.kc += kills;
					killNo = s.kc;
				}
				else
				{
					// for a boss where a kill without loot means something, a clue or pet alone is not loot (a sacrifice can still give the pet)
					final boolean regular = !boss.decidesOnLoot() || hasRegularLoot(boss, id, e.items);
					Pending p = pending.remove(id);
					Map<Integer, Integer> marked = markedNoLoot.get(id);
					Integer late = null;
					if (p == null && marked != null && !marked.isEmpty())
					{
						// loot after the plugin had decided there was none: it belongs to that kill after all
						int newest = Collections.max(marked.keySet());
						if (e.tick - marked.get(newest) <= SHORT_WINDOW)
						{
							late = newest;
							if (regular)
							{
								marked.remove(newest);
							}
						}
					}
					if (p != null && e.tick >= p.tick && e.tick - p.tick <= window(boss))
					{
						s.kc += kills - 1;
						killNo = s.kc;
					}
					else if (late != null)
					{
						killNo = late;
					}
					else
					{
						s.kc += kills;
						s.prov = s.provisional() + kills;
						killNo = s.kc;
						provisional = true;
					}
					if (boss.decidesOnLoot() && !provisional)
					{
						Map<String, String> says = regular ? boss.onLoot : boss.noLoot;
						if (!says.isEmpty())
						{
							Ledger.setKillParamsLocked(s, killNo, Boss.settings(says), Engine.defaultParams(boss));
							Ledger.noteReadLocked(s, boss, Boss.settings(says), killNo, killNo, Engine.defaultParams(boss));
						}
					}
				}
				if (!extra && s.liveFrom == null)
				{
					s.liveFrom = killNo;
				}
				Ledger.applyParamsLocked(s, killNo, patch, Engine.defaultParams(boss));
				Ledger.noteReadLocked(s, boss, patch, killNo, killNo, Engine.defaultParams(boss));
				Set<String> tracked = new HashSet<>(ledger.trackedNames(id));
				List<String> out = new ArrayList<>();
				for (Stack stack : e.items)
				{
					String item = index.item(id, stack.name);
					if (item == null || !tracked.contains(item))
					{
						continue;
					}
					if (secondChance.remove(id + '|' + item + '|' + killNo))
					{
						continue; // the collection log message already put this copy in
					}
					Drop d = ledger.addDropLocked(id, s, item, killNo, stack.qty, snapFor(id, item), Drop.SRC_LIVE);
					if (provisional)
					{
						if (s.provDrops == null)
						{
							s.provDrops = new ArrayList<>();
						}
						s.provDrops.add(d.id);
						while (s.provDrops.size() > PROV_DROPS_KEPT)
						{
							s.provDrops.remove(0);
						}
					}
					out.add(item);
				}
				kill[0] = killNo;
				counted[0] = provisional;
				return out;
			});
			logLoot(id, kill[0], e, counted[0]);
			for (String item : logged)
			{
				notifyLogged(id, item, kill[0]);
			}
			if (!extra)
			{
				killSeen(id, kill[0], e.tick);
			}
		}
	}

	/**
	 * True when the loot has anything besides what only the tertiary and pet rolls give.
	 */
	private boolean hasRegularLoot(Boss boss, String bossId, List<Stack> items)
	{
		for (Stack st : items)
		{
			String item = index.item(bossId, st.name);
			if (item == null || !boss.tertiaryOnly().contains(item))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The settings the game revealed with a loot event, restricted to the ones this boss has.
	 */
	static Map<String, Object> hintPatch(Boss boss, Map<String, Object> hints)
	{
		Map<String, Object> out = new LinkedHashMap<>();
		if (hints == null || hints.isEmpty())
		{
			return out;
		}
		for (Param p : boss.params)
		{
			Object v = hints.get(p.name);
			if (v == null)
			{
				continue;
			}
			if ("bool".equals(p.type))
			{
				out.put(p.name, truthy(v) ? 1 : 0);
			}
			else if ("int".equals(p.type) && v instanceof Number)
			{
				long r = Math.round(((Number) v).doubleValue());
				if (p.min != null)
				{
					r = Math.max(r, Math.round(p.min));
				}
				if (p.max != null)
				{
					r = Math.min(r, Math.round(p.max));
				}
				out.put(p.name, (int) r);
			}
			else if ("select".equals(p.type) && v instanceof String && p.options != null && p.options.contains(v))
			{
				out.put(p.name, v);
			}
		}
		return out;
	}

	private static boolean truthy(Object v)
	{
		if (v instanceof Boolean)
		{
			return (Boolean) v;
		}
		if (v instanceof Number)
		{
			return ((Number) v).doubleValue() != 0;
		}
		return v != null;
	}

	/**
	 * For an item that several bosses drop: the other bosses' kill counts right now.
	 */
	private Map<String, Integer> snapFor(String bossId, String item)
	{
		List<String> ids = logIndex.get(item);
		if (ids == null || ids.size() < 2)
		{
			return null;
		}
		Map<String, Integer> snap = new LinkedHashMap<>();
		for (String other : ids)
		{
			if (!other.equals(bossId))
			{
				int k = ledger.kc(other);
				if (k > 0)
				{
					snap.put(other, k);
				}
			}
		}
		return snap.isEmpty() ? null : snap;
	}

	// ------------------------------------------------------------------ the drop log

	/**
	 * Hands the whole loot to the drop log, or holds it while its kill number may still move (the loot came before its kill-count
	 * message).
	 */
	private void logLoot(String bossId, int killNo, Loot e, boolean provisional)
	{
		if (lootLog == null || e.items.isEmpty())
		{
			return;
		}
		List<Stack> items = new ArrayList<>(e.items);
		Held h = new Held(ledger.now(), killNo, items, lootSnap(bossId, items), e.tick);
		if (provisional)
		{
			held.computeIfAbsent(bossId, k -> new ArrayList<>()).add(h);
		}
		else
		{
			emit(bossId, h, 0);
		}
	}

	/**
	 * Logs the loot held for a boss, its kill numbers moved as the kill-count message moved the kills counted from their loot.
	 */
	private void release(String bossId, int shift)
	{
		List<Held> hs = held.remove(bossId);
		if (hs == null)
		{
			return;
		}
		for (Held h : hs)
		{
			emit(bossId, h, shift);
		}
	}

	private void emit(String bossId, Held h, int shift)
	{
		LootLog l = lootLog;
		if (l == null)
		{
			return;
		}
		try
		{
			l.loot(h.t, bossId, Math.max(1, h.killNo + shift), h.items, h.snap);
		}
		catch (RuntimeException ex)
		{
			log.debug("Drop log failed", ex);
		}
	}

	/**
	 * The other bosses' kill counts, for the items of the loot that several bosses drop.
	 */
	private Map<String, Integer> lootSnap(String bossId, List<Stack> items)
	{
		Map<String, Integer> snap = null;
		for (Stack st : items)
		{
			String item = index.item(bossId, st.name);
			Map<String, Integer> s = item == null ? null : snapFor(bossId, item);
			if (s != null)
			{
				if (snap == null)
				{
					snap = new LinkedHashMap<>();
				}
				snap.putAll(s);
			}
		}
		return snap;
	}

	/**
	 * Logs a pet the player got, which never shows in the loot: the one the message names, or the boss's only pet.
	 */
	private void logPet(Boss boss, String bossId, int killNo, String itemName)
	{
		if (lootLog == null)
		{
			return;
		}
		String pet = null;
		if (itemName != null)
		{
			String item = index.item(bossId, itemName);
			if (item == null || !isPet(boss, item))
			{
				return; // other items come with the loot
			}
			pet = item;
		}
		else
		{
			for (Map.Entry<String, Engine.ItemMeta> m : boss.meta().entrySet())
			{
				if (m.getValue().isPet() && !m.getValue().hidden)
				{
					if (pet != null)
					{
						return; // more than one pet: cannot tell which
					}
					pet = m.getKey();
				}
			}
		}
		if (pet == null)
		{
			return;
		}
		if (petsLogged.size() > 200)
		{
			petsLogged.clear();
		}
		if (petsLogged.add(bossId + '|' + pet + '|' + killNo))
		{
			emit(bossId, new Held(ledger.now(), killNo, Collections.singletonList(new Stack(pet, 1)), snapFor(bossId, pet), 0), 0);
		}
	}

	private void notifyLogged(String bossId, String item, int killNo)
	{
		Listener l = listener;
		if (l != null)
		{
			try
			{
				l.dropLogged(bossId, item, killNo);
			}
			catch (RuntimeException ex)
			{
				log.debug("Drop listener failed", ex);
			}
		}
	}

	// ------------------------------------------------------------------ pets and collection log

	/**
	 * A "New item added to your collection log: X" message.  Used for pets, which do not appear in loot events, and as a
	 * second chance for tracked items of the boss that was just killed.
	 */
	public synchronized void onCollectionLog(String itemName, int tick)
	{
		if (itemName == null || lastKill == null || tick - lastKill.tick > rewardWindow(lastKill))
		{
			// the message may come first; remember it only for pets
			return;
		}
		recordIfTracked(lastKill.bossId, lastKill.killNo, itemName);
	}

	/**
	 * A "funny feeling" pet message (it does not say which pet).  Counts when the boss just killed has exactly one pet.
	 */
	public synchronized void onPetMessage(int tick)
	{
		if (lastKill != null && tick - lastKill.tick <= rewardWindow(lastKill))
		{
			recordIfTracked(lastKill.bossId, lastKill.killNo, null);
		}
		else
		{
			petSeenTick = tick;
		}
	}

	private void killSeen(String bossId, int killNo, int tick)
	{
		lastKill = new LastKill(bossId, killNo, tick);
		if (tick - petSeenTick <= PET_WINDOW && tick >= petSeenTick)
		{
			petSeenTick = NEVER;
			recordIfTracked(bossId, killNo, null);
		}
	}

	/**
	 * Logs the item (or the boss's only pet when itemName is null) at the kill, unless that copy is already there.
	 */
	private void recordIfTracked(String bossId, int killNo, String itemName)
	{
		Boss boss = data.boss(bossId);
		if (boss == null)
		{
			return;
		}
		logPet(boss, bossId, killNo, itemName);
		List<String> logged = ledger.update(bossId, s ->
		{
			List<String> tracked = ledger.trackedNames(bossId);
			String item = null;
			if (itemName != null)
			{
				item = index.item(bossId, itemName);
				if (item == null || !tracked.contains(item))
				{
					return Collections.<String>emptyList();
				}
			}
			else
			{
				for (String n : tracked)
				{
					if (isPet(boss, n))
					{
						if (item != null)
						{
							return Collections.<String>emptyList(); // more than one pet: cannot tell which
						}
						item = n;
					}
				}
				if (item == null)
				{
					return Collections.<String>emptyList();
				}
			}
			for (Drop d : s.drops)
			{
				if (d.item.equals(item) && d.kc != null && d.kc == killNo)
				{
					return Collections.<String>emptyList();
				}
			}
			ledger.addDropLocked(bossId, s, item, killNo, 1, snapFor(bossId, item), Drop.SRC_LIVE);
			if (secondChance.size() > 200)
			{
				secondChance.clear();
			}
			secondChance.add(bossId + '|' + item + '|' + killNo);
			return Collections.singletonList(item);
		});
		for (String item : logged)
		{
			notifyLogged(bossId, item, killNo);
		}
	}

	private static boolean isPet(Boss b, String item)
	{
		Engine.ItemMeta m = b.meta().get(item);
		return m != null && m.isPet();
	}
}

package com.dropluckledger.capture;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Recognises the game messages the plugin cares about.  The patterns follow the ones RuneLite's own Chat Commands plugin uses
 * for kill counts, so they match the same wording.
 */
public final class KcMessages
{
	private KcMessages()
	{
	}

	private static final Pattern KILLCOUNT = Pattern.compile("Your (?<pre>completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?(?<boss>.+?)(?:</col>)? (?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)is: ?(?:<col=[0-9a-f]{6}>|@.+?@)(?<kc>[0-9,]+)</col>");
	private static final Pattern COLLECTION_LOG = Pattern.compile("New item added to your collection log: (.*)");
	private static final String[] PET = {
		"You have a funny feeling like you're being followed",
		"You feel something weird sneaking into your backpack",
		"You have a funny feeling like you would have been followed",
	};

	/**
	 * A kill-count message: the text the game used for the activity and the count it shows.
	 */
	public static final class Kc
	{
		public final String label;
		public final int count;

		Kc(String label, int count)
		{
			this.label = label;
			this.count = count;
		}
	}

	/**
	 * @return the label and count, or null when the message is not a kill-count message
	 */
	public static Kc parseKillCount(String message)
	{
		if (message == null)
		{
			return null;
		}
		Matcher m = KILLCOUNT.matcher(message);
		if (!m.find())
		{
			return null;
		}
		String pre = m.group("pre");
		String post = m.group("post");
		if ((pre == null || pre.isEmpty()) && (post == null || post.isEmpty()))
		{
			return null;
		}
		String label = m.group("boss").replace(":", "");
		int n;
		try
		{
			n = Integer.parseInt(m.group("kc").replace(",", ""));
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
		return new Kc(label, n);
	}

	/**
	 * @return the item name of a "New item added to your collection log" message, or null
	 */
	public static String collectionLogItem(String message)
	{
		if (message == null)
		{
			return null;
		}
		Matcher m = COLLECTION_LOG.matcher(stripTags(message));
		return m.find() ? m.group(1).trim() : null;
	}

	public static boolean isPetMessage(String message)
	{
		if (message == null)
		{
			return false;
		}
		String plain = stripTags(message);
		for (String p : PET)
		{
			if (plain.contains(p))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The message without the colour tags the game puts in it.
	 */
	public static String stripTags(String message)
	{
		return message.replaceAll("<[^>]*>", "");
	}
}

package com.dropluckledger.capture;

import java.util.Locale;

/**
 * Name matching helpers: game text and the boss data spell the same thing slightly differently
 * ("The Nightmare" / "Nightmare", "Theatre of Blood: Hard Mode" / "Theatre of Blood Hard Mode").
 */
public final class Names
{
	private Names()
	{
	}

	/**
	 * Lower case, letters and digits only, a leading "the" dropped.
	 */
	public static String norm(String s)
	{
		if (s == null)
		{
			return "";
		}
		String t = flat(s.replace("&", "and"));
		if (t.startsWith("the") && t.length() > 3)
		{
			t = t.substring(3);
		}
		return t;
	}

	/**
	 * Lower case, letters and digits only.
	 */
	public static String flat(String s)
	{
		if (s == null)
		{
			return "";
		}
		StringBuilder b = new StringBuilder(s.length());
		for (int i = 0; i < s.length(); i++)
		{
			char c = Character.toLowerCase(s.charAt(i));
			if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'))
			{
				b.append(c);
			}
		}
		return b.toString().toLowerCase(Locale.ROOT);
	}
}

package com.dropluckledger.engine;

import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Engine.ItemMeta;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Catalogue helpers shared by the panel and the capture code: which items a boss tracks by default, what kind of item each is,
 * which bosses list the same collection-log item.  Port of the equivalent helpers in the web app.
 */
public final class Catalog
{
	private Catalog()
	{
	}

	public static final List<String> CAT_ORDER = Arrays.asList("Raid", "Raid-style boss", "Desert Treasure II", "God Wars Dungeon", "Varlamore",
		"Slayer", "Dragons", "Wilderness", "Dagannoth Kings", "Minigame", "Minigame boss", "Skilling boss", "Standalone", "Misc",
		"Minor boss", "Clue boss");

	/**
	 * Bosses in display order (category order, then name).
	 */
	public static List<Boss> ordered(Data d)
	{
		List<Boss> l = new ArrayList<>(d.bosses);
		l.sort(Comparator.<Boss>comparingInt(b -> CAT_ORDER.indexOf(b.cat)).thenComparing(b -> b.name, String.CASE_INSENSITIVE_ORDER));
		return l;
	}

	/**
	 * The items shown by default: the collection-log items, the uniques and the pets that are not hidden; uniques first, then pets.
	 */
	public static List<String> defaultTracked(Boss b)
	{
		Map<String, ItemMeta> m = b.meta();
		Set<String> log = b.logSet();
		List<String> names = new ArrayList<>();
		for (Map.Entry<String, ItemMeta> e : m.entrySet())
		{
			ItemMeta im = e.getValue();
			if (!im.hidden && (log.contains(e.getKey()) || im.isUnique() || im.isPet()))
			{
				names.add(e.getKey());
			}
		}
		// stable sort by rank (JavaScript's sort is stable too)
		names.sort(Comparator.comparingInt(n -> rank(m.get(n))));
		return names;
	}

	private static int rank(ItemMeta m)
	{
		return m.isUnique() ? 0 : m.isPet() ? 1 : 2;
	}

	/**
	 * "unique", "pet" or "other".
	 */
	public static String kindOf(Boss b, String name)
	{
		ItemMeta m = b.meta().get(name);
		if (m == null)
		{
			return "other";
		}
		return m.isPet() ? "pet" : m.isUnique() ? "unique" : "other";
	}

	/**
	 * Item name to the ids of the bosses that list it in their collection log (in the order of {@link #ordered}).
	 */
	public static Map<String, List<String>> logIndex(Data d)
	{
		Map<String, List<String>> idx = new LinkedHashMap<>();
		for (Boss b : ordered(d))
		{
			for (String n : b.logSet())
			{
				idx.computeIfAbsent(n, k -> new ArrayList<>()).add(b.id);
			}
		}
		return idx;
	}

	/**
	 * The "any unique" selection: the tracked uniques that are in the collection log and have a drop rate, split into those that share
	 * the unique table and those rolled separately (noany).
	 */
	public static final class AnyNames
	{
		public final List<String> names = new ArrayList<>();
		public final List<String> sep = new ArrayList<>();
	}

	public static AnyNames anyNames(Boss b, List<String> tracked)
	{
		Map<String, ItemMeta> m = b.meta();
		Set<String> log = b.logSet();
		AnyNames out = new AnyNames();
		for (String n : tracked)
		{
			ItemMeta im = m.get(n);
			if (im == null || !im.isUnique() || im.hidden || !log.contains(n) || im.rateUnknown())
			{
				continue;
			}
			if (im.noany)
			{
				out.sep.add(n);
			}
			else
			{
				out.names.add(n);
			}
		}
		return out;
	}
}

package com.dropluckledger.engine;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The boss drop data (boss.json compiled from the .ds sources) and the compiled form of its expressions.
 * Fields without "transient" are read straight from the JSON; the transient ones are filled in by {@link #prepare()}.
 */
public final class Data
{
	public List<Boss> bosses = new ArrayList<>();
	public List<Shared> shared = new ArrayList<>();

	public transient Map<String, Boss> boss = new LinkedHashMap<>();
	public transient Map<String, Shared> sharedById = new HashMap<>();

	/**
	 * Reads and prepares the data from a stream (UTF-8 JSON).
	 */
	public static Data load(Gson gson, InputStream in) throws IOException
	{
		try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			Data d = gson.fromJson(r, Data.class);
			if (d == null)
			{
				throw new IOException("empty boss data");
			}
			d.prepare();
			return d;
		}
	}

	public Boss boss(String id)
	{
		return boss.get(id);
	}

	/**
	 * Compiles every expression once.
	 */
	public void prepare()
	{
		boss = new LinkedHashMap<>();
		sharedById = new HashMap<>();
		if (bosses == null)
		{
			bosses = new ArrayList<>();
		}
		if (shared == null)
		{
			shared = new ArrayList<>();
		}
		for (Shared s : shared)
		{
			for (Table t : s.tables)
			{
				t.prepare();
			}
			sharedById.put(s.id, s);
		}
		for (Boss b : bosses)
		{
			b.data = this;
			b.prepare();
			boss.put(b.id, b);
		}
	}

	// ------------------------------------------------------------------ model classes

	public static final class Shared
	{
		public String id;
		public String name;
		public List<Table> tables = new ArrayList<>();
	}

	public static final class Param
	{
		public String name;
		public String type; // bool | int | select
		public String label;
		@SerializedName("default")
		public Object def;
		public Double min;
		public Double max;
		public List<String> options;
	}

	public static final class LogItem
	{
		public String name;
		public boolean found;
	}

	public static final class Derive
	{
		public String name;
		public String expr;
	}

	public static final class Derived
	{
		public final String name;
		public final Expr f;

		Derived(String name, Expr f)
		{
			this.name = name;
			this.f = f;
		}
	}

	public static final class RollVar
	{
		public final String name;
		public final double start;

		RollVar(String name, double start)
		{
			this.name = name;
			this.start = start;
		}
	}

	public static final class Boss
	{
		public String id;
		public String name;
		public String cat;
		public String wiki;
		public List<String> kc = new ArrayList<>();
		public String samples;
		public String rolls;
		public List<String> notes = new ArrayList<>();
		public List<String> always = new ArrayList<>();
		public List<Param> params = new ArrayList<>();
		public List<Table> tables = new ArrayList<>();
		public List<Row> tert = new ArrayList<>();
		public List<Row> pets = new ArrayList<>();
		public List<Derive> derive = new ArrayList<>();
		public List<LogItem> logItems = new ArrayList<>();
		public String rollvar;
		public String simnote;
		/**
		 * The share of kills that pay out (an expression of the settings), or null: see {@link Engine#lootScale}.
		 */
		public String scale;
		/**
		 * How loot events relate to kills: "kill" (one loot event per kill, the default), "extra" (rewards taken later that never
		 * count as kills: Tempoross), "claim" (every loot event is one run and there is no kill-count message: Doom of
		 * Mokhaiotl) or "top" (only the top damage dealer gets the loot: a kill without loot paid another player).
		 */
		public String lootmode;
		/**
		 * Names of the other monsters whose loot counts for this boss (the God Wars bodyguards); it is recorded under the boss but
		 * never counts as a kill.
		 */
		public List<String> extraLoot = new ArrayList<>();
		/**
		 * The per-kill setting that counts the loots of those other monsters (EXTRACOUNT): each bodyguard loot the plugin sees adds one to
		 * the "Bodyguards killed with each kill" of the kill it belongs to.  Null for most bosses.
		 */
		public String extraCount;
		/**
		 * Settings a kill has when its regular loot arrives (ONLOOT) and when it never does (NOLOOT): another player got it, the
		 * corpse was destroyed, the loot was sacrificed.  Empty for most bosses.
		 */
		public Map<String, String> onLoot = new LinkedHashMap<>();
		public Map<String, String> noLoot = new LinkedHashMap<>();
		/**
		 * Settings the plugin reads from the game for every kill it sees (READS): for those kills they are not the player's to set,
		 * so what the player sets applies to the other kills only.
		 */
		public List<String> reads = new ArrayList<>();
		/**
		 * Of those, the ones whose first value seen also stands for the earlier kills, unless the player set them (INFER): the
		 * Fishing level of the first Tempoross reward seen is a better guess for the rewards before than a default.
		 */
		public List<String> infer = new ArrayList<>();

		public transient Data data;
		public transient Expr rollsFn;
		public transient Expr scaleFn;
		public transient RollVar rv;
		public transient List<Derived> derived = new ArrayList<>();
		// lazily computed, shared between threads
		transient Luck.Dep depCache;
		transient Map<String, Engine.ItemMeta> metaCache;
		transient java.util.Set<String> logCache;
		transient java.util.Set<String> tertCache;

		void prepare()
		{
			notes = nn(notes);
			always = nn(always);
			params = nn(params);
			tables = nn(tables);
			tert = nn(tert);
			pets = nn(pets);
			derive = nn(derive);
			kc = nn(kc);
			logItems = nn(logItems);
			rollsFn = rolls != null && !rolls.isEmpty() ? Expr.parse(rolls) : null;
			scaleFn = scale != null && !scale.isEmpty() ? Expr.parse(scale) : null;
			extraLoot = nn(extraLoot);
			reads = nn(reads);
			infer = nn(infer);
			onLoot = onLoot == null ? new LinkedHashMap<>() : onLoot;
			noLoot = noLoot == null ? new LinkedHashMap<>() : noLoot;
			if (lootmode == null || lootmode.isEmpty())
			{
				lootmode = "kill";
			}
			rv = null;
			if (rollvar != null && !rollvar.isEmpty())
			{
				String[] p = rollvar.trim().split("\\s+");
				rv = new RollVar(p[0], p.length > 1 ? Double.parseDouble(p[1]) : 0);
			}
			derived = new ArrayList<>();
			for (Derive d : derive)
			{
				derived.add(new Derived(d.name, Expr.parse(d.expr)));
			}
			for (Table t : tables)
			{
				t.prepare();
			}
			for (Row r : tert)
			{
				r.prepare();
			}
			for (Row r : pets)
			{
				r.prepare();
			}
			// the rows of each no-duplicate group, for the expressions that read how much of the whole set is owned (setowned)
			Map<String, List<Row>> groups = new LinkedHashMap<>();
			for (Row r : allRows())
			{
				String g = r.attrs.get("nodup");
				if (g != null && !g.isEmpty())
				{
					groups.computeIfAbsent(g, k -> new ArrayList<>()).add(r);
				}
			}
			for (List<Row> g : groups.values())
			{
				for (Row r : g)
				{
					r.group = g;
				}
			}
		}

		public boolean lootIsExtra()
		{
			return "extra".equals(lootmode);
		}

		public boolean lootIsClaim()
		{
			return "claim".equals(lootmode);
		}

		public boolean lootToTop()
		{
			return "top".equals(lootmode);
		}

		/**
		 * True when a kill without regular loot says something about the kill (see {@link #noLoot}).
		 */
		public boolean decidesOnLoot()
		{
			return !noLoot.isEmpty();
		}

		/**
		 * Settings from {@link #onLoot} or {@link #noLoot}, with numbers as numbers.
		 */
		public static Map<String, Object> settings(Map<String, String> m)
		{
			Map<String, Object> out = new LinkedHashMap<>();
			for (Map.Entry<String, String> e : m.entrySet())
			{
				String v = e.getValue();
				try
				{
					out.put(e.getKey(), Integer.parseInt(v));
				}
				catch (NumberFormatException ex)
				{
					out.put(e.getKey(), v);
				}
			}
			return out;
		}

		/**
		 * Items only the tertiary and pet rolls give (clue scrolls, pets): loot of nothing else is no regular loot.
		 */
		public synchronized java.util.Set<String> tertiaryOnly()
		{
			if (tertCache == null)
			{
				java.util.Set<String> tableItems = new java.util.HashSet<>();
				for (Table t : tables)
				{
					for (Row r : t.items)
					{
						tableItems.add(r.name);
					}
					for (Sub sb : t.subs)
					{
						for (Row r : sb.items)
						{
							tableItems.add(r.name);
						}
					}
				}
				java.util.Set<String> s = new java.util.HashSet<>();
				for (Row r : tert)
				{
					if (!tableItems.contains(r.name))
					{
						s.add(r.name);
					}
				}
				for (Row r : pets)
				{
					if (!tableItems.contains(r.name))
					{
						s.add(r.name);
					}
				}
				tertCache = s;
			}
			return tertCache;
		}

		/**
		 * Every row of every table, sub-table, tertiary and pet row (not the shared tables reached through gates).
		 */
		public List<Row> allRows()
		{
			List<Row> out = new ArrayList<>();
			for (Table t : tables)
			{
				out.addAll(t.items);
				for (Sub s : t.subs)
				{
					out.addAll(s.items);
				}
			}
			out.addAll(tert);
			out.addAll(pets);
			return out;
		}

		/**
		 * Names of the collection-log items of this boss (rows flagged log in the data).
		 */
		public synchronized java.util.Set<String> logSet()
		{
			if (logCache == null)
			{
				java.util.Set<String> s = new java.util.LinkedHashSet<>();
				for (Row r : allRows())
				{
					if (r.log)
					{
						s.add(r.name);
					}
				}
				logCache = s;
			}
			return logCache;
		}

		public synchronized Luck.Dep dep()
		{
			if (depCache == null)
			{
				depCache = Luck.scanBoss(this);
			}
			return depCache;
		}

		public synchronized Map<String, Engine.ItemMeta> meta()
		{
			if (metaCache == null)
			{
				metaCache = Engine.itemMeta(this);
			}
			return metaCache;
		}
	}

	public static final class Table
	{
		public String id;
		public String label;
		public boolean pre;
		public boolean par;
		public String alt;
		public List<Row> items = new ArrayList<>();
		public List<Gate> gates = new ArrayList<>();
		public List<Sub> subs = new ArrayList<>();
		public Map<String, String> opts = new HashMap<>();

		public transient Expr ifFn;
		public transient Expr gateFn;
		public transient Expr multFn;
		public transient Expr rollsFn;
		public transient Double cancels;
		public transient Double abs;
		/**
		 * A follow table's share for the boss's pet (petslot=a/b), 0 for none: once the pet is owned the slot is gone and the other
		 * rows share it out (the Abyssal Sire's Font of Consumption is out of 123 instead of 128 once the orphan is owned).
		 */
		public transient double petslot;
		/**
		 * The rolls never give the same row twice (distinct=1, the Chambers of Xeric's standard loot).
		 */
		public transient boolean distinct;
		/**
		 * Rolled whoever got the kill's own loot: the boss's loot share (SCALE) does not apply (noscale=1, the God Wars bodyguards).
		 */
		public transient boolean noscale;

		void prepare()
		{
			items = nn(items);
			gates = nn(gates);
			subs = nn(subs);
			if (opts == null)
			{
				opts = new HashMap<>();
			}
			ifFn = opts.containsKey("if") && !opts.get("if").isEmpty() ? Expr.cond(opts.get("if")) : null;
			gateFn = has(opts, "gate") ? Expr.parse(opts.get("gate")) : null;
			multFn = has(opts, "mult") ? Expr.parse(opts.get("mult")) : null;
			rollsFn = opts.containsKey("rolls") ? Expr.parse(opts.get("rolls")) : null;
			cancels = Row.parseCancels(opts.get("cancels"));
			abs = has(opts, "abs") ? Expr.rate(opts.get("abs")).eval(new Env()) : null;
			petslot = has(opts, "petslot") ? Expr.rate(opts.get("petslot")).eval(new Env()) : 0;
			distinct = has(opts, "distinct");
			noscale = has(opts, "noscale");
			for (Row r : items)
			{
				r.prepare();
			}
			for (Sub s : subs)
			{
				s.prepare();
			}
		}

		public String opt(String k)
		{
			return opts.get(k);
		}
	}

	public static final class Gate
	{
		public String table;
		public String rate;
		public double p;
		public Map<String, String> opts = new HashMap<>();

		public boolean opt(String k)
		{
			return opts != null && has(opts, k);
		}
	}

	public static final class Sub
	{
		public String id;
		public double p;
		public List<Row> items = new ArrayList<>();
		public Map<String, String> opts = new HashMap<>();

		public transient Expr ifFn;

		void prepare()
		{
			items = nn(items);
			if (opts == null)
			{
				opts = new HashMap<>();
			}
			ifFn = has(opts, "if") ? Expr.cond(opts.get("if")) : null;
			for (Row r : items)
			{
				r.prepare();
			}
		}
	}

	public static final class VarClause
	{
		public final List<String> conds;
		public final Expr rate;

		VarClause(List<String> conds, Expr rate)
		{
			this.conds = conds;
			this.rate = rate;
		}
	}

	public static final class Seq
	{
		public final String slot;
		public final int n;
		public final int[] ns;
		public final int last;

		Seq(String slot, int[] ns)
		{
			this.slot = slot;
			this.ns = ns;
			this.n = ns[0];
			int m = ns[0];
			for (int x : ns)
			{
				m = Math.max(m, x);
			}
			this.last = m;
		}
	}

	public static final class Row
	{
		public String flag = "";
		public String name;
		public String qty;
		public String rate;
		public Double p;
		public Map<String, String> attrs = new HashMap<>();
		public String key;
		public boolean log;

		public transient Expr ifFn;
		public transient Expr expr;
		public transient List<VarClause> var;
		public transient Double cancels;
		public transient Seq seq;
		public transient double pity;
		/**
		 * The rows of the row's no-duplicate group (this one included), or null when it is in none: what {@code setowned} reads.
		 */
		public transient List<Row> group;

		private static final Pattern SEQ = Pattern.compile("^([^:]+):(\\d+(?:,\\d+)*)$");

		/**
		 * True when the drop rate is not published yet ("unknown"): the row is shown and tracked, but never rolled.
		 */
		public boolean unknownRate()
		{
			return rate != null && "unknown".equalsIgnoreCase(rate.trim());
		}

		void prepare()
		{
			if (attrs == null)
			{
				attrs = new HashMap<>();
			}
			if (flag == null)
			{
				flag = "";
			}
			ifFn = has(attrs, "if") ? Expr.cond(attrs.get("if")) : null;
			expr = has(attrs, "expr") ? Expr.parse(attrs.get("expr")) : null;
			var = has(attrs, "var") ? parseVar(attrs.get("var")) : null;
			cancels = parseCancels(attrs.get("cancels"));
			seq = null;
			if (has(attrs, "seq"))
			{
				Matcher m = SEQ.matcher(attrs.get("seq"));
				if (!m.matches())
				{
					throw new IllegalArgumentException("bad seq=" + attrs.get("seq"));
				}
				String[] parts = m.group(2).split(",");
				int[] ns = new int[parts.length];
				for (int i = 0; i < parts.length; i++)
				{
					ns[i] = Integer.parseInt(parts[i]);
				}
				seq = new Seq(m.group(1), ns);
			}
			pity = has(attrs, "pity") ? Expr.parseFloat(attrs.get("pity")) : 0;
		}

		public String attr(String k)
		{
			return attrs.get(k);
		}

		/**
		 * JavaScript truthiness of an attribute string: set and non-empty.
		 */
		public boolean flagged(String k)
		{
			return has(attrs, k);
		}

		static Double parseCancels(String v)
		{
			if (v == null || v.isEmpty())
			{
				return null;
			}
			if (v.equals("main") || v.equals("all"))
			{
				return Double.POSITIVE_INFINITY;
			}
			if (v.equals("main-roll"))
			{
				return 1.0;
			}
			Matcher m = Pattern.compile("^main:(\\d+)$").matcher(v);
			if (m.matches())
			{
				return Double.parseDouble(m.group(1));
			}
			throw new IllegalArgumentException("bad cancels=" + v);
		}

		private static List<VarClause> parseVar(String src)
		{
			List<VarClause> out = new ArrayList<>();
			for (String e : Expr.splitTop(src, ','))
			{
				int i = e.indexOf(':');
				List<String> conds = new ArrayList<>();
				for (String c : e.substring(0, i).trim().split("\\+"))
				{
					String t = c.trim();
					if (!t.isEmpty())
					{
						conds.add(t);
					}
				}
				out.add(new VarClause(conds, Expr.rate(e.substring(i + 1))));
			}
			return out;
		}
	}

	// ------------------------------------------------------------------ helpers
	private static boolean has(Map<String, String> m, String k)
	{
		String v = m == null ? null : m.get(k);
		return v != null && !v.isEmpty();
	}

	private static <T> List<T> nn(List<T> l)
	{
		return l == null ? new ArrayList<>() : l;
	}
}

package com.dropluckledger.engine;

import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Data.Gate;
import com.dropluckledger.engine.Data.Param;
import com.dropluckledger.engine.Data.Row;
import com.dropluckledger.engine.Data.Seq;
import com.dropluckledger.engine.Data.Shared;
import com.dropluckledger.engine.Data.Sub;
import com.dropluckledger.engine.Data.Table;
import com.dropluckledger.engine.Data.VarClause;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

/**
 * Per-kill drop probabilities of a boss.  This is a line-by-line port of the web app's engine.js
 * (the part that computes chances; the drop simulator is intentionally not part of the plugin).
 * See SPEC.md of the web app for the meaning of the table options.
 */
public final class Engine
{
	private Engine()
	{
	}

	/**
	 * What the account has so far, used by rows whose chance depends on it (pity timers, no-duplicate groups, owned()).
	 */
	public interface Ctx
	{
		int owned(Row row);

		double since(Row row);
	}

	// ------------------------------------------------------------------ environment
	public static Map<String, Object> defaultParams(Boss boss)
	{
		Map<String, Object> o = new LinkedHashMap<>();
		for (Param p : boss.params)
		{
			o.put(p.name, p.def);
		}
		return o;
	}

	private static boolean jsTruthy(Object v)
	{
		if (v == null)
		{
			return false;
		}
		if (v instanceof Boolean)
		{
			return (Boolean) v;
		}
		if (v instanceof Number)
		{
			double d = ((Number) v).doubleValue();
			return d != 0 && !Double.isNaN(d);
		}
		if (v instanceof CharSequence)
		{
			return ((CharSequence) v).length() > 0;
		}
		return true;
	}

	private static double jsNumber(Object v)
	{
		if (v == null)
		{
			return 0;
		}
		if (v instanceof Boolean)
		{
			return (Boolean) v ? 1 : 0;
		}
		if (v instanceof Number)
		{
			return ((Number) v).doubleValue();
		}
		String s = v.toString().trim();
		if (s.isEmpty())
		{
			return 0;
		}
		try
		{
			return Double.parseDouble(s);
		}
		catch (NumberFormatException e)
		{
			return Double.NaN;
		}
	}

	/**
	 * Builds the variables an expression can read for one boss, one set of boss settings and a kill count.
	 *
	 * @param values  boss settings by name (missing ones use the data's default)
	 * @param globals account-wide switches (rowi = ring of wealth, lq = Legends' Quest)
	 */
	public static Env makeEnv(Boss boss, Map<String, Object> values, Map<String, Double> globals, double kc)
	{
		Env env = new Env();
		env.put("rowi", 0);
		env.put("lq", 1);
		env.put("kc", kc);
		env.put("owned", 0);
		env.put("setowned", 0);
		env.put("ri", 0);
		if (globals != null)
		{
			for (Map.Entry<String, Double> e : globals.entrySet())
			{
				env.put(e.getKey(), e.getValue());
			}
		}
		for (Param p : boss.params)
		{
			Object v = values != null && values.containsKey(p.name) ? values.get(p.name) : p.def;
			if ("bool".equals(p.type))
			{
				env.put(p.name, jsTruthy(v) ? 1 : 0);
			}
			else if ("int".equals(p.type))
			{
				env.put(p.name, jsNumber(v));
			}
			else if ("select".equals(p.type))
			{
				String sv = v instanceof String ? (String) v : null;
				env.put(p.name, sv == null ? -1 : p.options.indexOf(sv));
				for (String o : p.options)
				{
					env.put(o, o.equals(sv) ? 1 : 0);
				}
			}
		}
		for (Data.Derived d : boss.derived)
		{
			env.put(d.name, d.f.eval(env));
		}
		return env;
	}

	// ------------------------------------------------------------------ row probabilities
	/**
	 * Absolute probability per attempt of a row; null for "rest" rows (whatever is left over).  A rate that is not published yet
	 * ("unknown") is 0: the row is shown and tracked, but never rolled.
	 */
	public static Double rowBase(Row row, Env env, Ctx ctx)
	{
		if (row.ifFn != null && !Expr.truthy(row.ifFn.eval(env)))
		{
			return 0.0;
		}
		if (row.unknownRate())
		{
			return 0.0;
		}
		if (row.expr != null)
		{
			env.put("owned", ctx != null ? ctx.owned(row) : 0);
			env.put("setowned", setOwned(row, ctx));
			double v = row.expr.eval(env);
			env.put("owned", 0);
			env.put("setowned", 0);
			return Math.max(0, v);
		}
		if (row.var != null)
		{
			VarClause best = null;
			for (VarClause v : row.var)
			{
				boolean all = true;
				for (String c : v.conds)
				{
					boolean ok = c.charAt(0) == '!' ? !env.truthy(c.substring(1)) : env.truthy(c);
					if (!ok)
					{
						all = false;
						break;
					}
				}
				if (all && (best == null || v.conds.size() > best.conds.size()))
				{
					best = v;
				}
			}
			if (best != null)
			{
				return Math.max(0, best.rate.eval(env));
			}
		}
		if (row.flagged("pity") && ctx != null)
		{
			if (ctx.since(row) >= row.pity - 1)
			{
				return 1.0;
			}
		}
		if (row.p == null)
		{
			return null;
		}
		return row.p;
	}

	/**
	 * The fewest copies held of any item of the row's no-duplicate group: 0 until the whole set has been received once.  For a row in no
	 * group, its own copies.
	 */
	private static int setOwned(Row row, Ctx ctx)
	{
		if (ctx == null)
		{
			return 0;
		}
		if (row.group == null)
		{
			return ctx.owned(row);
		}
		int mn = Integer.MAX_VALUE;
		for (Row r : row.group)
		{
			mn = Math.min(mn, ctx.owned(r));
		}
		return mn == Integer.MAX_VALUE ? 0 : mn;
	}

	/**
	 * True for a no-duplicate group written {@code nodup=group:once}: its protection holds only until every item of it has been
	 * received once (the Tombs of Amascut jewels).
	 */
	public static boolean onceGroup(String group)
	{
		return group != null && group.endsWith(":once");
	}

	/**
	 * Independent attempts for tertiaries and pets (attribute trials=expr).
	 */
	private static Double withTrials(Row row, Double p, Env env)
	{
		String t = row.attrs.get("trials");
		if (t == null || t.isEmpty() || p == null)
		{
			return p;
		}
		double n = Expr.parse(t).eval(env);
		return 1 - Math.pow(1 - p, n);
	}

	private static int cnt(Ctx ctx, Row row)
	{
		return ctx != null ? ctx.owned(row) : 0;
	}

	private static boolean truthy(Double d)
	{
		return d != null && d != 0 && !Double.isNaN(d);
	}

	// ------------------------------------------------------------------ table expansion
	static final class Out
	{
		final String name;
		final double pm;
		final Row row;

		Out(String name, double pm, Row row)
		{
			this.name = name;
			this.pm = pm;
			this.row = row;
		}
	}

	public static final class Member
	{
		public final String name;
		public double pm;
		public final Row row;
		public String xor;
		public Integer seqN;
		public int[] seqNs;

		Member(String name, double pm, Row row)
		{
			this.name = name;
			this.pm = pm;
			this.row = row;
		}
	}

	public static final class Entry
	{
		public Double p;
		public Double k;
		public final List<Member> members = new ArrayList<>();
		public int row = -1;
		public String nodup;
		public String slot;
		public boolean bundle;
		public String shared;
	}

	private static Shared sharedLookup(Data data, String id)
	{
		Shared s = data.sharedById.get(id);
		if (s == null)
		{
			throw new IllegalStateException("unknown shared table " + id);
		}
		return s;
	}

	private static double nz(Double d)
	{
		return d == null ? 0 : d;
	}

	static void expandShared(Data data, Shared s, Env env, Ctx ctx, double mass, List<Out> out)
	{
		Table t = s.tables.get(0);
		List<Row> rows = new ArrayList<>();
		for (Row r : t.items)
		{
			if (!(env.truthy("rowi") && r.flagged("rowremove")))
			{
				rows.add(r);
			}
		}
		Double[] shares = new Double[rows.size()];
		for (int i = 0; i < rows.size(); i++)
		{
			Row r = rows.get(i);
			shares[i] = r.flag.equals("+") ? Double.valueOf(0) : rowBase(r, env, ctx);
		}
		int restIdx = -1;
		double sum = 0;
		boolean hasAbs = t.abs != null && t.abs != 0 && !Double.isNaN(t.abs);
		for (int i = 0; i < rows.size(); i++)
		{
			if (shares[i] == null)
			{
				restIdx = i;
			}
			else
			{
				if (hasAbs)
				{
					shares[i] = shares[i] / t.abs;
				}
				sum += shares[i];
			}
		}
		for (Gate g : t.gates)
		{
			sum += g.p;
		}
		if (restIdx >= 0)
		{
			shares[restIdx] = Math.max(0, 1 - sum);
			sum += shares[restIdx];
		}
		double f = sum > 0 ? 1 / sum : 0;
		for (int i = 0; i < rows.size(); i++)
		{
			Row r = rows.get(i);
			if (r.flag.equals("+") || !truthy(shares[i]))
			{
				continue;
			}
			out.add(new Out(r.name, mass * shares[i] * f, r));
		}
		for (Gate g : t.gates)
		{
			double m = mass * g.p * f;
			if (g.opt("lq") && !env.truthy("lq"))
			{
				out.add(new Out("Nature talisman", m, null));
				continue;
			}
			expandShared(data, sharedLookup(data, g.table), env, ctx, m, out);
		}
	}

	private static String nonEmpty(String s)
	{
		return s == null || s.isEmpty() ? null : s;
	}

	/**
	 * The mutually exclusive outcomes of one table for one attempt.
	 */
	static List<Entry> expandTable(Data data, Table t, Env env, Ctx ctx, boolean isBase)
	{
		List<Row> rows = t.items;
		int n = rows.size();
		List<Integer> leaders = new ArrayList<>();
		for (int i = 0; i < n; i++)
		{
			if (!rows.get(i).flag.equals("+"))
			{
				leaders.add(i);
			}
		}
		Double[] base = new Double[n];
		for (int i = 0; i < n; i++)
		{
			base[i] = rowBase(rows.get(i), env, ctx);
		}
		// sequence slots: the first row (lowest n) carries the probability, the others are members of the same entry
		Map<String, Integer> slotLead = new HashMap<>();
		for (int i : leaders)
		{
			Seq s = rows.get(i).seq;
			if (s != null && (!slotLead.containsKey(s.slot) || s.n < rows.get(slotLead.get(s.slot)).seq.n))
			{
				slotLead.put(s.slot, i);
			}
		}
		List<Entry> entries = new ArrayList<>();
		Map<String, Entry> slotEntry = new HashMap<>();
		for (int i : leaders)
		{
			Row r = rows.get(i);
			Seq s = r.seq;
			if (s != null && slotLead.get(s.slot) != i)
			{
				continue;
			}
			Entry e = new Entry();
			e.p = base[i];
			e.k = r.cancels;
			e.row = i;
			e.nodup = nonEmpty(r.attrs.get("nodup"));
			if (s != null)
			{
				e.slot = s.slot;
				slotEntry.put(s.slot, e);
			}
			entries.add(e);
			e.members.add(new Member(r.name, nz(base[i]), r));
			for (int j = i + 1; j < n && rows.get(j).flag.equals("+"); j++)
			{
				e.members.add(new Member(rows.get(j).name, nz(base[j]), rows.get(j)));
			}
		}
		for (int i : leaders)
		{
			Seq s = rows.get(i).seq;
			if (s != null && slotLead.get(s.slot) != i)
			{
				Entry e = slotEntry.get(s.slot);
				Member m = new Member(rows.get(i).name, nz(e.p), rows.get(i));
				m.seqN = s.n;
				m.seqNs = s.ns;
				e.members.add(m);
			}
		}
		for (Entry e : entries)
		{
			if (e.slot != null)
			{
				Member m0 = e.members.get(0);
				m0.seqN = m0.row.seq.n;
				m0.seqNs = m0.row.seq.ns;
				for (Member m : e.members)
				{
					m.pm = nz(e.p);
				}
			}
		}
		// no-duplicate groups: only the copies you hold the fewest of can drop; the group's total chance is kept
		Map<String, List<Entry>> groups = new LinkedHashMap<>();
		for (Entry e : entries)
		{
			if (e.nodup != null && e.p != null)
			{
				groups.computeIfAbsent(e.nodup, k -> new ArrayList<>()).add(e);
			}
		}
		for (Map.Entry<String, List<Entry>> ge : groups.entrySet())
		{
			List<Entry> es = ge.getValue();
			int[] counts = new int[es.size()];
			int mn = Integer.MAX_VALUE;
			double tot = 0;
			for (int i = 0; i < es.size(); i++)
			{
				counts[i] = cnt(ctx, rows.get(es.get(i).row));
				mn = Math.min(mn, counts[i]);
				tot += es.get(i).p;
			}
			if (onceGroup(ge.getKey()) && mn >= 1)
			{
				continue; // the whole set is owned: duplicates can come again
			}
			double se = 0;
			for (int i = 0; i < es.size(); i++)
			{
				if (counts[i] == mn)
				{
					se += es.get(i).p;
				}
			}
			for (int i = 0; i < es.size(); i++)
			{
				Entry e = es.get(i);
				double np = counts[i] == mn && se > 0 ? e.p * tot / se : 0;
				for (Member m : e.members)
				{
					m.pm = np;
				}
				e.p = np;
			}
		}
		// gated shared tables and sub-tables (absolute masses)
		List<Entry> extra = new ArrayList<>();
		for (Gate g : t.gates)
		{
			List<Out> out = new ArrayList<>();
			expandShared(data, sharedLookup(data, g.table), env, ctx, g.p, out);
			for (Out o : out)
			{
				Entry e = new Entry();
				e.p = o.pm;
				e.k = null;
				e.members.add(new Member(o.name, o.pm, o.row));
				e.shared = g.table;
				extra.add(e);
			}
		}
		Set<String> seenAlt = new HashSet<>();
		for (Sub sb : t.subs)
		{
			String alt = nonEmpty(sb.opts.get("alt"));
			if (sb.ifFn != null && !Expr.truthy(sb.ifFn.eval(env)))
			{
				continue;
			}
			if (alt != null)
			{
				if (seenAlt.contains(alt))
				{
					continue;
				}
				seenAlt.add(alt);
			}
			boolean sbBundle = nonEmpty(sb.opts.get("bundle")) != null;
			Double[] sp = new Double[sb.items.size()];
			for (int i = 0; i < sp.length; i++)
			{
				sp[i] = rowBase(sb.items.get(i), env, ctx);
			}
			if (sbBundle)
			{
				Entry e = new Entry();
				e.p = sb.p;
				e.k = null;
				e.bundle = true;
				for (int i = 0; i < sp.length; i++)
				{
					Row r = sb.items.get(i);
					Member m = new Member(r.name, Math.min(nz(sp[i]), sb.p), r);
					m.xor = nonEmpty(r.attrs.get("xor"));
					e.members.add(m);
				}
				extra.add(e);
			}
			else
			{
				Entry lead = null;
				for (int i = 0; i < sp.length; i++)
				{
					Row r = sb.items.get(i);
					if (r.flag.equals("+") && lead != null)
					{
						lead.members.add(new Member(r.name, nz(sp[i]), r));
						continue;
					}
					lead = new Entry();
					lead.p = nz(sp[i]);
					lead.k = r.cancels;
					lead.members.add(new Member(r.name, nz(sp[i]), r));
					extra.add(lead);
				}
			}
		}
		// totals
		double entriesSum = 0;
		for (Entry e : entries)
		{
			entriesSum += nz(e.p);
		}
		double extraSum = 0;
		for (Entry e : extra)
		{
			extraSum += e.p;
		}
		double total = entriesSum + extraSum;
		if (t.gateFn != null)
		{
			double g = Math.min(1, Math.max(0, t.gateFn.eval(env)));
			double s = entriesSum;
			double sc = s > 0 ? g / s : 0;
			for (Entry e : entries)
			{
				e.p = nz(e.p) * sc;
				for (Member m : e.members)
				{
					m.pm = m.pm * sc;
				}
			}
		}
		else
		{
			List<Entry> restE = new ArrayList<>();
			for (Entry e : entries)
			{
				if (e.p == null)
				{
					restE.add(e);
				}
			}
			if (!restE.isEmpty())
			{
				double r = Math.max(0, 1 - total);
				for (Entry e : restE)
				{
					e.p = r / restE.size();
					for (Member m : e.members)
					{
						m.pm = e.p;
					}
				}
				total += r;
			}
			// base tables always sum to 1 (wiki rounding); any table that exceeds 1 is scaled down so the maths agree
			String normalize = t.opts.get("normalize");
			if ((normalize != null && !normalize.isEmpty()) || isBase || total > 1)
			{
				double sc = total > 0 ? 1 / total : 1;
				for (Entry e : entries)
				{
					e.p = e.p * sc;
					for (Member m : e.members)
					{
						m.pm *= sc;
					}
				}
				for (Entry e : extra)
				{
					e.p = e.p * sc;
					for (Member m : e.members)
					{
						m.pm *= sc;
					}
				}
			}
		}
		List<Entry> all = new ArrayList<>(entries);
		all.addAll(extra);
		if (t.multFn != null)
		{
			double mu = t.multFn.eval(env);
			for (Entry e : all)
			{
				e.p = e.p * mu;
				for (Member m : e.members)
				{
					m.pm *= mu;
				}
			}
		}
		// item-level cancels default to the table level
		for (Entry e : all)
		{
			if (e.k == null)
			{
				e.k = t.cancels;
			}
		}
		List<Entry> res = new ArrayList<>();
		for (Entry e : all)
		{
			boolean named = false;
			for (Member m : e.members)
			{
				if (m.name != null && !m.name.isEmpty())
				{
					named = true;
					break;
				}
			}
			if (e.p > 0 || named)
			{
				res.add(e);
			}
		}
		return res;
	}

	// ------------------------------------------------------------------ kill plan
	static final class ChainTable
	{
		Table t;
		boolean par;
		List<Entry> entries;
		Expr nFn;
		boolean isBase;
	}

	static final class Chain
	{
		List<ChainTable> tables;
		ChainTable base;
	}

	static final class Plan
	{
		boolean indexMode;
		double[][] rd; // pairs [rolls, weight]
		Chain chain;
		List<Chain> chains;
		Boss boss;
	}

	/**
	 * True when one of the boss's tables is rolled whoever got the kill's own loot (noscale=1, the God Wars bodyguards).
	 */
	static boolean hasNoscale(Boss boss)
	{
		for (Table t : boss.tables)
		{
			if (t.noscale)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * @param onlyNoscale the plan of a kill whose own loot went to another player: only the noscale tables are rolled for the player
	 */
	private static Chain buildChain(Boss boss, Env env, Ctx ctx, boolean onlyNoscale)
	{
		List<ChainTable> chain = new ArrayList<>();
		for (Table t : boss.tables)
		{
			String follow = t.opts.get("follow");
			if (follow != null && !follow.isEmpty())
			{
				continue;
			}
			if (t.ifFn != null && !Expr.truthy(t.ifFn.eval(env)))
			{
				continue;
			}
			if (onlyNoscale && !t.noscale)
			{
				continue;
			}
			ChainTable ct = new ChainTable();
			ct.t = t;
			ct.par = t.par;
			ct.nFn = t.rollsFn;
			chain.add(ct);
		}
		ChainTable base = null;
		for (ChainTable ct : chain)
		{
			if (!ct.par && !ct.t.pre)
			{
				base = ct;
			}
		}
		for (ChainTable ct : chain)
		{
			ct.isBase = ct == base;
			ct.entries = expandTable(boss.data, ct.t, env, ctx, ct.isBase);
		}
		Chain c = new Chain();
		c.tables = new ArrayList<>();
		for (ChainTable ct : chain)
		{
			if (!ct.isBase)
			{
				c.tables.add(ct);
			}
		}
		c.base = base;
		return c;
	}

	private static double[][] rollsDist(Boss boss, Env env)
	{
		double v = boss.rollsFn != null ? boss.rollsFn.eval(env) : 1;
		double lo = Math.max(0, Math.floor(v + 1e-12));
		double f = Math.max(0, v - lo);
		if (f > 1e-9)
		{
			return new double[][] {{lo, 1 - f}, {lo + 1, f}};
		}
		return new double[][] {{lo, 1}};
	}

	static Plan plan(Boss boss, Env env, Ctx ctx, boolean onlyNoscale)
	{
		Plan pl = new Plan();
		pl.boss = boss;
		pl.rd = rollsDist(boss, env);
		if (boss.rv != null)
		{
			double maxR = 0;
			for (double[] x : pl.rd)
			{
				maxR = Math.max(maxR, x[0]);
			}
			pl.indexMode = true;
			pl.chains = new ArrayList<>();
			for (int r = 0; r < maxR; r++)
			{
				env.put(boss.rv.name, boss.rv.start + r);
				env.put("ri", r + 1);
				pl.chains.add(buildChain(boss, env, ctx, onlyNoscale));
			}
			return pl;
		}
		pl.indexMode = false;
		pl.chain = buildChain(boss, env, ctx, onlyNoscale);
		return pl;
	}

	private static int baseRolls(Chain chain, Env env, int rolls)
	{
		if (chain.base == null)
		{
			return 0;
		}
		Table t = chain.base.t;
		if (t.rollsFn != null)
		{
			return (int) Math.max(0, Math.floor(t.rollsFn.eval(env) + 1e-12));
		}
		return rolls;
	}

	private static int nAttempts(ChainTable t, Env env, int rolls)
	{
		if (t.nFn != null)
		{
			return (int) Math.max(0, Math.floor(t.nFn.eval(env) + 1e-12));
		}
		return t.par ? 1 : rolls;
	}

	private static double kEff(Entry e, ChainTable t)
	{
		return e.k != null ? e.k : (t.par ? 0 : 1);
	}

	/**
	 * Probability of receiving NONE of the named items in one kill with R rolls.
	 */
	static double survChain(Chain chain, Env env, int rolls, Set<String> names, Integer m0Force)
	{
		int m0 = m0Force != null ? m0Force : baseRolls(chain, env, rolls);
		double[] vec = new double[m0 + 1];
		vec[m0] = 1;
		for (ChainTable t : chain.tables)
		{
			TreeMap<Integer, Double> mass = new TreeMap<>();
			double tot = 0;
			for (Entry e : t.entries)
			{
				double a = 0;
				for (Member m : e.members)
				{
					if (names.contains(m.name))
					{
						a = Math.max(a, m.pm);
					}
				}
				a = Math.min(a, e.p);
				tot += e.p;
				double k = kEff(e, t);
				int kk = Double.isInfinite(k) ? 1_000_000_000 : (int) k;
				if (e.p - a > 0)
				{
					mass.merge(kk, e.p - a, Double::sum);
				}
			}
			double miss = Math.max(0, 1 - tot);
			int n = nAttempts(t, env, rolls);
			double[] nv = new double[m0 + 1];
			for (int mm = 0; mm <= m0; mm++)
			{
				double w = vec[mm];
				if (!Expr.truthy(w))
				{
					continue;
				}
				if (!t.par && mm == 0)
				{
					nv[0] += w;
					continue;
				}
				double[] local = new double[mm + 1];
				local[mm] = w;
				int ne = t.par ? n : Math.min(n, mm);
				for (int a = 0; a < ne; a++)
				{
					double[] nx = new double[mm + 1];
					for (int m = 0; m <= mm; m++)
					{
						double x = local[m];
						if (!Expr.truthy(x))
						{
							continue;
						}
						if (!t.par && m == 0)
						{
							nx[0] += x;
							continue;
						}
						nx[m] += x * miss;
						for (Map.Entry<Integer, Double> me : mass.entrySet())
						{
							nx[Math.max(0, m - me.getKey())] += x * me.getValue();
						}
					}
					local = nx;
				}
				for (int m = 0; m <= mm; m++)
				{
					nv[m] += local[m];
				}
			}
			vec = nv;
		}
		if (chain.base != null)
		{
			double q = 0;
			for (Entry e : chain.base.entries)
			{
				double a = 0;
				for (Member m : e.members)
				{
					if (names.contains(m.name))
					{
						a = Math.max(a, m.pm);
					}
				}
				q += Math.min(a, e.p);
			}
			double s = 0;
			double keep = Math.max(0, 1 - q);
			// distinct=1: the rolls never give the same row twice, so mm rolls give a row with chance mm x its share (exact for one
			// row of a table whose rows weigh the same)
			boolean distinct = chain.base.t.distinct;
			for (int mm = 0; mm <= m0; mm++)
			{
				s += vec[mm] * (distinct ? Math.max(0, 1 - mm * q) : Math.pow(keep, mm));
			}
			return s;
		}
		double s = 0;
		for (double x : vec)
		{
			s += x;
		}
		return s;
	}

	static double survPlan(Plan pl, Env env, Set<String> names)
	{
		double tot = 0;
		for (double[] rw : pl.rd)
		{
			int rolls = (int) rw[0];
			double w = rw[1];
			double s;
			if (!pl.indexMode)
			{
				s = survChain(pl.chain, env, rolls, names, null);
			}
			else
			{
				s = 1;
				for (int r = 0; r < rolls; r++)
				{
					env.put(pl.boss.rv.name, pl.boss.rv.start + r);
					env.put("ri", r + 1);
					s *= survChain(pl.chains.get(r), env, 1, names, 1);
				}
			}
			tot += w * s;
		}
		return tot;
	}

	private static Set<String> planNames(Plan pl)
	{
		Set<String> set = new LinkedHashSet<>();
		List<Chain> chains = new ArrayList<>();
		if (!pl.indexMode)
		{
			chains.add(pl.chain);
		}
		else
		{
			chains.addAll(pl.chains);
		}
		for (Chain c : chains)
		{
			List<ChainTable> all = new ArrayList<>(c.tables);
			if (c.base != null)
			{
				all.add(c.base);
			}
			for (ChainTable t : all)
			{
				for (Entry e : t.entries)
				{
					for (Member m : e.members)
					{
						set.add(m.name);
					}
				}
			}
		}
		return set;
	}

	// ------------------------------------------------------------------ per-kill item probabilities
	public static final class SeqInfo
	{
		public final String slot;
		public final int n;
		public final int len;

		SeqInfo(String slot, int n, int len)
		{
			this.slot = slot;
			this.n = n;
			this.len = len;
		}
	}

	public static final class ItemProb
	{
		public double p;
		public final List<String> kinds = new ArrayList<>();
		public final List<Row> rows = new ArrayList<>();
		public SeqInfo seq;
	}

	private static void put(Map<String, ItemProb> out, String name, double p, String kind, Row row)
	{
		ItemProb o = out.computeIfAbsent(name, k -> new ItemProb());
		// what the table maths leaves of an impossible drop is rounding (1e-16), not a chance
		o.p = 1 - (1 - o.p) * (1 - (p < 1e-12 ? 0 : Math.min(1, p)));
		if (!o.kinds.contains(kind))
		{
			o.kinds.add(kind);
		}
		if (row != null)
		{
			o.rows.add(row);
		}
	}

	/**
	 * The share of kills that pay out at all (the boss's SCALE): a boss whose loot goes to one player only pays you on the kills where
	 * you were that player, so every item's per-kill chance is this share times its chance on a kill that pays.  1 for most bosses.
	 */
	public static double lootScale(Boss boss, Env env)
	{
		if (boss.scaleFn == null)
		{
			return 1;
		}
		return Math.min(1, Math.max(0, boss.scaleFn.eval(env)));
	}

	/**
	 * Per-kill probability of each item (restricted to onlyNames when given).
	 */
	public static Map<String, ItemProb> itemProbs(Boss boss, Env env, Ctx ctx, Set<String> onlyNames)
	{
		Map<String, ItemProb> out = itemProbsRaw(boss, env, ctx, onlyNames, false);
		double s = lootScale(boss, env);
		if (s < 1)
		{
			// a kill that pays the player (share s) rolls everything; one that paid another player still rolls the noscale tables
			Map<String, ItemProb> ns = hasNoscale(boss) ? itemProbsRaw(boss, env, ctx, onlyNames, true) : java.util.Collections.<String, ItemProb>emptyMap();
			for (Map.Entry<String, ItemProb> e : out.entrySet())
			{
				ItemProb o = e.getValue();
				ItemProb n = ns.get(e.getKey());
				o.p = s * o.p + (1 - s) * (n != null ? n.p : 0);
			}
		}
		return out;
	}

	/**
	 * @param onlyNoscale only the noscale tables (no follow tables, tertiaries or pets: they belong to the kill's own loot)
	 */
	private static Map<String, ItemProb> itemProbsRaw(Boss boss, Env env, Ctx ctx, Set<String> onlyNames, boolean onlyNoscale)
	{
		Map<String, ItemProb> out = new LinkedHashMap<>();
		Plan pl = plan(boss, env, ctx, onlyNoscale);
		for (String n : planNames(pl))
		{
			if (onlyNames != null && !onlyNames.contains(n))
			{
				continue;
			}
			put(out, n, 1 - survPlan(pl, env, java.util.Collections.singleton(n)), "table", null);
		}
		// row metadata: sequence lengths
		Map<String, Integer> slotLen = new HashMap<>();
		for (Table t : boss.tables)
		{
			for (Row r : t.items)
			{
				if (r.seq != null)
				{
					slotLen.merge(r.seq.slot, r.seq.last, Math::max);
				}
			}
		}
		for (Table t : boss.tables)
		{
			for (Row r : t.items)
			{
				if (r.seq != null && out.containsKey(r.name))
				{
					out.get(r.name).seq = new SeqInfo(r.seq.slot, r.seq.n, slotLen.get(r.seq.slot));
				}
			}
		}
		if (onlyNoscale)
		{
			return out;
		}
		// follow tables (e.g. Abyssal Sire: items rolled when the Unsired is offered)
		for (Table t : boss.tables)
		{
			String src = nonEmpty(t.opts.get("follow"));
			if (src == null || (t.ifFn != null && !Expr.truthy(t.ifFn.eval(env))))
			{
				continue;
			}
			double pSrc = out.containsKey(src) ? out.get(src).p : 0;
			double fPet = petSlotFactor(boss, t, ctx);
			List<Row> rows = new ArrayList<>();
			for (Row r : t.items)
			{
				if (!r.flag.equals("+"))
				{
					rows.add(r);
				}
			}
			Map<String, List<Row>> groups = new LinkedHashMap<>();
			for (Row r : rows)
			{
				String g = nonEmpty(r.attrs.get("nodup"));
				if (g != null)
				{
					groups.computeIfAbsent(g, k -> new ArrayList<>()).add(r);
				}
			}
			IdentityHashMap<Row, Double> adj = new IdentityHashMap<>();
			for (Map.Entry<String, List<Row>> ge : groups.entrySet())
			{
				List<Row> rs = ge.getValue();
				int[] cs = new int[rs.size()];
				int mn = Integer.MAX_VALUE;
				double tot = 0;
				for (int i = 0; i < rs.size(); i++)
				{
					cs[i] = cnt(ctx, rs.get(i));
					mn = Math.min(mn, cs[i]);
					tot += nz(rs.get(i).p);
				}
				if (onceGroup(ge.getKey()) && mn >= 1)
				{
					continue;
				}
				double se = 0;
				for (int i = 0; i < rs.size(); i++)
				{
					if (cs[i] == mn)
					{
						se += nz(rs.get(i).p);
					}
				}
				for (int i = 0; i < rs.size(); i++)
				{
					adj.put(rs.get(i), cs[i] == mn && se > 0 ? nz(rs.get(i).p) * tot / se : 0.0);
				}
			}
			for (Row r : rows)
			{
				if (onlyNames != null && !onlyNames.contains(r.name))
				{
					continue;
				}
				Double sh = adj.containsKey(r) ? adj.get(r) : rowBase(r, env, ctx);
				if (truthy(sh))
				{
					put(out, r.name, pSrc * sh * fPet, "follow", r);
				}
			}
		}
		// tertiaries and pets
		for (Row r : boss.tert)
		{
			if (onlyNames != null && !onlyNames.contains(r.name))
			{
				continue;
			}
			Double p = withTrials(r, rowBase(r, env, ctx), env);
			if (truthy(p))
			{
				put(out, r.name, p, "tert", r);
			}
		}
		for (Row r : boss.pets)
		{
			if (onlyNames != null && !onlyNames.contains(r.name))
			{
				continue;
			}
			Double p = withTrials(r, rowBase(r, env, ctx), env);
			if (truthy(p))
			{
				put(out, r.name, p, "pet", r);
			}
		}
		return out;
	}

	/**
	 * Items that can only drop from a follow table, mapped to the item(s) that trigger that table
	 * (Abyssal Sire: Unsired -> Font of Consumption).
	 */
	public static Map<String, List<String>> followMap(Boss boss)
	{
		Map<String, List<String>> src = new LinkedHashMap<>();
		Set<String> other = new HashSet<>();
		for (Table t : boss.tables)
		{
			String f = nonEmpty(t.opts.get("follow"));
			for (Row r : t.items)
			{
				if (f != null)
				{
					src.computeIfAbsent(r.name, k -> new ArrayList<>()).add(f);
				}
				else
				{
					other.add(r.name);
				}
			}
		}
		Map<String, List<String>> out = new LinkedHashMap<>();
		for (Map.Entry<String, List<String>> e : src.entrySet())
		{
			if (!other.contains(e.getKey()))
			{
				out.put(e.getKey(), e.getValue());
			}
		}
		return out;
	}

	/**
	 * P(at least one of targets in one kill).  Items off the kill's tables exclude or otherwise depend on each other, so they are
	 * combined inside one pass (exact); tertiaries, pets and follow-up rolls are independent events and are multiplied in.
	 * sources = names other rolls depend on (follow-table sources) that must be evaluated but are not targets.
	 */
	public static double anyProb(Boss boss, Env env, Ctx ctx, Set<String> targets, Collection<String> sources)
	{
		double s = lootScale(boss, env);
		double paid = anyProbRaw(boss, env, ctx, targets, sources, false);
		if (s >= 1)
		{
			return paid;
		}
		return s * paid + (hasNoscale(boss) ? (1 - s) * anyProbRaw(boss, env, ctx, targets, sources, true) : 0);
	}

	private static double anyProbRaw(Boss boss, Env env, Ctx ctx, Set<String> targets, Collection<String> sources, boolean onlyNoscale)
	{
		Set<String> need = new LinkedHashSet<>(targets);
		if (sources != null)
		{
			need.addAll(sources);
		}
		Map<String, ItemProb> all = itemProbsRaw(boss, env, ctx, need, onlyNoscale);
		Set<String> tbl = new LinkedHashSet<>();
		double q = 1;
		Map<String, List<String>> src = new HashMap<>();
		for (Table t : boss.tables)
		{
			String f = nonEmpty(t.opts.get("follow"));
			if (f != null)
			{
				for (Row r : t.items)
				{
					src.computeIfAbsent(r.name, k -> new ArrayList<>()).add(f);
				}
			}
		}
		for (String n : targets)
		{
			ItemProb o = all.get(n);
			if (o == null)
			{
				continue;
			}
			if (o.kinds.size() == 1 && o.kinds.get(0).equals("table"))
			{
				tbl.add(n);
				continue;
			}
			if (o.kinds.size() == 1 && o.kinds.get(0).equals("follow"))
			{
				boolean viaTarget = false;
				List<String> fs = src.get(n);
				if (fs != null)
				{
					for (String f : fs)
					{
						if (targets.contains(f))
						{
							viaTarget = true;
							break;
						}
					}
				}
				if (viaTarget)
				{
					continue; // only rolled after a source that is itself in the set
				}
			}
			q *= 1 - o.p;
		}
		if (!tbl.isEmpty())
		{
			q *= survPlan(plan(boss, env, ctx, onlyNoscale), env, tbl);
		}
		return 1 - q;
	}

	/**
	 * For a follow table with petslot=a/b: 1 / (1 - a/b) once the boss's pet is owned (its slot is gone and the other rows share it
	 * out), 1 before.
	 */
	private static double petSlotFactor(Boss boss, Table t, Ctx ctx)
	{
		if (!(t.petslot > 0 && t.petslot < 1))
		{
			return 1;
		}
		for (Row r : boss.pets)
		{
			if (cnt(ctx, r) > 0)
			{
				return 1 / (1 - t.petslot);
			}
		}
		return 1;
	}

	// ------------------------------------------------------------------ item catalogue (static metadata)
	public static final class ItemMeta
	{
		public final String name;
		public final List<String> flags = new ArrayList<>();
		public String pool;
		public boolean hidden;
		public String group;
		public SeqInfo seq;
		public final List<String> where = new ArrayList<>();
		public boolean noany;
		public int pity;
		public String note;
		/**
		 * The duplicate-protection group the item is in (only the pieces held the fewest of can drop), or null.
		 */
		public String nodup;
		/**
		 * A common drop that the overview's Biggest Spoons leaves out (the Mokhaiotl waystone): being ahead of its rate is no spoon.
		 */
		public boolean noSpoon;
		private boolean knownRate;
		private boolean unknownRate;

		ItemMeta(String name)
		{
			this.name = name;
		}

		public boolean isUnique()
		{
			return flags.contains("U");
		}

		public boolean isPet()
		{
			return flags.contains("P");
		}

		/**
		 * True when no drop rate of the item is published yet: it is recorded, but no chance or luck is worked out for it.
		 */
		public boolean rateUnknown()
		{
			return unknownRate && !knownRate;
		}

		void rate(Row r)
		{
			if (r.unknownRate())
			{
				unknownRate = true;
			}
			else
			{
				knownRate = true;
			}
		}
	}

	public static Map<String, ItemMeta> itemMeta(Boss boss)
	{
		Map<String, ItemMeta> meta = new LinkedHashMap<>();
		Map<String, Integer> slotLen = new HashMap<>();
		for (Table t : boss.tables)
		{
			for (Row r : t.items)
			{
				if (r.seq != null)
				{
					slotLen.merge(r.seq.slot, r.seq.last, Math::max);
				}
			}
		}
		for (Table t : boss.tables)
		{
			for (Row r : t.items)
			{
				doRow(meta, slotLen, r, t.id);
			}
			for (Sub sb : t.subs)
			{
				for (Row r : sb.items)
				{
					doRow(meta, slotLen, r, t.id + ":" + sb.id);
				}
			}
			for (Gate g : t.gates)
			{
				List<Out> out = new ArrayList<>();
				Env env = makeEnv(boss, defaultParams(boss), new HashMap<>(), 0);
				env.put("rowi", 0);
				expandShared(boss.data, sharedLookup(boss.data, g.table), env, null, 1, out);
				for (Out o : out)
				{
					ItemMeta m = meta.computeIfAbsent(o.name, ItemMeta::new);
					if (!m.where.contains(g.table))
					{
						m.where.add(g.table);
					}
				}
			}
		}
		for (Row r : boss.tert)
		{
			doRow(meta, slotLen, r, "tertiary");
		}
		for (Row r : boss.pets)
		{
			ItemMeta m = meta.computeIfAbsent(r.name, ItemMeta::new);
			if (!m.flags.contains("P"))
			{
				m.flags.add("P");
			}
			m.where.add("pet");
			m.rate(r);
			if (r.flagged("note"))
			{
				m.note = r.attr("note");
			}
		}
		return meta;
	}

	private static void doRow(Map<String, ItemMeta> meta, Map<String, Integer> slotLen, Row r, String where)
	{
		ItemMeta m = meta.computeIfAbsent(r.name, ItemMeta::new);
		if (r.flag != null && !r.flag.isEmpty() && !m.flags.contains(r.flag))
		{
			m.flags.add(r.flag);
		}
		m.rate(r);
		if (r.flagged("pool"))
		{
			m.pool = r.attr("pool");
		}
		if (r.flagged("hidden"))
		{
			m.hidden = true;
		}
		if (r.flagged("group"))
		{
			m.group = r.attr("group");
		}
		if (r.flagged("noany"))
		{
			m.noany = true;
		}
		if (r.flagged("nodup"))
		{
			m.nodup = r.attr("nodup");
		}
		if (r.flagged("nospoon"))
		{
			m.noSpoon = true;
		}
		if (r.seq != null)
		{
			m.seq = new SeqInfo(r.seq.slot, r.seq.n, slotLen.get(r.seq.slot));
		}
		if (r.flagged("pity"))
		{
			m.pity = (int) Expr.parseFloat(r.attr("pity"));
		}
		if (r.flagged("note"))
		{
			m.note = r.attr("note");
		}
		if (!m.where.contains(where))
		{
			m.where.add(where);
		}
	}
}

