	public static Label luckLabel(Double pct)
	{
		if (pct == null || Double.isNaN(pct))
		{
			return new Label("na", "—");
		}
		if (pct < 0.05)
		{
			return new Label("vdry", "Very dry");
		}
		if (pct < 0.20)
		{
			return new Label("dry", "Dry");
		}
		if (pct < 0.40)
		{
			return new Label("below", "Slightly dry");
		}
		if (pct < 0.60)
		{
			return new Label("avg", "On rate");
		}
		if (pct < 0.80)
		{
			return new Label("above", "Slightly lucky");
		}
		if (pct < 0.95)
		{
			return new Label("lucky", "Lucky");
		}
		return new Label("vlucky", "Very lucky");
	}

	/**
	 * Kills needed from now (memoryless) for the chance of at least d hits to reach c; Infinity if unreachable.
	 */
	public static double killsTo(Model m, String name, int d, double c, int startK)
	{
		java.util.function.IntToDoubleFunction test = n -> atLeast(d, m.runsFor(name, startK + 1, startK + n));
		if (m.pAt(name, startK + 1) <= 0 && test.applyAsDouble(1) <= 0)
		{
			return Double.POSITIVE_INFINITY;
		}
		int hi = 1;
		while (test.applyAsDouble(hi) < c)
		{
			hi *= 2;
			if (hi > 20_000_000)
			{
				return Double.POSITIVE_INFINITY;
			}
		}
		int lo = hi / 2; // test(lo) < c (or lo = 0)
		while (hi - lo > 1)
		{
			int mid = (lo + hi) >> 1;
			if (test.applyAsDouble(mid) >= c)
			{
				hi = mid;
			}
			else
			{
				lo = mid;
			}
		}
		return hi;
	}

	/**
	 * The no-duplicate group an item belongs to (its names), or null.
	 */
	static List<String> nodupGroupOf(Model m, String name)
	{
		for (Set<String> set : m.dep.nodupGroups.values())
		{
			if (set.contains(name) && set.size() > 1)
			{
				return new ArrayList<>(set);
			}
		}
		return null;
	}

	/**
	 * True when the item's no-duplicate group is a "once" group: no protection once every item of it has been received.
	 */
	static boolean nodupOnce(Model m, String name)
	{
		for (Map.Entry<String, Set<String>> e : m.dep.nodupGroups.entrySet())
		{
			if (e.getValue().contains(name))
			{
				return Engine.onceGroup(e.getKey());
			}
		}
		return false;
	}

	/**
	 * The chances of all items of a "once" group after the set is complete: every item rolls at its own chance.
	 */
	private static double[] doneProbs(Model m, List<String> group, int[] counts, int k)
	{
		Map<String, Integer> c = new HashMap<>();
		for (int i = 0; i < group.size(); i++)
		{
			c.put(group.get(i), Math.max(1, counts == null ? 1 : counts[i]));
		}
		return m.pAtGroup(group, k, c);
	}

	/**
	 * The state that follows when item j of a no-duplicate group drops: it leaves the items at the fewest copies, and when none are left
	 * all of them are again (or, for a "once" group, the set is complete).
	 */
	private static int nextState(int s, int j, int full, int done, boolean once)
	{
		if (s == done)
		{
			return done;
		}
		int s2 = s & ~(1 << j);
		return s2 != 0 ? s2 : once ? done : full;
	}

	static final int NODUP_LIMIT = 200_000;

	/**
	 * The chances of a no-duplicate group's items in one state of the group (the bit mask of the items at the fewest copies), with
	 * the items outside the state at nothing.
	 */
	private static double[] stateProbs(Model m, List<String> group, int base, int state, int k)
	{
		Map<String, Integer> counts = new HashMap<>();
		for (int i = 0; i < group.size(); i++)
		{
			counts.put(group.get(i), base + (((state >> i) & 1) != 0 ? 0 : 1));
		}
		double[] all = m.pAtGroup(group, k, counts);
		double[] p = new double[all.length];
		for (int i = 0; i < p.length; i++)
		{
			p[i] = ((state >> i) & 1) != 0 ? all[i] : 0;
		}
		return p;
	}

	/**
	 * Chances of the next copy of an item of a no-duplicate group within the next n kills, and the kills to reach a chance: only the
	 * copies held the fewest of can drop, so an item that cannot drop now can once the others have.  The group's state (which items
	 * are at the fewest copies) is followed kill by kill.
	 */
	static void nodupForward(Model m, String x, List<String> group, int K, int[] windows, double[] cs, ItemAnalysis out, boolean once)
	{
		int n = group.size();
		int xi = group.indexOf(x);
		int full = (1 << n) - 1;
		// a "once" group whose set is complete: no item is held back any more
		final int done = full + 1;
		int mn = Integer.MAX_VALUE;
		int[] c0 = new int[n];
		for (int i = 0; i < n; i++)
		{
			c0[i] = m.ownedAt(group.get(i), K + 1);
			mn = Math.min(mn, c0[i]);
		}
		int s0 = 0;
		for (int i = 0; i < n; i++)
		{
			if (c0[i] == mn)
			{
				s0 |= 1 << i;
			}
		}
		if (once && mn >= 1)
		{
			s0 = done;
		}
		Map<Integer, Double> dist = new HashMap<>();
		dist.put(s0, 1.0);
		double absorbed = 0;
		int maxW = 0;
		for (int w : windows)
		{
			maxW = Math.max(maxW, w);
		}
		double[] want = cs.clone();
		Arrays.sort(want);
		int wi = 0;
		Map<Integer, Double> fwd = new HashMap<>();
		Map<Double, Double> kto = new LinkedHashMap<>();
		String lastCtx = null;
		Map<Integer, double[]> byS = new HashMap<>();
		int step = 0;
		while (step < NODUP_LIMIT && (step < maxW || wi < want.length) && !dist.isEmpty())
		{
			step++;
			int k = K + step;
			String ck = m.groupCtxKey(group, k);
			if (!ck.equals(lastCtx))
			{
				lastCtx = ck;
				byS = new HashMap<>();
			}
			Map<Integer, Double> nd = new HashMap<>();
			for (Map.Entry<Integer, Double> e : dist.entrySet())
			{
				int s = e.getKey();
				double q = e.getValue();
				double[] p = byS.get(s);
				if (p == null)
				{
					p = s == done ? doneProbs(m, group, c0, k) : stateProbs(m, group, mn, s, k);
					byS.put(s, p);
				}
				double tot = 0;
				for (double v : p)
				{
					tot += v;
				}
				absorbed += q * p[xi];
				if (tot < 1)
				{
					nd.merge(s, q * (1 - tot), Double::sum);
				}
				for (int j = 0; j < n; j++)
				{
					if (j == xi || !(p[j] > 0))
					{
						continue;
					}
					nd.merge(nextState(s, j, full, done, once), q * p[j], Double::sum);
				}
			}
			dist = nd;
			for (int w : windows)
			{
				if (w == step)
				{
					fwd.put(w, absorbed);
				}
			}
			while (wi < want.length && absorbed >= want[wi])
			{
				kto.put(want[wi], (double) step);
				wi++;
			}
		}
		for (int w : windows)
		{
			if (!out.fwd.containsKey(w))
			{
				out.fwd.put(w, fwd.containsKey(w) ? fwd.get(w) : absorbed);
			}
		}
		out.kto = new LinkedHashMap<>();
		for (double c : cs)
		{
			Double v = kto.get(c);
			out.kto.put(c, v != null ? v : Double.POSITIVE_INFINITY);
		}
	}

	/**
	 * The chances of the copies of an item of a no-duplicate group over kills 1..K, before knowing what dropped: which items can drop
	 * depends on what dropped before, so the chances as they were (nothing for an item between its copy and the rest of the set) would
	 * make every such item look lucky.  The group's state is followed kill by kill instead.
	 *
	 * @return P(at least n copies) for n = 0..cap, then the expected copies
	 */
	static double[] nodupCareer(Model m, String x, List<String> group, int K, int cap, boolean once)
	{
		int n = group.size();
		int xi = group.indexOf(x);
		int full = (1 << n) - 1;
		// a "once" group whose set is complete: no item is held back any more
		final int done = full + 1;
		int w = cap + 1;
		Map<Integer, Double> dist = new HashMap<>();
		dist.put(full * w, 1.0);
		double expected = 0;
		String lastCtx = null;
		Map<Integer, double[]> byS = new HashMap<>();
		for (int k = 1; k <= K; k++)
		{
			String ck = m.groupCtxKey(group, k);
			if (!ck.equals(lastCtx))
			{
				lastCtx = ck;
				byS = new HashMap<>();
			}
			Map<Integer, Double> nd = new HashMap<>();
			for (Map.Entry<Integer, Double> e : dist.entrySet())
			{
				int s = e.getKey() / w;
				int c = e.getKey() % w;
				double q = e.getValue();
				double[] p = byS.get(s);
				if (p == null)
				{
					p = s == done ? doneProbs(m, group, null, k) : stateProbs(m, group, 0, s, k);
					byS.put(s, p);
				}
				double tot = 0;
				for (double v : p)
				{
					tot += v;
				}
				expected += q * p[xi];
				if (q * (1 - tot) > 0)
				{
					nd.merge(s * w + c, q * (1 - tot), Double::sum);
				}
				for (int j = 0; j < n; j++)
				{
					if (!(p[j] > 0))
					{
						continue;
					}
					nd.merge(nextState(s, j, full, done, once) * w + (j == xi ? Math.min(cap, c + 1) : c), q * p[j], Double::sum);
				}
			}
			dist = nd;
		}
		double[] out = new double[w + 1];
		for (Map.Entry<Integer, Double> e : dist.entrySet())
		{
			int c = e.getKey() % w;
			for (int i = 0; i <= c; i++)
			{
				out[i] += e.getValue();
			}
		}
		out[w] = expected;
		return out;
	}

	/**
	 * The analysis of one item in one boss.
	 */
	public static final class ItemAnalysis
	{
		public String name;
		public int K;
		public SeqInfo seq;
		public int pity;
		public int O;
		public int unknown;
		public Integer hits;
		public boolean once;
		public double pNext;
		public boolean collected;
		public int need;
		public Double expected;
		public Double pct;
		public Double exceed;
		public Double cum;
		/**
		 * P(at least one more copy than the player has, from all their kills): how likely it is that the next copy would have come by
		 * now.  The kills made beyond the drop rate carry over to the next copy, so a drop does not send this back to zero.  Equal to
		 * {@link #cum} while the player has none; null before the first kill and for a drop that is already collected.
		 */
		public Double another;
		public Label label;
		public int streakFrom;
		public int streak;
		public double meter;
		/**
		 * False when the player has copies but none with a kill number, so nobody knows how long ago the last one was:
		 * {@link #streak} and {@link #meter} then count from the first kill and say nothing true.
		 */
		public boolean streakKnown = true;
		public final Map<Integer, Double> fwd = new LinkedHashMap<>();
		public Map<Double, Double> kto;
		public int window;
	}

	public static ItemAnalysis analyse(Model m, String name, int window)
	{
		final Boss boss = m.boss;
		final int K = m.K;
		final int win = window > 0 ? window : 50;
		ItemMeta meta = boss.meta().get(name);
		final SeqInfo seq = meta != null ? meta.seq : null;
		ItemAnalysis out = new ItemAnalysis();
		out.name = name;
		out.K = K;
		out.seq = seq;
		out.pity = meta != null ? meta.pity : 0;
		// copies and slot hits
		int O = m.copies(name);
		int unk = m.unknown(name);
		Integer H = null;
		List<String> members = null;
		List<Integer> knownAll = m.known(name);
		if (seq != null)
		{
			members = new ArrayList<>();
			for (Row r : slotMembers(boss, seq.slot))
			{
				members.add(r.name);
			}
			H = slotHits(m, boss, seq.slot);
			knownAll = new ArrayList<>();
			unk = 0;
			for (String n : members)
			{
				knownAll.addAll(m.known(n));
				unk += m.unknown(n);
			}
			Collections.sort(knownAll);
		}
		out.O = O;
		out.unknown = unk;
		out.hits = H;
		// dynamic "once" detection: probability with the item owned
		double pOwned = m.pAt(name, K + 1, 1);
		double pUn = m.pAt(name, K + 1, 0);
		out.once = pUn > 0 && pOwned == 0 && seq == null;
		out.pNext = m.pNext(name);
		out.collected = out.once && O > 0;
		// number of hits needed for the next copy
		int d = 1;
		if (seq != null)
		{
			int l0 = seq.len;
			d = (((seq.n - 1 - H) % l0) + l0) % l0 + 1;
		}
		out.need = d;
		final int dd = d;
		// career
		int lastKnown = knownAll.isEmpty() ? 0 : knownAll.get(knownAll.size() - 1);
		final String runName = seq != null ? members.get(0) : name;
		final List<Run> allRuns = K > 0 ? m.runsFor(runName, 1, K) : new ArrayList<Run>();
		out.expected = null;
		out.pct = null;
		final List<String> grp = seq == null ? nodupGroupOf(m, name) : null;
		if (K > 0)
		{
			java.util.function.IntToDoubleFunction needHits = mm -> mm <= 0 ? 0 : (seq != null ? seq.n + (mm - 1) * seq.len : mm);
			java.util.function.IntToDoubleFunction ge = mm -> mm <= 0 ? 1 : atLeast((int) needHits.applyAsDouble(mm), allRuns);
			if (grp != null && !out.once)
			{
				final double[] c = nodupCareer(m, name, grp, K, O + 1, nodupOnce(m, name));
				final int cap = O + 1;
				ge = mm -> mm <= 0 ? 1 : mm <= cap ? c[mm] : 0;
				out.pct = 1 - 0.5 * (ge.applyAsDouble(O) + ge.applyAsDouble(O + 1));
				out.another = ge.applyAsDouble(O + 1);
				out.expected = c[cap + 1];
			}
			else if (out.once && O > 0)
			{
				List<Integer> kn = m.known(name);
				if (!kn.isEmpty())
				{
					int k1 = kn.get(0);
					List<Run> r1 = m.runsFor(name, 1, k1 - 1);
					double pk = m.pAt(name, k1, 0);
					double sv = Math.exp(logSurv(r1));
					out.pct = sv * (1 - pk) + 0.5 * sv * pk; // P(T>k1) + 1/2 P(T=k1): first-passage mid-p
				}
				out.expected = sumP(allRuns);
			}
			else
			{
				out.pct = 1 - 0.5 * (ge.applyAsDouble(O) + ge.applyAsDouble(O + 1));
				out.another = ge.applyAsDouble(O + 1);
				if (seq != null)
				{
					double e = 0;
					for (int mm = 1; mm <= O + 12; mm++)
					{
						e += ge.applyAsDouble(mm);
					}
					out.expected = e;
				}
				else
				{
					out.expected = sumP(allRuns);
				}
			}
			out.exceed = ge.applyAsDouble(O); // P(at least as many as you have)
			out.cum = ge.applyAsDouble(1); // P(at least one over all your kills, whenever your drops came): never resets
		}
		out.label = luckLabel(out.pct);
		// progress meter: kills since the last receipt (hit of the slot for sequence items)
		out.streakFrom = lastKnown;
		out.streak = Math.max(0, K - lastKnown);
		out.streakKnown = !knownAll.isEmpty() || unk == 0;
		if (out.collected)
		{
			out.meter = 1;
		}
		else
		{
			List<Run> sr = out.streak > 0 ? m.runsFor(runName, lastKnown + 1, K) : new ArrayList<Run>();
			out.meter = out.streak > 0 ? atLeast(dd, sr) : 0;
		}
		// forward looking
		if (grp != null && !out.collected)
		{
			nodupForward(m, name, grp, K, new int[] {win, 10, 100, 500, 1000}, new double[] {0.5, 0.9, 0.99}, out, nodupOnce(m, name));
		}
		else if (!out.collected)
		{
			int[] ns = {win, 10, 100, 500, 1000};
			for (int n : ns)
			{
				if (!out.fwd.containsKey(n))
				{
					out.fwd.put(n, atLeast(dd, m.runsFor(runName, K + 1, K + n)));
				}
			}
			out.kto = new LinkedHashMap<>();
			for (double c : new double[] {0.5, 0.9, 0.99})
			{
				out.kto.put(c, killsTo(m, runName, dd, c, K));
			}
		}
		out.window = win;
		return out;
	}

	// ------------------------------------------------------------------ "any unique" synthetic item
	public static final class AnyUnique
	{
		public int O;
		public double expected;
		public double pct;
		public Label label;
		public double meter;
		public double cum;
		/**
		 * P(at least one more of these than the player has, from all their kills); see {@link ItemAnalysis#another}.
		 */
		public double another;
		public int streak;
		/**
		 * False when the player has uniques but none with a kill number (see {@link ItemAnalysis#streakKnown}).
		 */
		public boolean streakKnown = true;
		public final Map<Integer, Double> fwd = new LinkedHashMap<>();
		public int window;
		public double pNext;
		public int events;
	}

	/**
	 * One event per kill: "at least one of these items drops".  Computed inside the drop-table maths so items that cannot drop together
	 * (one table roll gives one item) are not treated as independent.  A sequence slot (the vestige) is one event for all its members.
	 */
	public static AnyUnique anyUnique(Model m, List<String> names, int window)
	{
		final Boss boss = m.boss;
		final int K = m.K;
		final int win = window > 0 ? window : 50;
		Map<String, ItemMeta> meta = boss.meta();
		Set<String> seen = new LinkedHashSet<>();
		List<String> evs = new ArrayList<>();
		// an item that only drops from a follow table (Sire's Font of Consumption, rolled once per Unsired) is part of its source's event
		Map<String, List<String>> fm = Engine.followMap(boss);
		Set<String> nset = new LinkedHashSet<>(names);
		Map<String, List<String>> kids = new HashMap<>();
		for (String n : names)
		{
			List<String> fs = fm.get(n);
			if (fs != null)
			{
				for (String f : fs)
				{
					if (nset.contains(f))
					{
						kids.computeIfAbsent(f, k -> new ArrayList<>()).add(n);
					}
				}
			}
		}
		for (String n : names)
		{
			ItemMeta mt = meta.get(n);
			if (mt == null || isKid(fm, nset, n))
			{
				continue;
			}
			if (mt.seq != null)
			{
				if (seen.contains(mt.seq.slot))
				{
					continue;
				}
				seen.add(mt.seq.slot);
			}
			evs.add(n);
		}
		if (evs.isEmpty() || K <= 0)
		{
			return null;
		}
		// O = kills that gave at least one of these items: copies on the same kill count once, copies with no kill number count one each,
		// and a slot's unlogged earlier hits are filled in
		int lastKnown = 0;
		int unk = 0;
		int extra = 0;
		Set<String> slots = new LinkedHashSet<>();
		Set<Integer> kcs = new LinkedHashSet<>();
		for (String n : names)
		{
			ItemMeta mt = meta.get(n);
			if (mt == null)
			{
				continue;
			}
			if (mt.seq != null)
			{
				if (slots.contains(mt.seq.slot))
				{
					continue;
				}
				slots.add(mt.seq.slot);
				int sumc = 0;
				for (Row r : slotMembers(boss, mt.seq.slot))
				{
					lastKnown = noteKnown(m, r.name, kcs, lastKnown);
					unk += m.unknown(r.name);
					sumc += m.copies(r.name);
				}
				extra += Math.max(0, slotHits(m, boss, mt.seq.slot) - sumc);
			}
			else
			{
				lastKnown = noteKnown(m, n, kcs, lastKnown);
				if (isKid(fm, nset, n))
				{
					continue;
				}
				int u = m.unknown(n);
				List<String> ks = kids.get(n);
				if (ks != null)
				{
					int t = 0;
					for (String k : ks)
					{
						t += m.unknown(k); // each Unsired gives one follow-table roll
					}
					u = Math.max(u, t);
				}
				unk += u;
			}
		}
		AnyUnique out = new AnyUnique();
		out.O = kcs.size() + unk + extra;
		List<Run> runsAll = m.runsForAny(evs, 1, K);
		out.pct = 1 - 0.5 * (atLeast(out.O, runsAll) + atLeast(out.O + 1, runsAll));
		List<Run> sr = K - lastKnown > 0 ? m.runsForAny(evs, lastKnown + 1, K) : new ArrayList<Run>();
		out.meter = K - lastKnown > 0 ? atLeast(1, sr) : 0;
		out.cum = atLeast(1, runsAll);
		out.another = atLeast(out.O + 1, runsAll);
		int[] ns = {win, 10, 100, 500};
		for (int n : ns)
		{
			out.fwd.put(n, atLeast(1, m.runsForAny(evs, K + 1, K + n)));
		}
		out.pNext = m.pAtAny(evs, K + 1);
		out.expected = sumP(runsAll);
		out.label = luckLabel(out.pct);
		out.streak = K - lastKnown;
		out.streakKnown = !kcs.isEmpty() || unk == 0;
		out.window = win;
		out.events = evs.size();
		return out;
	}

	private static boolean isKid(Map<String, List<String>> fm, Set<String> nset, String n)
	{
		List<String> fs = fm.get(n);
		if (fs == null)
		{
			return false;
		}
		for (String f : fs)
		{
			if (nset.contains(f))
			{
				return true;
			}
		}
		return false;
	}

	private static int noteKnown(Model m, String n, Set<Integer> kcs, int lastKnown)
	{
		List<Integer> ks = m.known(n);
		kcs.addAll(ks);
		if (!ks.isEmpty())
		{
			return Math.max(lastKnown, ks.get(ks.size() - 1));
		}
		return lastKnown;
	}

	// ------------------------------------------------------------------ pooled item (several bosses drop it)
	public static final class PoolMember
	{
		public final Model m;
		public final int snapKc;

		public PoolMember(Model m, int snapKc)
		{
			this.m = m;
			this.snapKc = snapKc;
		}
	}

	public static final class PoolPer
	{
		public String id;
		public String name;
		public int K;
		public int streak;
		public int copies;
	}

	public static final class Pool
	{
		public String name;
		public int O;
		public double expected;
		public double pct;
		public Label label;
		public double meter;
		public double cum;
		/**
		 * P(at least one more copy than the player has, over all these bosses' kills); see {@link ItemAnalysis#another}.
		 */
		public double another;
		public long streak;
		/**
		 * False when the player has copies but none with a kill number (see {@link ItemAnalysis#streakKnown}).
		 */
		public boolean streakKnown = true;
		public long kills;
		public final List<PoolPer> per = new ArrayList<>();
		public int window;
	}

	public static Pool analysePool(List<PoolMember> members, String name, int window)
	{
		final int win = window > 0 ? window : 50;
		int O = 0;
		int unknown = 0;
		boolean anyKnown = false;
		double expected = 0;
		List<List<Run>> runsAll = new ArrayList<>();
		List<List<Run>> sr = new ArrayList<>();
		List<PoolPer> per = new ArrayList<>();
		for (PoolMember pm : members)
		{
			Model m = pm.m;
			int K = m.K;
			O += m.copies(name);
			unknown += m.unknown(name);
			anyKnown |= !m.known(name).isEmpty();
			List<Run> ra = K > 0 ? m.runsFor(name, 1, K) : new ArrayList<Run>();
			runsAll.add(ra);
			expected += sumP(ra);
			int from = Math.min(K, Math.max(0, pm.snapKc));
			List<Run> rs = K - from > 0 ? m.runsFor(name, from + 1, K) : new ArrayList<Run>();
			sr.add(rs);
			PoolPer pp = new PoolPer();
			pp.id = m.boss.id;
			pp.name = m.boss.name;
			pp.K = K;
			pp.streak = K - from;
			pp.copies = m.copies(name);
			per.add(pp);
		}
		List<Run> all = mergeRuns(runsAll);
		List<Run> st = mergeRuns(sr);
		long kills = countKills(all);
		if (kills == 0)
		{
			return null;
		}
		Pool out = new Pool();
		out.name = name;
		out.O = O;
		out.expected = expected;
		out.pct = 1 - 0.5 * (atLeast(O, all) + atLeast(O + 1, all));
		out.label = luckLabel(out.pct);
		out.meter = atLeast(1, st);
		out.cum = atLeast(1, all);
		out.another = atLeast(O + 1, all);
		out.streak = countKills(st);
		out.streakKnown = anyKnown || unknown == 0;
		out.kills = kills;
		out.per.addAll(per);
		out.window = win;
		return out;
	}

	/**
	 * Convenience for tests: the chance list as plain strings.
	 */
	static String describe(List<Run> runs)
	{
		return Arrays.toString(runs.stream().map(r -> r.n + "x" + r.p).toArray());
	}
}

package com.dropluckledger.history;

import com.dropluckledger.capture.BossIndex;
import com.dropluckledger.engine.Catalog;
import com.dropluckledger.ledger.Drop;
import com.dropluckledger.ledger.Ledger;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Brings in, from the drop log, the copies of an item the player has just started to track.  The plugin logs every loot of its
 * bosses, tracked items or not, so the copies received before are there with the kill they came on:
 * <ul>
 * <li>a copy the ledger already has at that kill is left as it is;</li>
 * <li>otherwise a copy the ledger has with no kill number, brought in from game history after the loot came (so it counted that loot),
 * takes that kill number;</li>
 * <li>otherwise the copy is added, as seen in game.</li>
 * </ul>
 * Loot logged at a kill past the ledger's kill count is left out: it belongs to a ledger that has been replaced since.
 */
public final class Backfill
{
	private Backfill()
	{
	}

	/**
	 * What the drop log added.
	 */
	public static final class Result
	{
		/**
		 * Copies added.
		 */
		public int added;
		/**
		 * Copies with no kill number that got one.
		 */
		public int numbered;

		public boolean isEmpty()
		{
			return added == 0 && numbered == 0;
		}
	}

	/**
	 * @param log the logged loot (of any boss; only this boss's is used)
	 */
	public static Result apply(Ledger ledger, BossIndex index, String bossId, String item, List<LoggedLoot> log)
	{
		// kill number to the stacks of the item that came on it (a stack is one drop, as when it is recorded live)
		TreeMap<Integer, List<LoggedLoot.Item>> stacks = new TreeMap<>();
		Map<Integer, Map<String, Integer>> snaps = new LinkedHashMap<>();
		Map<Integer, Long> times = new LinkedHashMap<>();
		for (LoggedLoot l : log)
		{
			if (!bossId.equals(l.bossId) || l.kill < 1)
			{
				continue;
			}
			for (LoggedLoot.Item it : l.items)
			{
				if (it.qty > 0 && item.equals(index.item(bossId, it.name)))
				{
					stacks.computeIfAbsent(l.kill, k -> new ArrayList<>()).add(it);
					times.merge(l.kill, l.t, Math::min);
					if (l.snap != null)
					{
						snaps.put(l.kill, l.snap);
					}
				}
			}
		}
		Result r = new Result();
		if (stacks.isEmpty())
		{
			return r;
		}
		List<String> sharedWith = Catalog.logIndex(ledger.data()).get(item);
		ledger.update(bossId, s ->
		{
			for (Map.Entry<Integer, List<LoggedLoot.Item>> e : stacks.entrySet())
			{
				int kill = e.getKey();
				if (kill > s.kc)
				{
					continue;
				}
				int have = 0;
				for (Drop d : s.drops)
				{
					if (d.item.equals(item) && d.kc != null && d.kc == kill)
					{
						have++;
					}
				}
				List<LoggedLoot.Item> want = e.getValue();
				long when = times.get(kill);
				for (int i = have; i < want.size(); i++)
				{
					// an imported copy stands for this one only if the import came after it
					Drop unknown = null;
					for (Drop d : s.drops)
					{
						if (d.item.equals(item) && d.kc == null && Drop.SRC_IMPORT.equals(d.src) && d.t >= when)
						{
							unknown = d;
							break;
						}
					}
					if (unknown != null)
					{
						unknown.kc = kill;
						unknown.qty = Math.max(1, want.get(i).qty);
						unknown.src = Drop.SRC_LIVE;
						r.numbered++;
					}
					else
					{
						ledger.addDropLocked(bossId, s, item, kill, want.get(i).qty, snapFor(bossId, sharedWith, snaps.get(kill)), Drop.SRC_LIVE);
						r.added++;
					}
				}
			}
			return null;
		});
		return r;
	}

	/**
	 * The other bosses' kill counts that matter for the item: the ones that drop it too.
	 */
	private static Map<String, Integer> snapFor(String bossId, List<String> sharedWith, Map<String, Integer> snap)
	{
		if (snap == null || sharedWith == null || sharedWith.size() < 2)
		{
			return null;
		}
		Map<String, Integer> out = new LinkedHashMap<>();
		for (String other : sharedWith)
		{
			Integer k = snap.get(other);
			if (!other.equals(bossId) && k != null && k > 0)
			{
				out.put(other, k);
			}
		}
		return out.isEmpty() ? null : out;
	}
}

package com.dropluckledger.history;

import com.dropluckledger.capture.BossIndex;
import com.dropluckledger.capture.BossIndex.KcLabel;
import com.dropluckledger.capture.Capture;
import com.dropluckledger.engine.Catalog;
import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.history.HistoryPlanner.ItemRow;
import com.dropluckledger.history.HistoryPlanner.KcRow;
import com.dropluckledger.history.HistoryPlanner.Plan;
import com.dropluckledger.ledger.BossState;
import com.dropluckledger.ledger.Ledger;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.WeakHashMap;

/**
 * Checks the ledger against the game's own records as the player opens them and lists what they would change.  Nothing changes until
 * the player agrees: the list builds up over the records read since the player last added or dismissed it, so a run through several
 * pages makes one list.
 * <ul>
 * <li>Kill counts, from the Boss Kill Log and from the counts under a Collection Log page's title.  (The caller hands over a page's
 * counts as the game holds them once the page has settled, not as first drawn: the game can draw a page with the previous page's
 * numbers.)  When the records show every kill-count label of a boss, the ledger is set to their total, up or down, but never below the
 * kill of the latest drop with a kill number, which a note then points out; the latest look at each label counts.  When the Boss Kill
 * Log shows only some labels, it can only add the kills they show ({@link Capture#onShownCount}), and not at all when it leaves out the
 * awakened kills of a boss, as its other count may or may not hold them.  A page that shows only some of a boss's labels (the Desert
 * Treasure II bosses' pages have no awakened count) is not used for its kill count.</li>
 * <li>Items, from Collection Log pages.  A tracked item a page shows more copies of than the ledger has gets the missing copies with no
 * kill number, by the rules of <i>Add my game history…</i> ({@link HistoryPlanner}); an item several bosses drop that the page does not
 * pin to one boss is listed but not ticked.  An item the ledger has more copies of than the page shows loses the extra copies, when the
 * page's count is the number of times the item dropped: not an item that drops several at a time (the game counts how many were
 * received), not a pet (the ledger also counts a pet that dropped while the player already had it, which the game may not), and not a
 * count that may have stopped at the item's cap ({@link #MAY_BE_CAPPED}).  Extra copies of an item several bosses hold are pointed
 * out, as it is not known which boss's are wrong.  Items the player does not track are left alone.  The caller only hands over a page
 * whose items it has checked against what the game holds for it.</li>
 * </ul>
 * <p>
 * A read only speaks for a boss until the boss changes in the ledger (a kill, a drop, an edit by hand): after that its numbers are
 * older than the ledger's, so it is no longer used for that boss.  Likewise a list only adds the lines of bosses that have not changed
 * since it was made.
 */
public final class Catchup
{
	private static final String LOG = "Collection Log";
	private static final String KILL_LOG = "Boss Kill Log";
	private static final String KILL_LOG_KEY = "|kill log";
	private static final int LISTED = 3;
	/**
	 * The collection log stops counting some items at a cap that depends on the item: the wiki names 65,535 for Zulrah's scales
	 * and 250 for bracelets of ethereum, and has no full list.  A count this high may have stopped at its cap, so it never takes
	 * copies away.
	 */
	static final int MAY_BE_CAPPED = 250;

	/**
	 * One look at a page of the game's records.
	 */
	private static final class Read
	{
		/**
		 * The collection log page's title, or null for the Boss Kill Log.
		 */
		final String page;
		/**
		 * The counts shown, as the game words the activities: the Boss Kill Log's rows, or the lines under a page's title.
		 */
		final Map<String, Integer> counts;
		/**
		 * A page's items, as the game names them, to copies owned (empty for the Boss Kill Log).
		 */
		final Map<String, Integer> items;
		/**
		 * Every item on the page, owned or not.
		 */
		final Set<String> listed;
		/**
		 * Boss id to the ledger's revision of it when this was read.
		 */
		final Map<String, Long> revisions;

		Read(String page, Map<String, Integer> counts, Map<String, Integer> items, Collection<String> listed, Map<String, Long> revisions)
		{
			this.page = page;
			this.counts = new LinkedHashMap<>(counts);
			this.items = new LinkedHashMap<>(items);
			this.listed = new LinkedHashSet<>(listed);
			this.revisions = revisions;
		}
	}

	/**
	 * What a list was made from: the reads, and the ledger's revision of each boss then.
	 */
	private static final class Basis
	{
		final List<Read> reads;
		final Map<String, Long> revisions;

		Basis(List<Read> reads, Map<String, Long> revisions)
		{
			this.reads = reads;
			this.revisions = revisions;
		}
	}

	private final Ledger ledger;
	private final Capture capture;
	private final HistoryPlanner planner;
	private final BossIndex index;
	private final Data data;
	/**
	 * The records read since the last time the player added or dismissed them, the latest look at each page last.
	 */
	private final LinkedHashMap<String, Read> reads = new LinkedHashMap<>();
	/**
	 * The reads each list still on show was made from: adding a list lets go of those, not of reads that came after it.
	 */
	private final Map<Plan, Basis> plannedFrom = new WeakHashMap<>();

	public Catchup(Ledger ledger, Capture capture, HistoryPlanner planner, BossIndex index)
	{
		this.ledger = ledger;
		this.capture = capture;
		this.planner = planner;
		this.index = index;
		this.data = ledger.data();
	}

	/**
	 * The ledger's revision of every boss at one moment.  A read is stamped with the moment the game sent its numbers (they are on
	 * screen a little later), so a kill or a drop the ledger took in between makes it older than the ledger for that boss.
	 */
	public static final class Stamp
	{
		private final Map<String, Long> revisions;

		private Stamp(Map<String, Long> revisions)
		{
			this.revisions = revisions;
		}
	}

	/**
	 * The ledger as it is now, to stamp a read with.
	 */
	public synchronized Stamp stamp()
	{
		return new Stamp(revisions());
	}

	/**
	 * True when no boss a page speaks for has changed since the stamp: the bosses whose collection log lists one of its items, and the
	 * bosses of its counts.
	 *
	 * @param gameNames the page's items, as the game names them
	 * @param counts    the page's counts, as the game words them
	 */
	public synchronized boolean unchangedSince(Stamp then, Collection<String> gameNames, Collection<String> counts)
	{
		for (String name : gameNames)
		{
			String item = planner.itemFor(name);
			if (item != null && !unchanged(then.revisions, planner.bossesFor(item)))
			{
				return false;
			}
		}
		for (String shown : counts)
		{
			KcLabel kl = index.kcShown(shown);
			if (kl != null && !unchanged(then.revisions, Collections.singletonList(kl.bossId)))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * A collection log page that has settled.
	 *
	 * @param counts the counts under its title, as the game words them, with the values the game holds for them now
	 * @param items  item (as the game names it) to copies owned
	 * @param listed every item on the page, owned or not
	 * @param drawn  the ledger as it was when the page was drawn
	 */
	public synchronized void addPage(String title, Map<String, Integer> counts, Map<String, Integer> items, Collection<String> listed, Stamp drawn)
	{
		String key = "page|" + title;
		reads.remove(key);
		reads.put(key, new Read(title, counts, items, listed, new HashMap<>(drawn.revisions)));
	}

	/**
	 * The Boss Kill Log: activity as the screen wrote it, to the count.
	 *
	 * @param opened the ledger as it was when the log opened (the server sends its counts with it)
	 */
	public synchronized void addKillLog(Map<String, Integer> counts, Stamp opened)
	{
		reads.remove(KILL_LOG_KEY);
		reads.put(KILL_LOG_KEY, new Read(null, counts, Collections.<String, Integer>emptyMap(), Collections.<String>emptyList(),
			new HashMap<>(opened.revisions)));
	}

	/**
	 * The ledger's revision of every boss now.
	 */
	private Map<String, Long> revisions()
	{
		Map<String, Long> out = new HashMap<>();
		for (Boss b : data.bosses)
		{
			out.put(b.id, ledger.revision(b.id));
		}
		return out;
	}

	/**
	 * True when none of the bosses has changed in the ledger since the given revisions were taken.
	 */
	private boolean unchanged(Map<String, Long> then, Collection<String> bossIds)
	{
		for (String id : bossIds)
		{
			Long rev = then.get(id);
			if (rev == null || rev != ledger.revision(id))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Forgets what was read (the player dismissed it, or another account logged in).
	 */
	public synchronized void clear()
	{
		reads.clear();
		plannedFrom.clear();
	}

	// ------------------------------------------------------------------ the list

	/**
	 * What the records read so far would change, against the ledger as it is now.
	 */
	public synchronized Plan plan()
	{
		Plan plan = new Plan();
		plannedFrom.put(plan, new Basis(new ArrayList<>(reads.values()), revisions()));
		List<String> pages = new ArrayList<>();
		for (Read r : reads.values())
		{
			if (r.page == null)
			{
				plan.sources.add(KILL_LOG);
			}
			else
			{
				pages.add(r.page);
			}
		}
		if (!pages.isEmpty())
		{
			plan.sources.add(LOG + " (" + (pages.size() <= LISTED ? String.join(", ", pages)
				: String.join(", ", pages.subList(0, LISTED - 1)) + " and " + (pages.size() - LISTED + 1) + " more pages") + ")");
		}
		killCounts(plan);
		addedItems(plan);
		extraItems(plan);
		plan.kc.sort(Comparator.comparing(r -> r.name, String.CASE_INSENSITIVE_ORDER));
		plan.items.sort(Comparator.<ItemRow, String>comparing(r -> r.bossName, String.CASE_INSENSITIVE_ORDER).thenComparing(r -> r.item));
		return plan;
	}

	private List<String> labelNames(String bossId)
	{
		List<String> out = new ArrayList<>();
		for (KcLabel kl : index.labels(bossId))
		{
			out.add(kl.label);
		}
		return out;
	}

	/**
	 * True when a boss's awakened kills are not among the counts shown: then the other count may or may not hold them.
	 */
	private boolean hidesAwakened(String bossId, Collection<String> shown)
	{
		for (String label : labelNames(bossId))
		{
			if (label.startsWith("Awakened ") && !shown.contains(label))
			{
				return true;
			}
		}
		return false;
	}

	private void killCounts(Plan plan)
	{
		// each label's latest count, over the reads that still speak for its boss
		Map<String, Map<String, Integer>> byBoss = new LinkedHashMap<>();
		for (Read r : reads.values())
		{
			Map<String, Map<String, Integer>> found = new LinkedHashMap<>();
			for (Map.Entry<String, Integer> e : r.counts.entrySet())
			{
				KcLabel kl = e.getValue() == null || e.getValue() < 0 ? null : index.kcShown(e.getKey());
				if (kl != null)
				{
					found.computeIfAbsent(kl.bossId, k -> new LinkedHashMap<>()).merge(kl.label, e.getValue(), Math::max);
				}
			}
			for (Map.Entry<String, Map<String, Integer>> e : found.entrySet())
			{
				Boss b = data.boss(e.getKey());
				Set<String> shown = e.getValue().keySet();
				// every claimed reward is one run (the game's own count measures something else); a boss that changed after the read has
				// a newer count than the read's; a page with only some of a boss's counts does not say what the others are; and a log
				// without a boss's awakened kills may or may not count them elsewhere
				if (b == null || b.lootIsClaim() || !unchanged(r.revisions, Collections.singletonList(b.id))
					|| !shown.containsAll(labelNames(b.id)) && (r.page != null || hidesAwakened(b.id, shown)))
				{
					continue;
				}
				byBoss.computeIfAbsent(b.id, k -> new LinkedHashMap<>()).putAll(e.getValue());
			}
		}
		for (Map.Entry<String, Map<String, Integer>> e : byBoss.entrySet())
		{
			String id = e.getKey();
			if (capture.awaitingLoot(id))
			{
				continue; // a kill's loot is still to come and takes the count as it is then: the next look catches up
			}
			Map<String, Integer> labels = e.getValue();
			BossState s = ledger.copyOf(id);
			int cur = s.kc;
			String name = data.boss(id).name;
			if (labels.keySet().containsAll(labelNames(id)))
			{
				int total = 0;
				for (int n : labels.values())
				{
					total += n;
				}
				int floor = s.maxDropKc();
				if (total > cur)
				{
					plan.kc.add(new KcRow(id, name, cur, total, labels));
				}
				else if (total < cur && Math.max(total, floor) < cur)
				{
					plan.kc.add(new KcRow(id, name, cur, Math.max(total, floor), labels, true));
				}
				if (total < cur && floor > total)
				{
					plan.notes.add(name + ": the game counts " + count(total) + (total == 1 ? " kill" : " kills") + ", but the ledger has a drop at kill "
						+ count(floor) + ", so its kill count cannot go below that. If that kill number is wrong, change it on the boss's page.");
				}
				continue;
			}
			// only some of the boss's counts: the kills they add, as when they are seen live
			for (Map.Entry<String, Integer> l : labels.entrySet())
			{
				if (l.getValue() > 0)
				{
					Capture.raiseLocked(s, l.getKey(), l.getValue());
				}
			}
			if (s.kc > cur)
			{
				plan.kc.add(new KcRow(id, name, cur, s.kc, labels));
			}
		}
	}

	private void addedItems(Plan plan)
	{
		HistoryInput in = new HistoryInput();
		for (Read r : reads.values())
		{
			for (Map.Entry<String, Integer> e : r.items.entrySet())
			{
				if (current(r, e.getKey()))
				{
					in.addOwned(null, r.page, e.getKey(), e.getValue(), LOG);
				}
			}
		}
		if (in.owned.isEmpty())
		{
			return;
		}
		Plan items = planner.plan(in);
		for (ItemRow row : items.items)
		{
			if (row.add <= 0 || !ledger.trackedNames(row.bossId).contains(row.item))
			{
				continue;
			}
			if (row.assumed)
			{
				row.on = false; // several bosses drop it and the page did not say which: the player decides
			}
			plan.items.add(row);
		}
		plan.itemsMissing.addAll(items.itemsMissing);
	}

	/**
	 * True when no boss whose collection log lists an item (named as the game names it) has changed since the read.
	 */
	private boolean current(Read r, String gameName)
	{
		String item = planner.itemFor(gameName);
		return item == null || unchanged(r.revisions, planner.bossesFor(item));
	}

	/**
	 * The copies of tracked items that the ledger has more of than the pages show.  A page's count of an item is the game's count over
	 * every boss that drops it, so it is set against the copies all of them hold.
	 */
	private void extraItems(Plan plan)
	{
		// the count the latest page listing each item shows (0 when it is drawn faded)
		Map<String, Integer> shown = new LinkedHashMap<>();
		for (Read r : reads.values())
		{
			// a page that draws every item faded may have been drawn before its numbers came: it takes nothing away
			if (r.items.isEmpty())
			{
				continue;
			}
			Map<String, Integer> here = new LinkedHashMap<>();
			for (String name : r.listed)
			{
				String item = planner.itemFor(name);
				if (item != null && current(r, name))
				{
					Integer n = r.items.get(name);
					here.merge(item, n == null ? 0 : n, Math::max);
				}
			}
			shown.putAll(here);
		}
		// each boss's state is looked at for many items: copied once
		Map<String, BossState> copies = new HashMap<>();
		for (Map.Entry<String, Integer> e : shown.entrySet())
		{
			String item = e.getKey();
			int game = e.getValue();
			if (game >= MAY_BE_CAPPED)
			{
				continue;
			}
			List<String> holders = new ArrayList<>();
			Map<String, BossState> states = new LinkedHashMap<>();
			int held = 0;
			boolean dropCount = true;
			for (String id : planner.bossesFor(item))
			{
				BossState s = copies.computeIfAbsent(id, ledger::copyOf);
				int n = s.copies(item);
				if (n == 0)
				{
					continue;
				}
				Boss boss = data.boss(id);
				dropCount &= ledger.trackedNames(id).contains(item) && !"pet".equals(Catalog.kindOf(boss, item)) && Quantities.oneAtATime(boss, item);
				holders.add(id);
				states.put(id, s);
				held += n;
			}
			int extra = held - game;
			if (!dropCount || extra <= 0)
			{
				continue;
			}
			// copies a history import added with no kill number are guesses wherever they are; the import puts an item it cannot pin
			// to one boss at the one with the most kills, so the other bosses lose theirs first
			holders.sort(Comparator.comparingInt(id -> states.get(id).kc));
			Map<String, Integer> imported = new LinkedHashMap<>();
			for (String id : holders)
			{
				int take = Math.min(extra, states.get(id).importedUnknown(item));
				if (take > 0)
				{
					imported.put(id, take);
					extra -= take;
				}
			}
			List<String> still = new ArrayList<>();
			for (String id : holders)
			{
				if (states.get(id).copies(item) > imported.getOrDefault(id, 0))
				{
					still.add(id);
				}
			}
			if (extra > 0 && still.size() == 1)
			{
				String id = still.get(0);
				int take = extra + imported.getOrDefault(id, 0);
				imported.remove(id);
				plan.items.add(ItemRow.extra(id, data.boss(id).name, item, game, states.get(id).copies(item), take, false));
				extra = 0;
			}
			for (Map.Entry<String, Integer> t : imported.entrySet())
			{
				plan.items.add(ItemRow.extra(t.getKey(), data.boss(t.getKey()).name, item, game, states.get(t.getKey()).copies(item), t.getValue(), true));
			}
			if (extra > 0 && still.size() > 1)
			{
				List<String> names = new ArrayList<>();
				for (String id : still)
				{
					names.add(data.boss(id).name);
				}
				plan.notes.add("The ledger has " + extra + " more " + item + " than the collection log shows, split between " + join(names)
					+ ": remove the wrong " + (extra == 1 ? "copy on its boss page." : "copies on their boss pages."));
			}
		}
	}

	// ------------------------------------------------------------------ adding it

	/**
	 * Makes the ticked changes of a list, then forgets the reads it was made from.  Each line is checked against the ledger as it is now.
	 * A list made before the reads were forgotten (dismissed, or another account logged in) changes nothing.
	 *
	 * @return {kill counts changed, copies added, copies taken away, ticked lines left out because their boss changed after the list was
	 * made or a kill of it waits for its loot}
	 */
	public synchronized int[] apply(Plan plan)
	{
		Basis basis = plannedFrom.remove(plan);
		if (basis == null)
		{
			return new int[4];
		}
		// a boss that changed after the list was made (a kill, a drop) keeps what it has: the list's numbers are older than its own
		Set<String> changed = new HashSet<>();
		for (Map.Entry<String, Long> e : basis.revisions.entrySet())
		{
			if (e.getValue() != ledger.revision(e.getKey()))
			{
				changed.add(e.getKey());
			}
		}
		Map<String, Long> atStart = revisions();
		int kills = 0;
		int added = 0;
		int removed = 0;
		int left = 0;
		for (KcRow r : plan.kc)
		{
			if (!r.on || !r.changes())
			{
				continue;
			}
			if (changed.contains(r.bossId) || capture.awaitingLoot(r.bossId))
			{
				left++;
				continue;
			}
			if (r.lower)
			{
				kills += ledger.kcToGame(r.bossId, r.labels, r.to) ? 1 : 0;
				continue;
			}
			int before = ledger.kc(r.bossId);
			for (Map.Entry<String, Integer> e : r.labels.entrySet())
			{
				if (e.getValue() > 0)
				{
					capture.onShownCount(e.getKey(), e.getValue());
				}
			}
			if (r.labels.keySet().containsAll(labelNames(r.bossId)))
			{
				// the game's total of every kill is the count, whatever the ledger had seen of it before
				int total = 0;
				for (int n : r.labels.values())
				{
					total += n;
				}
				ledger.kcToGame(r.bossId, r.labels, total);
			}
			kills += ledger.kc(r.bossId) != before ? 1 : 0;
		}
		for (ItemRow r : plan.items)
		{
			if (!r.on || r.add <= 0 && r.remove <= 0)
			{
				continue;
			}
			if (changed.contains(r.bossId))
			{
				left++;
				continue;
			}
			if (r.extra)
			{
				removed += ledger.removeExtra(r.bossId, r.item, r.remove, r.importedOnly);
			}
			else if (r.add > 0)
			{
				int have = ledger.copies(r.bossId, r.item);
				added += ledger.addOwned(r.bossId, r.item, Math.max(0, Math.min(r.want, r.cap()) - have));
			}
		}
		for (Read r : basis.reads)
		{
			reads.values().remove(r);
		}
		// the reads left came from the same game as this list: what was just added does not make them older than the ledger
		for (Read r : reads.values())
		{
			for (Map.Entry<String, Long> e : atStart.entrySet())
			{
				if (e.getValue().equals(r.revisions.get(e.getKey())))
				{
					r.revisions.put(e.getKey(), ledger.revision(e.getKey()));
				}
			}
		}
		return new int[]{kills, added, removed, left};
	}

	// ------------------------------------------------------------------ the words

	/**
	 * One line for the player about a list: "Boss Kill Log, Collection Log (Skotizo): kill count Skotizo 117 → 5; Dark claw −1.  Nothing
	 * changes until you add them."  A list with nothing to change says its first note.
	 */
	public static String describe(Plan plan)
	{
		List<String> kills = new ArrayList<>();
		List<String> items = new ArrayList<>();
		int moreKills = 0;
		int moreItems = 0;
		int unticked = 0;
		for (KcRow r : plan.kc)
		{
			if (!r.changes())
			{
				continue;
			}
			if (!r.on)
			{
				unticked++;
			}
			else if (kills.size() < LISTED)
			{
				kills.add(r.name + " " + count(r.cur) + " → " + count(r.to));
			}
			else
			{
				moreKills++;
			}
		}
		for (ItemRow r : plan.items)
		{
			if (r.add <= 0 && r.remove <= 0)
			{
				continue;
			}
			if (!r.on)
			{
				unticked++;
			}
			else if (items.size() < LISTED)
			{
				items.add(r.item + (r.extra ? " −" + count(r.remove) : " +" + count(r.add)));
			}
			else
			{
				moreItems++;
			}
		}
		List<String> parts = new ArrayList<>();
		if (!kills.isEmpty())
		{
			parts.add((kills.size() + moreKills == 1 ? "kill count " : "kill counts ") + String.join(", ", kills)
				+ (moreKills > 0 ? " and " + moreKills + " more" : ""));
		}
		if (!items.isEmpty())
		{
			parts.add(String.join(", ", items) + (moreItems > 0 ? " and " + moreItems + " more item" + (moreItems == 1 ? "" : "s") : ""));
		}
		StringBuilder b = new StringBuilder(String.join(", ", plan.sources)).append(": ");
		if (parts.isEmpty())
		{
			if (unticked == 0 && !plan.notes.isEmpty())
			{
				b.append(plan.notes.get(0));
				int others = plan.notes.size() - 1;
				return others == 0 ? b.toString() : b.append(" Review it for ").append(others).append(others == 1 ? " more note." : " more notes.").toString();
			}
			b.append(unticked).append(" line").append(unticked == 1 ? "" : "s").append(" to look at");
			return b.append(". Review it to choose what to add.").toString();
		}
		b.append(String.join("; ", parts)).append('.');
		if (unticked > 0)
		{
			b.append(' ').append(unticked).append(" more line").append(unticked == 1 ? "" : "s").append(" to look at.");
		}
		int changes = kills.size() + moreKills + items.size() + moreItems;
		return b.append(" Nothing changes until you add ").append(changes == 1 ? "it." : "them.").toString();
	}

	/**
	 * True when a list holds anything for the player: a line that changes something, or a note.
	 */
	public static boolean worthShowing(Plan plan)
	{
		for (KcRow r : plan.kc)
		{
			if (r.changes())
			{
				return true;
			}
		}
		for (ItemRow r : plan.items)
		{
			if (r.add > 0 || r.remove > 0)
			{
				return true;
			}
		}
		return !plan.notes.isEmpty();
	}

	private static String count(int n)
	{
		return String.format(Locale.ROOT, "%,d", n);
	}

	private static String join(List<String> l)
	{
		if (l.size() < 2)
		{
			return String.join("", l);
		}
		return String.join(", ", l.subList(0, l.size() - 1)) + " and " + l.get(l.size() - 1);
	}
}

package com.dropluckledger.history;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Everything gathered from the game's own records, before it is matched against the ledger.
 */
public final class HistoryInput
{
	/**
	 * Copies of an item the player owns.
	 */
	public static final class Owned
	{
		/**
		 * The boss, when the source says exactly which one (the loot tracker does); otherwise null.
		 */
		public final String bossId;
		/**
		 * Collection log page the item was seen on, when the source has pages; otherwise null.
		 */
		public final String page;
		public final String item;
		public final int count;

		Owned(String bossId, String page, String item, int count)
		{
			this.bossId = bossId;
			this.page = page;
			this.item = item;
			this.count = count;
		}
	}

	/**
	 * Activity name as the game or hiscores print it, to the kill count (the largest if several sources have one).
	 */
	public final Map<String, Integer> kc = new LinkedHashMap<>();
	public final List<Owned> owned = new ArrayList<>();
	/**
	 * Where the data came from, for display.
	 */
	public final Set<String> sources = new LinkedHashSet<>();

	public void addKc(String name, int n, String source)
	{
		if (name == null || n <= 0)
		{
			return;
		}
		kc.merge(name, n, Math::max);
		sources.add(source);
	}

	public void addOwned(String bossId, String page, String item, int count, String source)
	{
		if (item == null || count <= 0)
		{
			return;
		}
		owned.add(new Owned(bossId, page, item, count));
		sources.add(source);
	}

	public boolean isEmpty()
	{
		return kc.isEmpty() && owned.isEmpty();
	}
}

package com.dropluckledger.history;

import com.dropluckledger.capture.BossIndex;
import com.dropluckledger.capture.BossIndex.KcLabel;
import com.dropluckledger.capture.Names;
import com.dropluckledger.engine.Catalog;
import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Engine;
import com.dropluckledger.ledger.BossState;
import com.dropluckledger.ledger.Ledger;
import com.dropluckledger.ledger.Period;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Works out what the game's records add to the ledger, and applies it.
 * <p>
 * No game record says which kill an old drop came on, so history can only bring in kill counts and "owned copies"
 * (items with an unknown kill number).  Running it twice, or after the plugin has seen the same drops live, adds nothing
 * twice: copies already in the ledger are subtracted, and kill counts only ever go up.
 */
public final class HistoryPlanner
{
	/**
	 * Same cap as the web app: more copies than this is almost certainly a mistake in the source.  A boss with more kills than
	 * this allows as many copies as it has kills.
	 */
	public static final int MAX_COPIES = 200;

	/**
	 * A kill count to set.
	 */
	public static final class KcRow
	{
		public final String bossId;
		public final String name;
		public final int cur;
		public final int to;
		/**
		 * Kill-count label (as in the boss data) to the count the source had.
		 */
		public final Map<String, Integer> labels;
		/**
		 * The game's count is below the ledger's: the line brings the ledger down to it (only from the game's own records, when they
		 * show every kill count of the boss).
		 */
		public final boolean lower;
		public boolean on;

		KcRow(String bossId, String name, int cur, int to, Map<String, Integer> labels)
		{
			this(bossId, name, cur, to, labels, false);
		}

		KcRow(String bossId, String name, int cur, int to, Map<String, Integer> labels, boolean lower)
		{
			this.bossId = bossId;
			this.name = name;
			this.cur = cur;
			this.to = to;
			this.labels = labels;
			this.lower = lower;
			this.on = lower ? to < cur : to > cur;
		}

		/**
		 * True when ticking the line changes something.
		 */
		public boolean changes()
		{
			return lower ? to < cur : to > cur;
		}

		/**
		 * The game's count as read: its kill-count labels' counts added up.
		 */
		public int shown()
		{
			int n = 0;
			for (int v : labels.values())
			{
				n += v;
			}
			return n;
		}
	}

	/**
	 * Copies (drops) of one item to add.
	 */
	public static final class ItemRow
	{
		public final String bossId;
		public final String bossName;
		public final String item;
		/**
		 * How many drops the source stands for.
		 */
		public final int want;
		public final int have;
		public final int add;
		/**
		 * Copies an earlier import added with no kill number that the source does not support, because they counted every item of a
		 * stack as a drop.  Only set for rows worked out from a quantity.
		 */
		public final int remove;
		/**
		 * The most drops of this item the ledger takes for the boss.
		 */
		final int cap;
		/**
		 * Several bosses drop this item and the source did not say which: it went to the one with the most kills.
		 */
		public final boolean assumed;
		/**
		 * How many of the item the source said were received, when that is not the number of drops (a stackable item such as bolt
		 * racks arrives several at a time, so {@link #want} is worked out from this); 0 when {@link #want} is exactly what the
		 * source said.
		 */
		public final int quantity;
		/**
		 * The collection log shows fewer of the item than the ledger has: {@link #remove} copies go, the ones least likely to be right
		 * first (see {@code Ledger.removeExtra}).
		 */
		public final boolean extra;
		/**
		 * With {@link #extra}: only copies a history import added with no kill number go (the item is held at several bosses).
		 */
		public final boolean importedOnly;
		public boolean on;

		ItemRow(String bossId, String bossName, String item, int want, int have, int imported, int cap, boolean assumed, int quantity)
		{
			this.bossId = bossId;
			this.bossName = bossName;
			this.item = item;
			this.want = want;
			this.have = have;
			this.cap = cap;
			this.add = Math.max(0, Math.min(want, cap) - have);
			this.remove = quantity > 0 ? Math.min(imported, Math.max(0, have - Math.min(want, cap))) : 0;
			this.assumed = assumed;
			this.quantity = quantity;
			this.extra = false;
			this.importedOnly = false;
			this.on = add > 0 || remove > 0;
		}

		private ItemRow(String bossId, String bossName, String item, int shown, int have, int remove, boolean importedOnly)
		{
			this.bossId = bossId;
			this.bossName = bossName;
			this.item = item;
			this.want = shown;
			this.have = have;
			this.cap = Integer.MAX_VALUE;
			this.add = 0;
			this.remove = remove;
			this.assumed = false;
			this.quantity = 0;
			this.extra = true;
			this.importedOnly = importedOnly;
			this.on = remove > 0;
		}

		/**
		 * A line taking away copies the collection log does not show.
		 *
		 * @param shown how many the collection log shows, over every boss that drops the item
		 * @param have  the copies this boss holds
		 */
		static ItemRow extra(String bossId, String bossName, String item, int shown, int have, int remove, boolean importedOnly)
		{
			return new ItemRow(bossId, bossName, item, shown, have, remove, importedOnly);
		}

		/**
		 * The most copies the row may bring the boss to.
		 */
		int cap()
		{
			return cap;
		}

		/**
		 * True when {@link #want} is an estimate from a received quantity rather than a count of drops.
		 */
		public boolean estimated()
		{
			return quantity > 0;
		}
	}

	public static final class Plan
	{
		public final List<KcRow> kc = new ArrayList<>();
		public final List<ItemRow> items = new ArrayList<>();
		/**
		 * Kill-count entries that are not a boss in the ledger ("name count").
		 */
		public final List<String> kcSkipped = new ArrayList<>();
		/**
		 * Item names that are not tracked.
		 */
		public final List<String> itemsMissing = new ArrayList<>();
		public int itemsTotal;
		public final Set<String> sources = new LinkedHashSet<>();
		/**
		 * Things the records show that no line can settle, for the player to look at (an item one boss too many holds, at several
		 * bosses).
		 */
		public final List<String> notes = new ArrayList<>();

		public int kcToApply()
		{
			int n = 0;
			for (KcRow r : kc)
			{
				if (r.on && r.changes())
				{
					n++;
				}
			}
			return n;
		}

		public int itemRowsToApply()
		{
			int n = 0;
			for (ItemRow r : items)
			{
				if (r.on && (r.add > 0 || r.remove > 0))
				{
					n++;
				}
			}
			return n;
		}

		public int copiesToAdd()
		{
			int n = 0;
			for (ItemRow r : items)
			{
				if (r.on)
				{
					n += r.add;
				}
			}
			return n;
		}

		/**
		 * Copies of an earlier import that the rows ticked would take back.
		 */
		public int copiesToRemove()
		{
			int n = 0;
			for (ItemRow r : items)
			{
				if (r.on)
				{
					n += r.remove;
				}
			}
			return n;
		}

		public boolean isEmpty()
		{
			return kcToApply() == 0 && copiesToAdd() == 0 && copiesToRemove() == 0;
		}
	}

	private final Ledger ledger;
	private final Data data;
	private final BossIndex index;
	private final Map<String, List<String>> logIndex;
	private final Map<String, String> itemKey = new HashMap<>();

	public HistoryPlanner(Ledger ledger, BossIndex index)
	{
		this.ledger = ledger;
		this.data = ledger.data();
		this.index = index;
		this.logIndex = Catalog.logIndex(data);
		for (String n : logIndex.keySet())
		{
			itemKey.putIfAbsent(Names.flat(n), n);
		}
		// collection log pages use the game's names, which differ from the wiki's for a few items
		for (Boss b : data.bosses)
		{
			for (Data.Row r : b.allRows())
			{
				String game = r.attr("game");
				if (r.log && game != null && !game.isEmpty())
				{
					itemKey.putIfAbsent(Names.flat(game), r.name);
				}
			}
		}
	}

	public Plan plan(HistoryInput in)
	{
		Plan plan = new Plan();
		plan.sources.addAll(in.sources);

		// ---- kill counts: one row per boss, summing its modes
		Map<String, Map<String, Integer>> byBoss = new LinkedHashMap<>();
		for (Map.Entry<String, Integer> e : in.kc.entrySet())
		{
			KcLabel kl = index.kc(e.getKey());
			if (kl == null)
			{
				plan.kcSkipped.add(e.getKey() + " " + e.getValue());
				continue;
			}
			byBoss.computeIfAbsent(kl.bossId, k -> new LinkedHashMap<>()).merge(kl.label, e.getValue(), Math::max);
		}
		Map<String, Integer> kcTo = new HashMap<>();
		for (Map.Entry<String, Map<String, Integer>> e : byBoss.entrySet())
		{
			int sum = 0;
			for (int v : e.getValue().values())
			{
				sum += v;
			}
			kcTo.put(e.getKey(), sum);
			plan.kc.add(new KcRow(e.getKey(), data.boss(e.getKey()).name, ledger.kc(e.getKey()), sum, e.getValue()));
		}
		plan.kc.sort(Comparator.<KcRow>comparingInt(r -> -r.to).thenComparing(r -> r.name));

		// ---- owned copies
		Map<String, Integer> exact = new HashMap<>(); // bossId|item -> drops the source named a boss for
		Map<String, Integer> quantities = new HashMap<>(); // bossId|item -> the received quantity behind it, when that is not the drops
		class Page
		{
			int n;
			final List<String> pages = new ArrayList<>();
		}
		Map<String, Page> perItem = new LinkedHashMap<>();
		LinkedHashSet<String> missing = new LinkedHashSet<>();
		// what the sources that name the boss received, summed over their records (one per name the boss's loot goes by)
		Map<String, Integer> exactQty = new LinkedHashMap<>();
		for (HistoryInput.Owned o : in.owned)
		{
			plan.itemsTotal++;
			if (o.bossId != null)
			{
				Boss b = data.boss(o.bossId);
				String item = b == null ? null : index.item(o.bossId, o.item);
				if (item == null || !Catalog.defaultTracked(b).contains(item))
				{
					missing.add(o.item);
					continue;
				}
				exactQty.merge(o.bossId + '|' + item, o.count, Integer::sum);
				continue;
			}
			String item = itemKey.get(Names.flat(o.item));
			if (item == null)
			{
				missing.add(o.item);
				continue;
			}
			Page p = perItem.computeIfAbsent(item, k -> new Page());
			p.n = Math.max(p.n, o.count); // a received quantity, not yet drops
			if (o.page != null)
			{
				p.pages.add(Names.norm(o.page));
			}
		}
		for (Map.Entry<String, Integer> e : exactQty.entrySet())
		{
			String key = e.getKey();
			Boss b = data.boss(key.substring(0, key.indexOf('|')));
			String item = key.substring(key.indexOf('|') + 1);
			int drops = Quantities.drops(b, item, e.getValue());
			exact.put(key, drops);
			if (drops != e.getValue())
			{
				quantities.put(key, e.getValue());
			}
		}
		Map<String, int[]> want = new LinkedHashMap<>(); // bossId|item -> {copies, assumed}
		Map<String, BossState> state = new HashMap<>(); // each boss's state, copied once
		for (Map.Entry<String, Integer> e : exact.entrySet())
		{
			want.put(e.getKey(), new int[]{e.getValue(), 0});
		}
		for (Map.Entry<String, Page> e : perItem.entrySet())
		{
			String item = e.getKey();
			Page p = e.getValue();
			List<String> cands = logIndex.get(item);
			String id;
			boolean assumed = false;
			if (cands.size() == 1)
			{
				id = cands.get(0);
			}
			else
			{
				List<String> byPage = new ArrayList<>();
				for (String c : cands)
				{
					String bn = Names.norm(data.boss(c).name);
					for (String pg : p.pages)
					{
						if (pg.contains(bn) && !byPage.contains(c))
						{
							byPage.add(c);
						}
					}
				}
				if (byPage.size() == 1)
				{
					id = byPage.get(0);
				}
				else
				{
					List<String> sorted = new ArrayList<>(cands);
					sorted.sort(Comparator.<String>comparingInt(c -> -(kcTo.containsKey(c) ? kcTo.get(c) : ledger.kc(c))));
					id = sorted.get(0);
					assumed = true;
				}
			}
			int drops = Quantities.drops(data.boss(id), item, p.n);
			// the collection log keeps one count for an item, whichever boss it came from: the copies the other bosses that drop it
			// hold (once their own rows are added) are already part of that count, so only the rest belongs here
			int others = 0;
			for (String c : cands)
			{
				if (!c.equals(id))
				{
					int held = state.computeIfAbsent(c, ledger::copyOf).copies(item);
					int[] theirs = want.get(c + '|' + item);
					others += theirs == null ? held : Math.max(held, Math.min(theirs[0], copyCap(c, kcTo)));
				}
			}
			String key = id + '|' + item;
			int[] cur = want.get(key);
			int target = drops - others;
			if (target <= (cur == null ? 0 : cur[0]))
			{
				continue;
			}
			if (drops != p.n)
			{
				quantities.merge(key, p.n, Integer::sum);
			}
			if (cur == null)
			{
				want.put(key, new int[]{target, assumed ? 1 : 0});
			}
			else
			{
				cur[0] = target;
				cur[1] = assumed ? 1 : cur[1];
			}
		}
		for (Map.Entry<String, int[]> e : want.entrySet())
		{
			String id = e.getKey().substring(0, e.getKey().indexOf('|'));
			String item = e.getKey().substring(e.getKey().indexOf('|') + 1);
			BossState st = state.computeIfAbsent(id, ledger::copyOf);
			plan.items.add(new ItemRow(id, data.boss(id).name, item, e.getValue()[0], st.copies(item), st.importedUnknown(item), copyCap(id, kcTo),
				e.getValue()[1] != 0, quantities.getOrDefault(e.getKey(), 0)));
		}
		plan.items.sort(Comparator.<ItemRow, String>comparing(r -> r.bossName, String.CASE_INSENSITIVE_ORDER).thenComparing(r -> r.item));
		plan.itemsMissing.addAll(missing);
		return plan;
	}

	/**
	 * The data's name for a collection-log item named as the game names it, or null when no boss lists it.
	 */
	String itemFor(String gameName)
	{
		return itemKey.get(Names.flat(gameName));
	}

	/**
	 * The bosses whose collection log lists the item.
	 */
	List<String> bossesFor(String item)
	{
		List<String> l = logIndex.get(item);
		return l == null ? Collections.<String>emptyList() : l;
	}

	/**
	 * The most copies of an item the ledger takes for a boss: {@link #MAX_COPIES}, or the number of kills when there are more.
	 */
	private int copyCap(String bossId, Map<String, Integer> kcTo)
	{
		Integer planned = kcTo.get(bossId);
		return Math.max(MAX_COPIES, Math.max(planned == null ? 0 : planned, ledger.kc(bossId)));
	}

	/**
	 * Applies the rows that are switched on.
	 *
	 * @return {kill counts set, copies added, copies taken back}
	 */
	public int[] apply(Plan plan)
	{
		int kcSet = 0;
		int copies = 0;
		int removed = 0;
		for (KcRow r : plan.kc)
		{
			if (!r.on || r.lower)
			{
				continue; // a count to lower comes only from the game's own records, which Catchup applies
			}
			final Boss boss = data.boss(r.bossId);
			ledger.update(r.bossId, s ->
			{
				boolean fresh = s.kc == 0 && s.drops.isEmpty() && s.segs.size() == 1;
				if (fresh)
				{
					layOutModes(s, boss, r);
				}
				for (Map.Entry<String, Integer> e : r.labels.entrySet())
				{
					s.labels().merge(e.getKey(), e.getValue(), Math::max);
				}
				s.kc = Math.max(s.kc, Math.max(r.to, s.maxDropKc()));
				s.prov = null;
				s.provDrops = null;
				return null;
			});
			kcSet++;
		}
		for (ItemRow r : plan.items)
		{
			if (r.on && r.extra)
			{
				removed += ledger.removeExtra(r.bossId, r.item, r.remove, r.importedOnly);
			}
			else if (r.on && (r.add > 0 || r.remove > 0))
			{
				// re-check against the ledger as it is now, in case something changed since the plan was made
				BossState st = ledger.copyOf(r.bossId);
				int have = st.copies(r.item);
				int target = Math.min(r.want, r.cap);
				copies += ledger.addOwned(r.bossId, r.item, Math.max(0, target - have));
				if (r.remove > 0)
				{
					removed += ledger.removeOwned(r.bossId, r.item, Math.min(st.importedUnknown(r.item), Math.max(0, have - target)));
				}
			}
		}
		return new int[]{kcSet, copies, removed};
	}

	/**
	 * For a boss with no kills yet: the settings of its kill-count labels become periods.  With several labels (normal and
	 * challenge mode, awakened and normal ...) the kills of each label form one block of kills with that label's settings,
	 * in the order of the boss data.  The real order is unknown, but the totals per mode are right.
	 */
	private static void layOutModes(BossState s, Boss boss, KcRow r)
	{
		Map<String, Object> defaults = Engine.defaultParams(boss);
		if (r.labels.size() < 2)
		{
			Map<String, Object> patch = BossIndex.patchOf(boss, r.labels.keySet().iterator().next());
			if (!patch.isEmpty())
			{
				Ledger.applyParamsLocked(s, 1, patch, defaults);
			}
			return;
		}
		List<Period> periods = new ArrayList<>();
		int from = 1;
		for (String label : boss.kc)
		{
			Integer n = r.labels.get(label);
			if (n == null)
			{
				continue;
			}
			Map<String, Object> params = new LinkedHashMap<>(s.segs.get(0).params);
			params.putAll(BossIndex.patchOf(boss, label));
			if (periods.isEmpty() || !samePeriod(periods.get(periods.size() - 1).params, params, defaults))
			{
				periods.add(new Period(from, params));
			}
			from += n;
		}
		if (!periods.isEmpty())
		{
			s.segs = periods;
		}
	}

	private static boolean samePeriod(Map<String, Object> a, Map<String, Object> b, Map<String, Object> defaults)
	{
		Set<String> keys = new LinkedHashSet<>(a.keySet());
		keys.addAll(b.keySet());
		for (String k : keys)
		{
			Object x = a.containsKey(k) ? a.get(k) : defaults.get(k);
			Object y = b.containsKey(k) ? b.get(k) : defaults.get(k);
			if (x instanceof Number && y instanceof Number)
			{
				if (((Number) x).doubleValue() != ((Number) y).doubleValue())
				{
					return false;
				}
			}
			else if (!String.valueOf(x).equals(String.valueOf(y)))
			{
				return false;
			}
		}
		return true;
	}
}

package com.dropluckledger.history;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * One loot of a boss as the drop log kept it: every item, tracked or not, with the kill number it came on.
 */
public final class LoggedLoot
{
	/**
	 * One item of the loot, named as the game names it.
	 */
	public static final class Item
	{
		public final String name;
		public final int qty;

		public Item(String name, int qty)
		{
			this.name = name;
			this.qty = qty;
		}
	}

	/**
	 * Epoch milliseconds when it was received.
	 */
	public final long t;
	public final String bossId;
	/**
	 * The ledger's kill number it came on.
	 */
	public final int kill;
	public final List<Item> items;
	/**
	 * For items several bosses drop: the other bosses' kill counts when it came (null when none of its items is shared).
	 */
	public final Map<String, Integer> snap;

	public LoggedLoot(long t, String bossId, int kill, List<Item> items, Map<String, Integer> snap)
	{
		this.t = t;
		this.bossId = bossId;
		this.kill = kill;
		this.items = Collections.unmodifiableList(new ArrayList<>(items));
		this.snap = snap == null || snap.isEmpty() ? null : Collections.unmodifiableMap(snap);
	}
}

package com.dropluckledger.history;

import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Data.Row;

/**
 * Turns "how many of an item the game says you have" into "how many times it dropped".
 * <p>
 * Stackable items drop several at a time (the Alchemical Hydra gives 500-1000 dragon knives, the Hueycoatl 1-20 huasca seeds), but
 * the Loot Tracker and the Collection Log only keep the running total.  Counting that total as separate drops would make
 * the player look absurdly lucky, so it is divided by the usual amount per drop.  The result is an estimate; for items that
 * always drop one at a time it is exact.
 */
public final class Quantities
{
	private Quantities()
	{
	}

	/**
	 * The usual number of the item in one drop from the boss: the average of the amounts on its drop table, weighted by how
	 * likely each row is; 1 when the table gives no amount.
	 */
	public static double perDrop(Boss boss, String item)
	{
		double sum = 0;
		double weights = 0;
		boolean allHaveRates = true;
		for (Row r : boss.allRows())
		{
			if (item.equals(r.name) && parse(r.qty) != null && !(r.p != null && r.p > 0))
			{
				allHaveRates = false;
			}
		}
		for (Row r : boss.allRows())
		{
			Double q = item.equals(r.name) ? parse(r.qty) : null;
			if (q == null)
			{
				continue;
			}
			double w = allHaveRates ? r.p : 1;
			sum += q * w;
			weights += w;
		}
		return weights > 0 ? Math.max(1, sum / weights) : 1;
	}

	/**
	 * How many drops a received total stands for.
	 *
	 * @param total how many of the item the game says were received
	 */
	public static int drops(Boss boss, String item, int total)
	{
		if (total <= 0)
		{
			return 0;
		}
		double each = perDrop(boss, item);
		if (each < 1.05)
		{
			return total;
		}
		return (int) Math.max(1, Math.round(total / each));
	}

	/**
	 * True when the boss always drops the item one at a time: every row of it on the drop tables gives exactly one.  The game's
	 * count of such an item is the number of times it dropped, with nothing estimated.
	 */
	public static boolean oneAtATime(Boss boss, String item)
	{
		boolean found = false;
		for (Row r : boss.allRows())
		{
			if (!item.equals(r.name))
			{
				continue;
			}
			found = true;
			String q = r.qty == null ? "1" : r.qty.trim();
			if (q.endsWith("n"))
			{
				q = q.substring(0, q.length() - 1).trim(); // noted
			}
			if (!q.isEmpty() && !q.equals("1"))
			{
				return false;
			}
		}
		return found;
	}

	/**
	 * The amount a drop-table cell stands for: "3" is 3, "35-40" is 37.5, "11;17" (without and with a perfect kill) is 11, the
	 * trailing "n" of a noted item and the thousands separators are ignored.  Null when there is no amount.
	 */
	static Double parse(String qty)
	{
		if (qty == null)
		{
			return null;
		}
		String s = qty.trim().replace(",", "");
		int semicolon = s.indexOf(';');
		if (semicolon >= 0)
		{
			s = s.substring(0, semicolon);
		}
		s = s.replaceAll("[^0-9-]", "");
		if (s.isEmpty() || s.startsWith("-"))
		{
			return null;
		}
		try
		{
			int dash = s.indexOf('-');
			if (dash < 0)
			{
				return Double.valueOf(Long.parseLong(s));
			}
			double lo = Long.parseLong(s.substring(0, dash));
			double hi = Long.parseLong(s.substring(dash + 1));
			return (lo + hi) / 2;
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}
}

package com.dropluckledger.ledger;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Everything the ledger knows about one boss.  The first six fields are the same as the web app's backup format,
 * the rest belong to the plugin (they are ignored by the web app).
 */
public final class BossState
{
	public int kc;
	public List<Period> segs = new ArrayList<>();
	public List<Drop> drops = new ArrayList<>();
	public List<String> track = new ArrayList<>();
	public List<String> hide = new ArrayList<>();
	public long u;

	/**
	 * Plugin only: the last kill count the game showed for each kill-count label of the boss (for example the normal and
	 * the awakened count of a Desert Treasure II boss).  The ledger kill count is their sum plus any kills added by hand.
	 */
	public Map<String, Integer> labelKc;
	/**
	 * Plugin only: kills counted from a loot event before the game's kill-count message for them arrived.
	 */
	public Integer prov;
	/**
	 * Plugin only: ids of the drops recorded on those kills.
	 */
	public List<String> provDrops;
	/**
	 * Plugin only: the first kill the plugin counted from the game itself (null until it has counted one).  Kills before it came
	 * from history or were set by hand, so what the game reveals per kill (whose loot it was, how many brothers fell) is unknown
	 * for them; settings of that kind apply to them alone.
	 */
	public Integer liveFrom;
	/**
	 * Plugin only: for each setting the game reveals (see {@code Boss.reads}), the first kill the plugin read it for.  The kills
	 * before it are the ones the player's own value applies to; a setting missing here was never read, so it applies to every kill.
	 */
	public Map<String, Integer> seen;

	public BossState()
	{
		segs.add(new Period(1, new LinkedHashMap<>()));
	}

	public int maxDropKc()
	{
		int m = 0;
		for (Drop d : drops)
		{
			if (d.kc != null && d.kc > m)
			{
				m = d.kc;
			}
		}
		return m;
	}

	public int copies(String item)
	{
		int n = 0;
		for (Drop d : drops)
		{
			if (d.item.equals(item))
			{
				n++;
			}
		}
		return n;
	}

	/**
	 * Copies of an item that came from a history import and have no kill number.
	 */
	public int importedUnknown(String item)
	{
		int n = 0;
		for (Drop d : drops)
		{
			if (d.item.equals(item) && d.kc == null && Drop.SRC_IMPORT.equals(d.src))
			{
				n++;
			}
		}
		return n;
	}

	public int provisional()
	{
		return prov == null ? 0 : prov;
	}

	public Map<String, Integer> labels()
	{
		if (labelKc == null)
		{
			labelKc = new LinkedHashMap<>();
		}
		return labelKc;
	}

	public int labelSum(String except)
	{
		int s = 0;
		if (labelKc != null)
		{
			for (Map.Entry<String, Integer> e : labelKc.entrySet())
			{
				if (!e.getKey().equals(except))
				{
					s += e.getValue();
				}
			}
		}
		return s;
	}

	/**
	 * The first kill the plugin read this setting for, or null when it never has.
	 */
	public Integer seenFrom(String setting)
	{
		return seen == null ? null : seen.get(setting);
	}

	public Period lastPeriod()
	{
		return segs.get(segs.size() - 1);
	}

	/**
	 * The settings in force at a kill number (the latest period starting at or before it).
	 */
	public Map<String, Object> paramsAt(int killNo)
	{
		Period best = segs.get(0);
		for (Period p : segs)
		{
			if (p.from <= killNo && p.from >= best.from)
			{
				best = p;
			}
		}
		return best.params;
	}

	public BossState copy()
	{
		BossState b = new BossState();
		b.kc = kc;
		b.segs = new ArrayList<>();
		for (Period p : segs)
		{
			b.segs.add(p.copy());
		}
		b.drops = new ArrayList<>();
		for (Drop d : drops)
		{
			b.drops.add(d.copy());
		}
		b.track = new ArrayList<>(track);
		b.hide = new ArrayList<>(hide);
		b.u = u;
		b.labelKc = labelKc == null ? null : new LinkedHashMap<>(labelKc);
		b.prov = prov;
		b.provDrops = provDrops == null ? null : new ArrayList<>(provDrops);
		b.liveFrom = liveFrom;
		b.seen = seen == null ? null : new LinkedHashMap<>(seen);
		return b;
	}
}

package com.dropluckledger.ledger;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * One copy of an item the player received.
 */
public final class Drop
{
	/**
	 * Came from the collection log or loot tracker history: the kill number is unknown.
	 */
	public static final String SRC_IMPORT = "import";
	/**
	 * Seen in game while the plugin was running.
	 */
	public static final String SRC_LIVE = "live";
	/**
	 * Typed in by the player.
	 */
	public static final String SRC_MANUAL = "manual";

	public String id;
	public String item;
	/**
	 * Ledger kill number it came on, null when unknown.
	 */
	public Integer kc;
	public int qty = 1;
	/**
	 * Epoch milliseconds when it was recorded.
	 */
	public long t;
	/**
	 * For items several bosses drop: the other bosses' kill counts when this one dropped.
	 */
	public Map<String, Integer> snap;
	public String src;

	public Drop copy()
	{
		Drop d = new Drop();
		d.id = id;
		d.item = item;
		d.kc = kc;
		d.qty = qty;
		d.t = t;
		d.snap = snap == null ? null : new LinkedHashMap<>(snap);
		d.src = src;
		return d;
	}
}

package com.dropluckledger.ledger;

import com.dropluckledger.engine.Catalog;
import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Engine.ItemMeta;
import com.dropluckledger.engine.Luck;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Function;
import java.util.function.LongSupplier;

/**
 * The player's kill counts, drops and boss settings.  All access goes through this class, which is safe to use from any
 * thread: every change happens under one lock, and readers get copies.
 */
public final class Ledger
{
	/**
	 * Told after every change.  Called on the thread that made the change, outside the lock; keep it quick.
	 */
	public interface Listener
	{
		/**
		 * @param bossId the boss that changed, or null when the change is not about one boss (settings, restore)
		 */
		void changed(String bossId);
	}

	private final Data data;
	private final LongSupplier clock;
	private final Map<String, BossState> bosses = new LinkedHashMap<>();
	/**
	 * Bosses in the ledger file that the plugin leaves out (the raids, for one), as the JSON they were read from.  They are
	 * never shown or counted, only written back when the ledger is saved or backed up, so their kills and drops are not lost.
	 */
	private final Map<String, String> retired = new LinkedHashMap<>();
	private final Map<String, Long> revisions = new HashMap<>();
	private final CopyOnWriteArrayList<Listener> listeners = new CopyOnWriteArrayList<>();
	private final Random rnd = new Random();
	private Prefs prefs = new Prefs();
	private long revision;

	public Ledger(Data data)
	{
		this(data, System::currentTimeMillis);
	}

	public Ledger(Data data, LongSupplier clock)
	{
		this.data = data;
		this.clock = clock;
	}

	public Data data()
	{
		return data;
	}

	public long now()
	{
		return clock.getAsLong();
	}

	public void addListener(Listener l)
	{
		listeners.add(l);
	}

	public void removeListener(Listener l)
	{
		listeners.remove(l);
	}

	private void fire(String bossId)
	{
		for (Listener l : listeners)
		{
			l.changed(bossId);
		}
	}

	private void touch(String id)
	{
		revision++;
		if (id != null)
		{
			revisions.merge(id, 1L, Long::sum);
			BossState b = bosses.get(id);
			if (b != null)
			{
				b.u = now();
			}
		}
	}

	/**
	 * Changes every time anything changes.
	 */
	public synchronized long revision()
	{
		return revision;
	}

	/**
	 * Changes every time the given boss changes (or the settings that affect all bosses).
	 */
	public synchronized long revision(String id)
	{
		return revisions.getOrDefault(id, 0L) + globalRev;
	}

	private long globalRev;

	// ------------------------------------------------------------------ reading

	public synchronized boolean hasData(String id)
	{
		BossState b = bosses.get(id);
		return b != null && (b.kc > 0 || !b.drops.isEmpty());
	}

	/**
	 * Ids of the bosses with a kill count or a drop.
	 */
	public synchronized List<String> activeBosses()
	{
		List<String> out = new ArrayList<>();
		for (Boss b : Catalog.ordered(data))
		{
			if (hasData(b.id))
			{
				out.add(b.id);
			}
		}
		return out;
	}

	/**
	 * A copy of the boss state (a blank one when the boss has none yet).
	 */
	public synchronized BossState copyOf(String id)
	{
		BossState b = bosses.get(id);
		return b == null ? new BossState() : b.copy();
	}

	public synchronized int kc(String id)
	{
		BossState b = bosses.get(id);
		return b == null ? 0 : b.kc;
	}

	/**
	 * How many copies of an item the boss has in the ledger.
	 */
	public synchronized int copies(String id, String item)
	{
		BossState b = bosses.get(id);
		return b == null ? 0 : b.copies(item);
	}

	/**
	 * The state in the form the luck maths takes.
	 */
	public synchronized Luck.BossRecord record(String id)
	{
		BossState s = bosses.get(id);
		Luck.BossRecord r = new Luck.BossRecord();
		if (s == null)
		{
			return r;
		}
		r.kc = s.kc;
		for (Period p : s.segs)
		{
			r.segs.add(new Luck.Seg(p.from, new LinkedHashMap<>(p.params)));
		}
		for (Drop d : s.drops)
		{
			r.drops.add(new Luck.DropRec(d.item, d.kc));
		}
		return r;
	}

	public synchronized Map<String, Double> globals()
	{
		Map<String, Double> g = new HashMap<>();
		g.put("rowi", prefs.rowi != 0 ? 1.0 : 0.0);
		g.put("lq", prefs.lq != 0 ? 1.0 : 0.0);
		return g;
	}

	public synchronized Prefs prefs()
	{
		return prefs.copy();
	}

	/**
	 * The settings in force for the next kill (the last period, over the boss defaults).
	 */
	public synchronized Map<String, Object> currentParams(String id)
	{
		Boss boss = data.boss(id);
		Map<String, Object> out = com.dropluckledger.engine.Engine.defaultParams(boss);
		BossState s = bosses.get(id);
		if (s != null)
		{
			out.putAll(s.lastPeriod().params);
		}
		return out;
	}

	/**
	 * Items shown for the boss: the default ones the player has not hidden, then any they added.
	 */
	public synchronized List<String> trackedNames(String id)
	{
		Boss boss = data.boss(id);
		if (boss == null)
		{
			return Collections.emptyList();
		}
		BossState s = bosses.get(id);
		Set<String> hide = s == null ? Collections.emptySet() : new LinkedHashSet<>(s.hide);
		List<String> out = new ArrayList<>();
		for (String n : Catalog.defaultTracked(boss))
		{
			if (!hide.contains(n))
			{
				out.add(n);
			}
		}
		if (s != null)
		{
			Map<String, ItemMeta> meta = boss.meta();
			for (String n : s.track)
			{
				ItemMeta im = meta.get(n);
				if (!out.contains(n) && im != null && !im.hidden)
				{
					out.add(n);
				}
			}
		}
		return out;
	}

	/**
	 * Changes one boss under the lock and tells the listeners.  The boss is created when it does not exist yet.
	 */
	public <T> T update(String id, Function<BossState, T> fn)
	{
		T out;
		synchronized (this)
		{
			BossState s = bosses.computeIfAbsent(id, k -> blank());
			out = fn.apply(s);
			touch(id);
		}
		fire(id);
		return out;
	}

	private BossState blank()
	{
		BossState b = new BossState();
		b.u = now();
		return b;
	}

	// ------------------------------------------------------------------ changes made by the player or by history

	/**
	 * The player sets the kill count by hand.  The game's counts seen so far are forgotten, so the next one the game shows (a kill-count
	 * message, a Collection Log page) is taken as it is rather than added on top of the player's number.
	 */
	public void setKc(String id, int kc)
	{
		update(id, s ->
		{
			s.kc = Math.max(s.maxDropKc(), Math.max(0, kc));
			s.prov = null;
			s.provDrops = null;
			s.labelKc = null;
			return null;
		});
	}

	/**
	 * The player adds or takes away kills by hand (as {@link #setKc}, the game's counts seen so far are forgotten).
	 */
	public void addKc(String id, int n)
	{
		update(id, s ->
		{
			s.kc = Math.max(s.maxDropKc(), Math.max(0, s.kc + n));
			s.labelKc = null;
			return null;
		});
	}

	/**
	 * Sets the kill count to the game's own count of every kill of the boss (the player agreed to it, from a Collection Log page or the
	 * Boss Kill Log), up or down, but never below the kill of the last drop with a kill number.  The game's counts become the ones last
	 * seen.
	 *
	 * @param labels kill-count label (as in the boss data) to the game's count for it
	 * @param total  the game's count of every kill
	 * @return true when the kill count changed
	 */
	public boolean kcToGame(String id, Map<String, Integer> labels, int total)
	{
		return update(id, s ->
		{
			int to = Math.max(s.maxDropKc(), Math.max(0, total));
			boolean changed = to != s.kc;
			s.kc = to;
			s.prov = null;
			s.provDrops = null;
			s.labels().clear();
			s.labels().putAll(labels);
			return changed;
		});
	}

	/**
	 * Logs a drop (the player's own entry, or one seen in game).
	 */
	public Drop logDrop(String id, String item, Integer kc, int qty, Map<String, Integer> snap, String src)
	{
		return update(id, s -> addDropLocked(id, s, item, kc, qty, snap, src));
	}

	/**
	 * Adds a drop to a boss the caller already holds through {@link #update}.
	 */
	public Drop addDropLocked(String id, BossState s, String item, Integer kc, int qty, Map<String, Integer> snap, String src)
	{
		Drop d = new Drop();
		d.id = newId();
		d.item = item;
		d.kc = kc == null ? null : Math.max(1, kc);
		d.qty = Math.max(1, qty);
		d.t = now();
		d.src = src;
		d.snap = snap == null || snap.isEmpty() ? null : new LinkedHashMap<>(snap);
		s.drops.add(d);
		if (d.kc != null && d.kc > s.kc)
		{
			s.kc = d.kc;
		}
		s.hide.remove(item);
		Boss boss = data.boss(id);
		if (boss != null && !Catalog.defaultTracked(boss).contains(item) && !s.track.contains(item))
		{
			s.track.add(item);
		}
		return d;
	}

	/**
	 * Changes a logged drop.  Returns false when there is no such drop.
	 */
	public boolean editDrop(String id, String dropId, String item, Integer kc, int qty, Map<String, Integer> snap)
	{
		return update(id, s ->
		{
			for (Drop d : s.drops)
			{
				if (d.id.equals(dropId))
				{
					d.item = item;
					d.kc = kc == null ? null : Math.max(1, kc);
					d.qty = Math.max(1, qty);
					d.snap = snap == null || snap.isEmpty() ? null : new LinkedHashMap<>(snap);
					if (d.src != null && !Drop.SRC_LIVE.equals(d.src))
					{
						d.src = Drop.SRC_MANUAL;
					}
					if (d.kc != null && d.kc > s.kc)
					{
						s.kc = d.kc;
					}
					s.hide.remove(item);
					Boss boss = data.boss(id);
					if (boss != null && !Catalog.defaultTracked(boss).contains(item) && !s.track.contains(item))
					{
						s.track.add(item);
					}
					return true;
				}
			}
			return false;
		});
	}

	public boolean deleteDrop(String id, String dropId)
	{
		return update(id, s ->
		{
			if (s.provDrops != null)
			{
				s.provDrops.remove(dropId);
			}
			return s.drops.removeIf(d -> d.id.equals(dropId));
		});
	}

	/**
	 * Changes a boss setting.  With newKillsOnly the change starts at the next kill; before that the earlier kills keep
	 * the old value (the web app calls this "new kills only").
	 */
	public void setParam(String id, String name, Object value, boolean newKillsOnly)
	{
		update(id, s ->
		{
			if (newKillsOnly && s.kc > 0)
			{
				int from = s.kc + 1;
				Period seg = null;
				for (Period p : s.segs)
				{
					if (p.from == from)
					{
						seg = p;
					}
				}
				if (seg == null)
				{
					Period prev = null;
					for (Period p : s.segs)
					{
						if (p.from < from)
						{
							prev = p;
						}
					}
					seg = new Period(from, prev == null ? null : prev.params);
					s.segs.add(seg);
					s.segs.sort((a, b) -> Integer.compare(a.from, b.from));
				}
				for (Period p : s.segs)
				{
					if (p.from >= from)
					{
						p.params.put(name, value);
					}
				}
			}
			else
			{
				for (Period p : s.segs)
				{
					p.params.put(name, value);
				}
			}
			return null;
		});
	}

	/**
	 * Sets a value for the kills the plugin never read this setting for (see {@link BossState#seen}): the kills before the first one
	 * it read it for, or every kill when it never has.  The kills it read keep what the game said about them.
	 */
	public void setParamBefore(String id, String name, Object value)
	{
		Map<String, Object> defaults = com.dropluckledger.engine.Engine.defaultParams(data.boss(id));
		update(id, s ->
		{
			Integer seen = s.seenFrom(name);
			setBeforeLocked(s, name, value, seen == null ? Integer.MAX_VALUE : seen, defaults);
			return null;
		});
	}

	/**
	 * Gives the kills before a kill number a value for one setting, leaving that kill and the later ones as they are.
	 */
	static void setBeforeLocked(BossState s, String name, Object value, int until, Map<String, Object> defaults)
	{
		s.segs.sort((a, b) -> Integer.compare(a.from, b.from));
		if (until != Integer.MAX_VALUE)
		{
			boolean starts = false;
			Period before = null;
			for (Period p : s.segs)
			{
				if (p.from == until)
				{
					starts = true;
				}
				if (p.from < until)
				{
					before = p;
				}
			}
			if (!starts && before != null)
			{
				s.segs.add(new Period(until, before.params));
				s.segs.sort((a, b) -> Integer.compare(a.from, b.from));
			}
		}
		for (Period p : s.segs)
		{
			if (p.from < until)
			{
				p.params.put(name, value);
			}
		}
		mergeSamePeriods(s, defaults);
	}

	/**
	 * Records that the game revealed some settings for a kill, for callers that already hold the boss under {@link #update}: the first
	 * kill each setting was read for is remembered, and a setting the boss infers (see {@code Boss.infer}) gives its first value to the
	 * earlier kills, unless the player set them.
	 *
	 * @param killNo the kill the game told about
	 * @param from   the first kill the value was given to (kills the plugin missed just before are assumed to be like this one)
	 */
	public static void noteReadLocked(BossState s, Boss boss, Map<String, Object> patch, int killNo, int from, Map<String, Object> defaults)
	{
		if (patch == null)
		{
			return;
		}
		for (Map.Entry<String, Object> e : patch.entrySet())
		{
			String k = e.getKey();
			if (!boss.reads.contains(k) || s.seenFrom(k) != null || e.getValue() == null)
			{
				continue;
			}
			if (s.seen == null)
			{
				s.seen = new LinkedHashMap<>();
			}
			s.seen.put(k, killNo);
			if (boss.infer.contains(k) && from > 1 && !setByPlayer(s, k, from))
			{
				setBeforeLocked(s, k, e.getValue(), from, defaults);
			}
		}
	}

	/**
	 * True when a period before the kill number says what the setting is (the player set it).
	 */
	static boolean setByPlayer(BossState s, String name, int until)
	{
		for (Period p : s.segs)
		{
			if (p.from < until && p.params.containsKey(name))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Merges all periods into one that has the latest settings.
	 */
	public void collapsePeriods(String id)
	{
		update(id, s ->
		{
			Period last = s.lastPeriod();
			s.segs = new ArrayList<>();
			s.segs.add(new Period(1, last.params));
			return null;
		});
	}

	/**
	 * Makes sure the settings that apply to the kill with this number include the given values (used when the game tells
	 * the plugin which mode the kill was in), for callers that already hold the boss under {@link #update}.  A new period
	 * starts at the kill when the settings differ.  Does nothing when a later period exists (the player has set things up
	 * by hand).
	 *
	 * @param defaults the boss's default settings, which apply where a period does not say (may be null)
	 */
	public static boolean applyParamsLocked(BossState s, int killNo, Map<String, Object> patch, Map<String, Object> defaults)
	{
		Period last = s.lastPeriod();
		if (last.from > killNo)
		{
			return false;
		}
		boolean differs = false;
		for (Map.Entry<String, Object> e : patch.entrySet())
		{
			Object cur = last.params.containsKey(e.getKey()) ? last.params.get(e.getKey()) : defaults == null ? null : defaults.get(e.getKey());
			if (!sameValue(cur, e.getValue()))
			{
				differs = true;
			}
		}
		if (!differs)
		{
			return false;
		}
		if (last.from == killNo)
		{
			last.params.putAll(patch);
			return true;
		}
		Period p = new Period(killNo, last.params);
		p.params.putAll(patch);
		s.segs.add(p);
		return true;
	}

	/**
	 * Gives one kill its own values for some settings, leaving the kills before and after it as they were (used for what the game
	 * reveals about a single kill, such as whether its loot went to you).  Periods are split around the kill and identical neighbours
	 * are merged again, so nothing piles up when the value matches.
	 *
	 * @return true when the ledger changed
	 */
	public static boolean setKillParamsLocked(BossState s, int killNo, Map<String, Object> patch, Map<String, Object> defaults)
	{
		if (killNo < 1 || patch == null || patch.isEmpty())
		{
			return false;
		}
		s.segs.sort((a, b) -> Integer.compare(a.from, b.from));
		int i = 0;
		for (int j = 0; j < s.segs.size(); j++)
		{
			if (s.segs.get(j).from <= killNo)
			{
				i = j;
			}
		}
		Period at = s.segs.get(i);
		boolean differs = false;
		for (Map.Entry<String, Object> e : patch.entrySet())
		{
			Object cur = at.params.containsKey(e.getKey()) ? at.params.get(e.getKey()) : defaults == null ? null : defaults.get(e.getKey());
			if (!sameValue(cur, e.getValue()))
			{
				differs = true;
			}
		}
		if (!differs)
		{
			return false;
		}
		Period next = i + 1 < s.segs.size() ? s.segs.get(i + 1) : null;
		if (next == null || next.from > killNo + 1)
		{
			// the kills after this one keep the values they had
			s.segs.add(i + 1, new Period(killNo + 1, at.params));
		}
		if (at.from == killNo)
		{
			at.params.putAll(patch);
		}
		else
		{
			Period mine = new Period(killNo, at.params);
			mine.params.putAll(patch);
			s.segs.add(i + 1, mine);
		}
		mergeSamePeriods(s, defaults);
		return true;
	}

	/**
	 * Merges neighbouring periods whose settings are the same.
	 */
	static void mergeSamePeriods(BossState s, Map<String, Object> defaults)
	{
		for (int j = s.segs.size() - 1; j > 0; j--)
		{
			if (sameParams(s.segs.get(j - 1).params, s.segs.get(j).params, defaults))
			{
				s.segs.remove(j);
			}
		}
	}

	private static boolean sameParams(Map<String, Object> a, Map<String, Object> b, Map<String, Object> defaults)
	{
		java.util.Set<String> keys = new java.util.HashSet<>(a.keySet());
		keys.addAll(b.keySet());
		for (String k : keys)
		{
			Object x = a.containsKey(k) ? a.get(k) : defaults == null ? null : defaults.get(k);
			Object y = b.containsKey(k) ? b.get(k) : defaults == null ? null : defaults.get(k);
			if (!sameValue(x, y))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Equality for setting values that may be a number, a boolean or a string; a missing value counts as "off" / 0.
	 */
	static boolean sameValue(Object a, Object b)
	{
		if (a == null)
		{
			a = 0;
		}
		if (b == null)
		{
			b = 0;
		}
		if (a instanceof String || b instanceof String)
		{
			return a.toString().equals(b.toString());
		}
		return num(a) == num(b);
	}

	private static double num(Object o)
	{
		if (o instanceof Boolean)
		{
			return (Boolean) o ? 1 : 0;
		}
		return ((Number) o).doubleValue();
	}

	public void setTracked(String id, String name, boolean on)
	{
		update(id, s ->
		{
			Boss boss = data.boss(id);
			boolean def = boss != null && Catalog.defaultTracked(boss).contains(name);
			if (on)
			{
				s.hide.remove(name);
				if (!def && !s.track.contains(name))
				{
					s.track.add(name);
				}
			}
			else
			{
				s.track.remove(name);
				if (def && !s.hide.contains(name))
				{
					s.hide.add(name);
				}
			}
			return null;
		});
	}

	/**
	 * Adds copies of an item the player owns without a known kill number (history).  Returns how many were added.
	 */
	public int addOwned(String id, String item, int n)
	{
		if (n <= 0)
		{
			return 0;
		}
		update(id, s ->
		{
			for (int i = 0; i < n; i++)
			{
				Drop d = new Drop();
				d.id = newId();
				d.item = item;
				d.qty = 1;
				d.t = now();
				d.src = Drop.SRC_IMPORT;
				s.drops.add(d);
			}
			s.hide.remove(item);
			Boss boss = data.boss(id);
			if (boss != null && !Catalog.defaultTracked(boss).contains(item) && !s.track.contains(item))
			{
				s.track.add(item);
			}
			return null;
		});
		return n;
	}

	/**
	 * Takes back copies that a history import added with no kill number (it counted every item of a stack as a drop, say).  Only
	 * those copies are touched, never one that was logged live or by hand.
	 *
	 * @return how many were removed
	 */
	public int removeOwned(String id, String item, int n)
	{
		if (n <= 0)
		{
			return 0;
		}
		final int[] removed = {0};
		update(id, s ->
		{
			for (java.util.Iterator<Drop> it = s.drops.iterator(); it.hasNext() && removed[0] < n; )
			{
				Drop d = it.next();
				if (d.item.equals(item) && d.kc == null && Drop.SRC_IMPORT.equals(d.src))
				{
					it.remove();
					removed[0]++;
				}
			}
			return null;
		});
		return removed[0];
	}

	/**
	 * Takes away copies of an item that the game's collection log shows fewer of than the ledger has.  The copies least likely to
	 * be right go first: those a history import added with no kill number, then those typed in by hand, then those seen in game.
	 * Within each, a copy that shares its kill with another copy of the item (counted twice) goes before the others, and then the
	 * one recorded last.
	 *
	 * @param importedOnly take only copies a history import added with no kill number
	 * @return how many were removed
	 */
	public int removeExtra(String id, String item, int n, boolean importedOnly)
	{
		if (n <= 0)
		{
			return 0;
		}
		return update(id, s ->
		{
			int removed = 0;
			while (removed < n)
			{
				Map<Integer, Integer> perKill = new HashMap<>();
				for (Drop d : s.drops)
				{
					if (d.item.equals(item) && d.kc != null)
					{
						perKill.merge(d.kc, 1, Integer::sum);
					}
				}
				Drop pick = null;
				for (Drop d : s.drops)
				{
					if (d.item.equals(item) && (!importedOnly || trust(d) == 0) && (pick == null || goesFirst(d, pick, perKill)))
					{
						pick = d;
					}
				}
				if (pick == null)
				{
					break;
				}
				s.drops.remove(pick);
				if (s.provDrops != null)
				{
					s.provDrops.remove(pick.id);
				}
				removed++;
			}
			return removed;
		});
	}

	/**
	 * 0 for a copy a history import added with no kill number, 1 for one typed in by hand, 2 for one seen in game.
	 */
	private static int trust(Drop d)
	{
		if (d.kc == null && Drop.SRC_IMPORT.equals(d.src))
		{
			return 0;
		}
		return Drop.SRC_MANUAL.equals(d.src) ? 1 : 2;
	}

	/**
	 * Of two copies of one item, whether a is taken away before b.
	 *
	 * @param perKill kill number to the copies of the item at it
	 */
	private static boolean goesFirst(Drop a, Drop b, Map<Integer, Integer> perKill)
	{
		if (trust(a) != trust(b))
		{
			return trust(a) < trust(b);
		}
		boolean twiceA = a.kc != null && perKill.get(a.kc) > 1;
		boolean twiceB = b.kc != null && perKill.get(b.kc) > 1;
		if (twiceA != twiceB)
		{
			return twiceA;
		}
		if (a.t != b.t)
		{
			return a.t > b.t;
		}
		return (a.kc == null ? 0 : a.kc) > (b.kc == null ? 0 : b.kc);
	}

	public void updatePrefs(java.util.function.Consumer<Prefs> fn)
	{
		synchronized (this)
		{
			fn.accept(prefs);
			prefs.window = Math.max(1, Math.min(5000, prefs.window));
			globalRev++;
			touch(null);
		}
		fire(null);
	}

	/**
	 * Whether the overview lists the boss (Settings, "Bosses to show").  Every boss is recorded either way.
	 */
	public synchronized boolean shown(String id)
	{
		return !prefs.hiddenBosses.contains(id);
	}

	/**
	 * Shows bosses on the overview or leaves them out.  No figure depends on it, so what was worked out stays valid.
	 */
	public void setShown(java.util.Collection<String> ids, boolean show)
	{
		synchronized (this)
		{
			boolean changed = false;
			for (String id : ids)
			{
				if (show)
				{
					changed |= prefs.hiddenBosses.remove(id);
				}
				else if (!prefs.hiddenBosses.contains(id))
				{
					prefs.hiddenBosses.add(id);
					changed = true;
				}
			}
			if (!changed)
			{
				return;
			}
			revision++;
		}
		fire(null);
	}

	/**
	 * Remembers what the side panel shows so that it comes back the same.  It is saved with the ledger; no figure depends on it.
	 */
	public void setView(String sel, String tab, String scope)
	{
		synchronized (this)
		{
			if (prefs.sel.equals(sel) && prefs.tab.equals(tab) && prefs.scope.equals(scope))
			{
				return;
			}
			prefs.sel = sel;
			prefs.tab = tab;
			prefs.scope = scope;
			revision++;
		}
		fire(null);
	}

	/**
	 * Adds what another ledger (a backup) has.  A boss this ledger knows nothing about comes over whole.  For the others the
	 * drops with ids not yet here are added, the kill count becomes the larger of the two, and the extra tracked items come over.
	 * Bosses the plugin leaves out come over only when this ledger does not have them yet.
	 *
	 * @return the number of drops added
	 */
	public int mergeFrom(Ledger other)
	{
		Map<String, BossState> theirs = new LinkedHashMap<>();
		Map<String, String> theirRetired;
		synchronized (other)
		{
			for (Map.Entry<String, BossState> e : other.bosses.entrySet())
			{
				theirs.put(e.getKey(), e.getValue().copy());
			}
			theirRetired = new LinkedHashMap<>(other.retired);
		}
		int added = 0;
		synchronized (this)
		{
			for (Map.Entry<String, String> e : theirRetired.entrySet())
			{
				retired.putIfAbsent(e.getKey(), e.getValue());
			}
			for (Map.Entry<String, BossState> e : theirs.entrySet())
			{
				String id = e.getKey();
				BossState inc = e.getValue();
				BossState cur = bosses.get(id);
				if (cur == null)
				{
					bosses.put(id, inc);
					added += inc.drops.size();
				}
				else
				{
					Set<String> have = new HashSet<>();
					for (Drop d : cur.drops)
					{
						have.add(d.id);
					}
					for (Drop d : inc.drops)
					{
						if (have.add(d.id))
						{
							cur.drops.add(d);
							added++;
						}
					}
					cur.kc = Math.max(cur.kc, Math.max(inc.kc, cur.maxDropKc()));
					for (String n : inc.track)
					{
						if (!cur.track.contains(n))
						{
							cur.track.add(n);
						}
					}
				}
				touch(id);
			}
		}
		fire(null);
		return added;
	}

	/**
	 * Replaces everything with the content of another ledger (restore).
	 */
	public void replaceWith(Ledger other)
	{
		synchronized (this)
		{
			Map<String, BossState> theirs;
			Map<String, String> theirRetired;
			Prefs p;
			synchronized (other)
			{
				theirs = new LinkedHashMap<>();
				for (Map.Entry<String, BossState> e : other.bosses.entrySet())
				{
					theirs.put(e.getKey(), e.getValue().copy());
				}
				theirRetired = new LinkedHashMap<>(other.retired);
				p = other.prefs.copy();
			}
			bosses.clear();
			bosses.putAll(theirs);
			retired.clear();
			retired.putAll(theirRetired);
			prefs = p;
			globalRev++;
			touch(null);
		}
		fire(null);
	}

	/**
	 * Adds the state of one boss from outside (restore of a single boss); replaces what is there.
	 */
	void putBoss(String id, BossState s)
	{
		synchronized (this)
		{
			bosses.put(id, s);
			revision++;
			revisions.merge(id, 1L, Long::sum);
		}
	}

	/**
	 * Keeps the JSON of a boss the plugin leaves out, to be written back on save.
	 */
	void putRetired(String id, String json)
	{
		synchronized (this)
		{
			retired.put(id, json);
		}
	}

	synchronized Map<String, String> rawRetired()
	{
		return retired;
	}

	void putPrefs(Prefs p)
	{
		synchronized (this)
		{
			this.prefs = p;
			globalRev++;
		}
	}

	synchronized Map<String, BossState> rawBosses()
	{
		return bosses;
	}

	synchronized Prefs rawPrefs()
	{
		return prefs;
	}

	public String newId()
	{
		StringBuilder b = new StringBuilder();
		for (int i = 0; i < 8; i++)
		{
			b.append(Character.forDigit(rnd.nextInt(36), 36));
		}
		return b.toString();
	}
}

package com.dropluckledger.ledger;

import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Data.Param;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonPrimitive;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Reads and writes the ledger as JSON.  The format is the web app's backup format ("drop-luck-ledger", version 1) with a few
 * extra plugin-only fields that the web app ignores, so a backup can be moved either way.
 */
public final class LedgerCodec
{
	public static final String APP = "drop-luck-ledger";

	private LedgerCodec()
	{
	}

	/**
	 * Thrown for text that is not a ledger backup.
	 */
	public static final class FormatException extends Exception
	{
		private static final long serialVersionUID = 1L;

		public FormatException(String msg)
		{
			super(msg);
		}
	}

	// ------------------------------------------------------------------ writing

	public static String toJson(Gson gson, Ledger ledger)
	{
		return gson.toJson(toTree(ledger));
	}

	static JsonObject toTree(Ledger ledger)
	{
		JsonObject root = new JsonObject();
		root.addProperty("app", APP);
		root.addProperty("v", 1);
		root.addProperty("saved", Instant.ofEpochMilli(ledger.now()).toString());
		synchronized (ledger)
		{
			Prefs p = ledger.rawPrefs();
			JsonObject po = new JsonObject();
			po.addProperty("window", p.window);
			po.addProperty("rowi", p.rowi);
			po.addProperty("lq", p.lq);
			po.addProperty("theme", p.theme);
			po.addProperty("scope", p.scope);
			po.addProperty("sel", p.sel);
			po.addProperty("tab", p.tab);
			po.addProperty("images", p.images);
			if (!p.hiddenBosses.isEmpty())
			{
				po.add("hiddenBosses", strings(p.hiddenBosses));
			}
			root.add("prefs", po);
			JsonObject bo = new JsonObject();
			for (Map.Entry<String, BossState> e : ledger.rawBosses().entrySet())
			{
				bo.add(e.getKey(), bossTree(e.getValue()));
			}
			for (Map.Entry<String, String> e : ledger.rawRetired().entrySet())
			{
				if (!bo.has(e.getKey()))
				{
					bo.add(e.getKey(), new JsonParser().parse(e.getValue()));
				}
			}
			root.add("bosses", bo);
		}
		return root;
	}

	static JsonObject bossTree(BossState b)
	{
		JsonObject o = new JsonObject();
		o.addProperty("kc", b.kc);
		JsonArray segs = new JsonArray();
		for (Period p : b.segs)
		{
			JsonObject s = new JsonObject();
			s.addProperty("from", p.from);
			JsonObject params = new JsonObject();
			for (Map.Entry<String, Object> e : p.params.entrySet())
			{
				Object v = e.getValue();
				if (v instanceof Boolean)
				{
					params.addProperty(e.getKey(), (Boolean) v ? 1 : 0);
				}
				else if (v instanceof Number)
				{
					params.addProperty(e.getKey(), (Number) v);
				}
				else if (v != null)
				{
					params.addProperty(e.getKey(), v.toString());
				}
			}
			s.add("params", params);
			segs.add(s);
		}
		o.add("segs", segs);
		JsonArray drops = new JsonArray();
		for (Drop d : b.drops)
		{
			JsonObject j = new JsonObject();
			j.addProperty("id", d.id);
			j.addProperty("item", d.item);
			if (d.kc != null)
			{
				j.addProperty("kc", d.kc);
			}
			j.addProperty("qty", d.qty);
			j.addProperty("t", d.t);
			if (d.snap != null && !d.snap.isEmpty())
			{
				JsonObject sn = new JsonObject();
				for (Map.Entry<String, Integer> e : d.snap.entrySet())
				{
					sn.addProperty(e.getKey(), e.getValue());
				}
				j.add("snap", sn);
			}
			if (d.src != null)
			{
				j.addProperty("src", d.src);
			}
			drops.add(j);
		}
		o.add("drops", drops);
		o.add("track", strings(b.track));
		o.add("hide", strings(b.hide));
		o.addProperty("u", b.u);
		if (b.labelKc != null && !b.labelKc.isEmpty())
		{
			JsonObject lk = new JsonObject();
			for (Map.Entry<String, Integer> e : b.labelKc.entrySet())
			{
				lk.addProperty(e.getKey(), e.getValue());
			}
			o.add("labelKc", lk);
		}
		if (b.prov != null && b.prov > 0)
		{
			o.addProperty("prov", b.prov);
		}
		if (b.provDrops != null && !b.provDrops.isEmpty())
		{
			o.add("provDrops", strings(b.provDrops));
		}
		if (b.liveFrom != null)
		{
			o.addProperty("liveFrom", b.liveFrom);
		}
		if ((b.seen != null && !b.seen.isEmpty()) || b.liveFrom != null)
		{
			// written even when empty once the plugin counts kills itself, so an older ledger is told apart from one that read nothing
			JsonObject sn = new JsonObject();
			if (b.seen != null)
			{
				for (Map.Entry<String, Integer> e : b.seen.entrySet())
				{
					sn.addProperty(e.getKey(), e.getValue());
				}
			}
			o.add("seen", sn);
		}
		return o;
	}

	private static JsonArray strings(List<String> l)
	{
		JsonArray a = new JsonArray();
		for (String s : l)
		{
			a.add(s);
		}
		return a;
	}

	// ------------------------------------------------------------------ reading

	/**
	 * Reads a backup.  Bosses the plugin leaves out are kept as they are (written back, never shown), unknown settings are
	 * dropped, damaged entries are repaired or skipped.
	 */
	public static Ledger fromJson(Data data, String json) throws FormatException
	{
		return fromJson(data, json, null);
	}

	public static Ledger fromJson(Data data, String json, java.util.function.LongSupplier clock) throws FormatException
	{
		JsonObject root;
		try
		{
			JsonElement e = new JsonParser().parse(json == null ? "" : json.trim());
			if (!e.isJsonObject())
			{
				throw new FormatException("This is not a Drop Luck Ledger backup.");
			}
			root = e.getAsJsonObject();
		}
		catch (com.google.gson.JsonParseException | IllegalStateException ex)
		{
			throw new FormatException("This is not a Drop Luck Ledger backup (the file could not be read).");
		}
		if (!root.has("app") || !root.get("app").isJsonPrimitive() || !APP.equals(root.get("app").getAsString()))
		{
			throw new FormatException("This is not a Drop Luck Ledger backup.");
		}
		Ledger l = clock == null ? new Ledger(data) : new Ledger(data, clock);
		Prefs prefs = new Prefs();
		if (root.has("prefs") && root.get("prefs").isJsonObject())
		{
			JsonObject po = root.getAsJsonObject("prefs");
			prefs.window = clamp(po.get("window"), 1, 5000, prefs.window);
			prefs.rowi = flag(po.get("rowi"), 0);
			prefs.lq = flag(po.get("lq"), 1);
			prefs.images = flag(po.get("images"), 1);
			prefs.theme = text(po.get("theme"), "");
			prefs.scope = "new".equals(text(po.get("scope"), "all")) ? "new" : "all";
			String sel = text(po.get("sel"), "");
			prefs.sel = data.boss(sel) != null ? sel : "";
			prefs.tab = text(po.get("tab"), "tracker");
			for (String id : stringList(po.get("hiddenBosses")))
			{
				if (data.boss(id) != null && !prefs.hiddenBosses.contains(id))
				{
					prefs.hiddenBosses.add(id);
				}
			}
		}
		l.putPrefs(prefs);
		if (root.has("bosses") && root.get("bosses").isJsonObject())
		{
			for (Map.Entry<String, JsonElement> e : root.getAsJsonObject("bosses").entrySet())
			{
				if (!e.getValue().isJsonObject())
				{
					continue;
				}
				Boss boss = data.boss(e.getKey());
				if (boss == null)
				{
					// a boss the plugin leaves out (the raids, for one, which the web app has): kept as it is and written back
					l.putRetired(e.getKey(), e.getValue().toString());
					continue;
				}
				l.putBoss(e.getKey(), sanitizeBoss(l, boss, e.getValue().getAsJsonObject()));
			}
		}
		// a "history" block (what an earlier version kept of the game's screens) is no longer used, and goes at the next save
		return l;
	}

	private static BossState sanitizeBoss(Ledger l, Boss boss, JsonObject x)
	{
		BossState b = new BossState();
		b.kc = clamp(x.get("kc"), 0, 100_000_000, 0);
		b.u = lng(x.get("u"), l.now());
		List<Period> segs = new ArrayList<>();
		if (x.has("segs") && x.get("segs").isJsonArray())
		{
			for (JsonElement se : x.getAsJsonArray("segs"))
			{
				if (!se.isJsonObject())
				{
					continue;
				}
				JsonObject so = se.getAsJsonObject();
				Period p = new Period();
				p.from = Math.max(1, clamp(so.get("from"), 1, 1_000_000_000, 1));
				if (so.has("params") && so.get("params").isJsonObject())
				{
					for (Map.Entry<String, JsonElement> pe : so.getAsJsonObject("params").entrySet())
					{
						Param def = null;
						for (Param pd : boss.params)
						{
							if (pd.name.equals(pe.getKey()))
							{
								def = pd;
							}
						}
						if (def != null)
						{
							Object v = coerce(def, pe.getValue());
							if (v != null)
							{
								p.params.put(pe.getKey(), v);
							}
						}
					}
				}
				segs.add(p);
			}
		}
		if (!segs.isEmpty())
		{
			segs.sort(Comparator.comparingInt(p -> p.from));
			if (segs.get(0).from != 1)
			{
				segs.add(0, new Period(1, new LinkedHashMap<>()));
			}
			b.segs = segs;
		}
		if (x.has("drops") && x.get("drops").isJsonArray())
		{
			for (JsonElement de : x.getAsJsonArray("drops"))
			{
				if (!de.isJsonObject())
				{
					continue;
				}
				JsonObject d = de.getAsJsonObject();
				if (!d.has("item") || !d.get("item").isJsonPrimitive() || !d.get("item").getAsJsonPrimitive().isString())
				{
					continue;
				}
				Drop r = new Drop();
				r.id = text(d.get("id"), "");
				if (r.id.isEmpty())
				{
					r.id = l.newId();
				}
				r.item = d.get("item").getAsString();
				r.kc = d.has("kc") && !d.get("kc").isJsonNull() ? Integer.valueOf(clamp(d.get("kc"), 1, 1_000_000_000, 1)) : null;
				r.qty = clamp(d.get("qty"), 1, 1_000_000_000, 1);
				r.t = lng(d.get("t"), 0);
				if (d.has("snap") && d.get("snap").isJsonObject())
				{
					Map<String, Integer> sn = new LinkedHashMap<>();
					for (Map.Entry<String, JsonElement> se : d.getAsJsonObject("snap").entrySet())
					{
						sn.put(se.getKey(), clamp(se.getValue(), 0, 1_000_000_000, 0));
					}
					r.snap = sn.isEmpty() ? null : sn;
				}
				String src = text(d.get("src"), "");
				r.src = Drop.SRC_IMPORT.equals(src) || Drop.SRC_LIVE.equals(src) || Drop.SRC_MANUAL.equals(src) ? src : null;
				b.drops.add(r);
			}
		}
		b.track = stringList(x.get("track"));
		b.hide = stringList(x.get("hide"));
		if (x.has("labelKc") && x.get("labelKc").isJsonObject())
		{
			Map<String, Integer> lk = new LinkedHashMap<>();
			for (Map.Entry<String, JsonElement> le : x.getAsJsonObject("labelKc").entrySet())
			{
				lk.put(le.getKey(), clamp(le.getValue(), 0, 100_000_000, 0));
			}
			b.labelKc = lk.isEmpty() ? null : lk;
		}
		int prov = clamp(x.get("prov"), 0, 1_000_000, 0);
		b.prov = prov > 0 ? prov : null;
		List<String> pd = stringList(x.get("provDrops"));
		b.provDrops = pd.isEmpty() ? null : pd;
		int live = clamp(x.get("liveFrom"), 0, 100_000_000, 0);
		b.liveFrom = live > 0 ? live : null;
		if (x.has("seen") && x.get("seen").isJsonObject())
		{
			Map<String, Integer> sn = new LinkedHashMap<>();
			for (Map.Entry<String, JsonElement> se : x.getAsJsonObject("seen").entrySet())
			{
				int k = clamp(se.getValue(), 0, 100_000_000, 0);
				if (k > 0 && boss.reads.contains(se.getKey()))
				{
					sn.put(se.getKey(), k);
				}
			}
			b.seen = sn.isEmpty() ? null : sn;
		}
		else if (b.liveFrom != null && !boss.reads.isEmpty())
		{
			readSinceLiveFrom(b, boss);
		}
		b.kc = Math.max(b.kc, b.maxDropKc());
		return b;
	}

	/**
	 * A ledger from before the plugin remembered which kills it read each setting for: it read them from the first kill it counted.
	 * The settings the boss infers then give the earlier kills their first value read, as they would have in a new ledger.
	 */
	private static void readSinceLiveFrom(BossState b, Boss boss)
	{
		Map<String, Object> defaults = com.dropluckledger.engine.Engine.defaultParams(boss);
		b.seen = new LinkedHashMap<>();
		for (String r : boss.reads)
		{
			b.seen.put(r, b.liveFrom);
		}
		for (String r : boss.infer)
		{
			if (b.liveFrom <= 1 || Ledger.setByPlayer(b, r, b.liveFrom))
			{
				continue;
			}
			Object first = null;
			for (Period p : b.segs)
			{
				if (p.from >= b.liveFrom && p.params.containsKey(r))
				{
					first = p.params.get(r);
					break;
				}
			}
			if (first != null)
			{
				Ledger.setBeforeLocked(b, r, first, b.liveFrom, defaults);
			}
		}
	}

	/**
	 * A setting value in the form the maths takes: 1 or 0 for yes/no, an integer, or the chosen option.
	 */
	private static Object coerce(Param p, JsonElement v)
	{
		if (v == null || v.isJsonNull() || !v.isJsonPrimitive())
		{
			return null;
		}
		JsonPrimitive pr = v.getAsJsonPrimitive();
		if ("bool".equals(p.type))
		{
			if (pr.isBoolean())
			{
				return pr.getAsBoolean() ? 1 : 0;
			}
			return flag(pr, 0);
		}
		if ("int".equals(p.type))
		{
			double d = number(pr, Double.NaN);
			if (Double.isNaN(d))
			{
				return null;
			}
			long r = Math.round(d);
			if (p.min != null)
			{
				r = Math.max(r, Math.round(p.min));
			}
			if (p.max != null)
			{
				r = Math.min(r, Math.round(p.max));
			}
			return (int) r;
		}
		String s = pr.getAsString();
		return p.options != null && p.options.contains(s) ? s : null;
	}

	private static List<String> stringList(JsonElement e)
	{
		List<String> out = new ArrayList<>();
		if (e != null && e.isJsonArray())
		{
			for (JsonElement s : e.getAsJsonArray())
			{
				if (s.isJsonPrimitive() && s.getAsJsonPrimitive().isString())
				{
					out.add(s.getAsString());
				}
			}
		}
		return out;
	}

	private static String text(JsonElement e, String def)
	{
		return e != null && e.isJsonPrimitive() ? e.getAsString() : def;
	}

	private static double number(JsonElement e, double def)
	{
		if (e == null || !e.isJsonPrimitive())
		{
			return def;
		}
		JsonPrimitive p = e.getAsJsonPrimitive();
		if (p.isNumber())
		{
			return p.getAsDouble();
		}
		if (p.isBoolean())
		{
			return p.getAsBoolean() ? 1 : 0;
		}
		try
		{
			return Double.parseDouble(p.getAsString().trim());
		}
		catch (NumberFormatException ex)
		{
			return def;
		}
	}

	private static int clamp(JsonElement e, int lo, int hi, int def)
	{
		double d = number(e, Double.NaN);
		if (Double.isNaN(d) || Double.isInfinite(d))
		{
			return def;
		}
		long r = Math.round(d);
		return (int) Math.max(lo, Math.min(hi, r));
	}

	private static long lng(JsonElement e, long def)
	{
		double d = number(e, Double.NaN);
		return Double.isNaN(d) || Double.isInfinite(d) ? def : (long) d;
	}

	/**
	 * 1 for true / 1 / "1" / "true", 0 for false / 0, the default for anything else.
	 */
	private static int flag(JsonElement e, int def)
	{
		if (e == null || !e.isJsonPrimitive())
		{
			return def;
		}
		JsonPrimitive p = e.getAsJsonPrimitive();
		if (p.isBoolean())
		{
			return p.getAsBoolean() ? 1 : 0;
		}
		if (p.isNumber())
		{
			return p.getAsDouble() != 0 ? 1 : 0;
		}
		String s = p.getAsString().trim();
		if (s.equalsIgnoreCase("true") || s.equals("1"))
		{
			return 1;
		}
		if (s.equalsIgnoreCase("false") || s.equals("0") || s.isEmpty())
		{
			return 0;
		}
		return def;
	}
}

package com.dropluckledger.ledger;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Keeps a {@link LedgerStore} up to date: changes are written a moment after the last one, on a background thread.
 */
public final class LedgerSaver implements Ledger.Listener
{
	private static final Logger log = LoggerFactory.getLogger(LedgerSaver.class);

	private final Ledger ledger;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final long delayMs;
	private LedgerStore store;
	private Future<?> pending;
	private boolean dirty;
	private boolean failedOnce;

	public LedgerSaver(Ledger ledger, Gson gson, ScheduledExecutorService executor, long delayMs)
	{
		this.ledger = ledger;
		this.gson = gson;
		this.executor = executor;
		this.delayMs = delayMs;
	}

	/**
	 * Where to save from now on (null = nowhere, for example while logged out).  Anything not written yet goes to the
	 * previous place first, so to switch accounts call setStore(null), load the other account into the ledger, then
	 * setStore(its store).
	 */
	public synchronized void setStore(LedgerStore next)
	{
		flushNow();
		store = next;
		dirty = false;
	}

	@Override
	public synchronized void changed(String bossId)
	{
		if (store == null)
		{
			return;
		}
		dirty = true;
		if (pending != null)
		{
			pending.cancel(false);
		}
		pending = executor.schedule(this::flushNow, delayMs, TimeUnit.MILLISECONDS);
	}

	/**
	 * Writes now if there is anything to write.  Safe to call from any thread.
	 */
	public synchronized void flushNow()
	{
		if (pending != null)
		{
			pending.cancel(false);
			pending = null;
		}
		if (store == null || !dirty)
		{
			return;
		}
		try
		{
			store.write(LedgerCodec.toJson(gson, ledger));
			dirty = false;
			failedOnce = false;
		}
		catch (IOException | RuntimeException ex)
		{
			if (!failedOnce)
			{
				log.warn("Could not save the drop ledger", ex);
				failedOnce = true;
			}
			// keep it dirty; the next change tries again
		}
	}

	public synchronized void cancel()
	{
		if (pending != null)
		{
			pending.cancel(false);
			pending = null;
		}
	}

	/**
	 * Reads the saved ledger into the live one.  A missing file leaves the ledger empty.
	 *
	 * @return false when a file existed but could not be read (the ledger is left empty and nothing is overwritten
	 * until the player changes something)
	 */
	public synchronized boolean loadInto(LedgerStore from)
	{
		try
		{
			String text = from.read();
			if (text == null || text.trim().isEmpty())
			{
				ledger.replaceWith(new Ledger(ledger.data()));
				return true;
			}
			ledger.replaceWith(LedgerCodec.fromJson(ledger.data(), text));
			return true;
		}
		catch (IOException | LedgerCodec.FormatException | RuntimeException ex)
		{
			log.warn("Could not read the saved drop ledger", ex);
			try
			{
				from.quarantine();
			}
			catch (IOException | RuntimeException ex2)
			{
				log.warn("Could not set the unreadable ledger file aside", ex2);
			}
			ledger.replaceWith(new Ledger(ledger.data()));
			return false;
		}
	}
}

package com.dropluckledger.ledger;

import java.io.IOException;

/**
 * Where one account's ledger file lives.
 */
public interface LedgerStore
{
	/**
	 * @return the saved text, or null when nothing has been saved yet
	 */
	String read() throws IOException;

	/**
	 * Replaces the saved text.  Must not leave a half-written file behind if it fails.
	 */
	void write(String json) throws IOException;

	/**
	 * Called when the saved text could not be understood: keep it somewhere (for example by renaming the file) so the next
	 * save does not destroy it.
	 */
	default void quarantine() throws IOException
	{
	}
}

package com.dropluckledger.ledger;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Boss settings (task, team size, mode, ...) that apply from a kill number on.
 */
public final class Period
{
	public int from = 1;
	public Map<String, Object> params = new LinkedHashMap<>();

	public Period()
	{
	}

	public Period(int from, Map<String, Object> params)
	{
		this.from = from;
		this.params = params == null ? new LinkedHashMap<>() : new LinkedHashMap<>(params);
	}

	public Period copy()
	{
		return new Period(from, params);
	}
}

package com.dropluckledger.ledger;

import java.util.ArrayList;
import java.util.List;

/**
 * Settings stored in the ledger file (same names as the web app so a backup moves between the two).
 */
public final class Prefs
{
	/**
	 * Number of upcoming kills the "next kills" figures look at.
	 */
	public int window = 50;
	/**
	 * Wearing a ring of wealth (i): 1 or 0.
	 */
	public int rowi;
	/**
	 * Legends' Quest completed: 1 or 0.
	 */
	public int lq = 1;
	public String theme = "";
	public String scope = "all";
	public String sel = "";
	public String tab = "tracker";
	public int images = 1;
	/**
	 * Plugin only: the bosses the player unticked under "Bosses to show", which the overview leaves out.  Kept as the ones hidden
	 * rather than the ones shown, so a boss added to the plugin later shows up.
	 */
	public List<String> hiddenBosses = new ArrayList<>();

	public Prefs copy()
	{
		Prefs p = new Prefs();
		p.window = window;
		p.rowi = rowi;
		p.lq = lq;
		p.theme = theme;
		p.scope = scope;
		p.sel = sel;
		p.tab = tab;
		p.images = images;
		p.hiddenBosses = new ArrayList<>(hiddenBosses);
		return p;
	}
}

package com.dropluckledger.plugin;

import com.dropluckledger.history.LoggedLoot;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.JsonParser;
import java.io.BufferedReader;
import java.io.IOException;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.Executor;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Every loot the plugin's bosses give, standard drops included, one line per loot in {@code drops-<account>.jsonl}:
 * <pre>{"t":1761040800000,"boss":"zulrah","kill":1234,"items":[["Coins",40000],["Zulrah's scales",120],["Tanzanite fang",1]]}</pre>
 * The ledger keeps only the items the player tracks; this file keeps everything, so an item tracked later gets its earlier copies,
 * with the kills they came on ({@link com.dropluckledger.history.Backfill}).  Lines are only ever added, on the background thread;
 * a line that cannot be read (half written when the computer went off) is skipped.
 */
public final class DropLog
{
	private static final Logger log = LoggerFactory.getLogger(DropLog.class);

	/**
	 * A log bigger than this is not read back (it would take too long and too much memory).
	 */
	static final long MAX_BYTES = 256L * 1024 * 1024;

	private static final class Line
	{
		final Filepath file;
		final String text;

		Line(Filepath file, String text)
		{
			this.file = file;
			this.text = text;
		}
	}

	private final Filepath dir;
	private final Executor executor;
	private final ConcurrentLinkedQueue<Line> queue = new ConcurrentLinkedQueue<>();
	private final Object writing = new Object();
	private volatile Filepath file;

	/**
	 * @param dir      the plugin's data folder
	 * @param executor where the file is written and read
	 */
	public DropLog(Filepath dir, Executor executor)
	{
		this.dir = dir;
		this.executor = executor;
	}

	/**
	 * File name of an account's drop log.
	 */
	public static String fileName(long accountHash)
	{
		return "drops-" + accountHash + ".jsonl";
	}

	/**
	 * The account whose loot is logged from now on, or null for none (logged out, or a world with its own save).
	 */
	public void setAccount(Long accountHash)
	{
		file = accountHash == null ? null : dir.joinSegment(fileName(accountHash));
	}

	/**
	 * Logs one loot.  Any thread: the line is written on the background thread.
	 */
	public void add(LoggedLoot loot)
	{
		Filepath f = file;
		if (f == null || loot.items.isEmpty())
		{
			return;
		}
		queue.add(new Line(f, toJson(loot)));
		executor.execute(this::flush);
	}

	/**
	 * Writes the lines waiting.  Background thread.
	 */
	public void flush()
	{
		synchronized (writing)
		{
			Map<Filepath, StringBuilder> byFile = new LinkedHashMap<>();
			for (Line l = queue.poll(); l != null; l = queue.poll())
			{
				byFile.computeIfAbsent(l.file, k -> new StringBuilder()).append(l.text).append('\n');
			}
			for (Map.Entry<Filepath, StringBuilder> e : byFile.entrySet())
			{
				try
				{
					dir.createDirectories();
					e.getKey().write(e.getValue().toString(), StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.WRITE);
				}
				catch (IOException ex)
				{
					log.warn("Could not write to the drop log", ex);
				}
			}
		}
	}

	/**
	 * Every loot logged for a boss, oldest first.  Background thread.
	 */
	public List<LoggedLoot> read(String bossId) throws IOException
	{
		flush();
		Filepath f = file;
		if (f == null || !f.isFile())
		{
			return Collections.emptyList();
		}
		if (f.size() > MAX_BYTES)
		{
			throw new IOException("The drop log is too large to read");
		}
		List<LoggedLoot> out = new ArrayList<>();
		synchronized (writing)
		{
			try (BufferedReader r = f.openBufferedReader())
			{
				for (String line = r.readLine(); line != null; line = r.readLine())
				{
					LoggedLoot l = parse(line);
					if (l != null && l.bossId.equals(bossId))
					{
						out.add(l);
					}
				}
			}
		}
		return out;
	}

	/**
	 * Deletes the account's log, with the lines still waiting for it (the ledger was erased).  Background thread.
	 */
	public void erase() throws IOException
	{
		Filepath f = file;
		if (f == null)
		{
			return;
		}
		synchronized (writing)
		{
			queue.removeIf(l -> l.file.equals(f));
			f.deleteIfExists();
		}
	}

	static String toJson(LoggedLoot loot)
	{
		JsonObject o = new JsonObject();
		o.addProperty("t", loot.t);
		o.addProperty("boss", loot.bossId);
		o.addProperty("kill", loot.kill);
		JsonArray items = new JsonArray();
		for (LoggedLoot.Item it : loot.items)
		{
			JsonArray pair = new JsonArray();
			pair.add(it.name);
			pair.add(it.qty);
			items.add(pair);
		}
		o.add("items", items);
		if (loot.snap != null)
		{
			JsonObject snap = new JsonObject();
			for (Map.Entry<String, Integer> e : loot.snap.entrySet())
			{
				snap.addProperty(e.getKey(), e.getValue());
			}
			o.add("snap", snap);
		}
		return o.toString();
	}

	/**
	 * One line, or null when it cannot be read.
	 */
	static LoggedLoot parse(String line)
	{
		if (line == null || line.trim().isEmpty())
		{
			return null;
		}
		try
		{
			JsonElement root = new JsonParser().parse(line);
			if (!root.isJsonObject())
			{
				return null;
			}
			JsonObject o = root.getAsJsonObject();
			JsonElement boss = o.get("boss");
			JsonElement kill = o.get("kill");
			JsonElement list = o.get("items");
			if (boss == null || !boss.isJsonPrimitive() || kill == null || !kill.isJsonPrimitive() || list == null || !list.isJsonArray())
			{
				return null;
			}
			List<LoggedLoot.Item> items = new ArrayList<>();
			for (JsonElement e : list.getAsJsonArray())
			{
				if (e.isJsonArray() && e.getAsJsonArray().size() >= 2)
				{
					JsonArray pair = e.getAsJsonArray();
					items.add(new LoggedLoot.Item(pair.get(0).getAsString(), pair.get(1).getAsInt()));
				}
			}
			Map<String, Integer> snap = null;
			JsonElement s = o.get("snap");
			if (s != null && s.isJsonObject())
			{
				snap = new LinkedHashMap<>();
				for (Map.Entry<String, JsonElement> e : s.getAsJsonObject().entrySet())
				{
					snap.put(e.getKey(), e.getValue().getAsInt());
				}
			}
			JsonElement t = o.get("t");
			return new LoggedLoot(t != null && t.isJsonPrimitive() ? t.getAsLong() : 0, boss.getAsString(), kill.getAsInt(), items, snap);
		}
		catch (JsonParseException | IllegalStateException | UnsupportedOperationException | NumberFormatException ex)
		{
			log.debug("Skipping a drop log line that could not be read");
			return null;
		}
	}
}

package com.dropluckledger.plugin;

import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.ledger.BossState;
import com.dropluckledger.ledger.Drop;
import java.text.NumberFormat;
import java.util.Locale;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;

/**
 * The game message shown when a drop has been added to the ledger.
 */
public final class DropMessages
{
	private DropMessages()
	{
	}

	/**
	 * "Logged Dragonbone necklace at Vorkath kill 1,234 (412 kills since the last one)."
	 *
	 * @param state the boss as it is after the drop was added
	 * @return the message in RuneLite's chat format
	 */
	public static String build(Data data, String bossId, BossState state, String item, int killNo)
	{
		Boss boss = data.boss(bossId);
		String bossName = boss == null ? bossId : boss.name;
		return new ChatMessageBuilder()
			.append(ChatColorType.NORMAL)
			.append("Logged ")
			.append(ChatColorType.HIGHLIGHT)
			.append(item)
			.append(ChatColorType.NORMAL)
			.append(" at ")
			.append(ChatColorType.HIGHLIGHT)
			.append(bossName)
			.append(ChatColorType.NORMAL)
			.append(" kill " + number(killNo) + detail(state, item, killNo) + ".")
			.build();
	}

	/**
	 * What to say about the streak: kills since the last copy, or that this is the first one.  Nothing when copies of unknown
	 * kill number (imported from history) make that unclear.
	 */
	static String detail(BossState state, String item, int killNo)
	{
		int previous = 0;
		int unknown = 0;
		int others = 0;
		for (Drop d : state.drops)
		{
			if (!d.item.equals(item))
			{
				continue;
			}
			if (d.kc == null)
			{
				unknown++;
			}
			else if (d.kc < killNo)
			{
				previous = Math.max(previous, d.kc);
				others++;
			}
			else if (d.kc > killNo)
			{
				return "";
			}
		}
		if (unknown > 0)
		{
			return "";
		}
		if (others == 0)
		{
			return killNo > 1 ? " (the first one, after " + number(killNo - 1) + " kills)" : "";
		}
		int since = killNo - previous;
		return " (" + number(since) + (since == 1 ? " kill" : " kills") + " since the last one)";
	}

	private static String number(int n)
	{
		return NumberFormat.getIntegerInstance(Locale.US).format(n);
	}
}

package com.dropluckledger.plugin;

import com.dropluckledger.ledger.LedgerStore;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import net.runelite.client.util.Filepath;

/**
 * One text file in the plugin's data folder.  Every path goes through RuneLite's {@link Filepath}, so the plugin cannot write
 * anywhere else.  Writes go to a temporary file first and are moved over the real one, so a crash never leaves half a file.
 */
public final class FileStore implements LedgerStore
{
	/**
	 * A ledger file bigger than this is not read (it is not a ledger).
	 */
	static final long MAX_BYTES = 64L * 1024 * 1024;

	private final Filepath dir;
	private final String name;
	private boolean backedUp;

	/**
	 * @param dir  the folder (created on the first write)
	 * @param name the file name inside it, one path segment
	 */
	public FileStore(Filepath dir, String name)
	{
		this.dir = dir;
		this.name = name;
	}

	/**
	 * File name of an account's ledger.
	 */
	public static String ledgerName(long accountHash)
	{
		return "ledger-" + accountHash + ".json";
	}

	@Override
	public String read() throws IOException
	{
		Filepath file = dir.joinSegment(name);
		if (!file.isFile())
		{
			return null;
		}
		return readText(file);
	}

	/**
	 * Reads a whole UTF-8 text file.
	 */
	public static String readText(Filepath file) throws IOException
	{
		if (file.size() > MAX_BYTES)
		{
			throw new IOException("The file is too large to be a ledger backup");
		}
		try (InputStream in = file.openInputStream())
		{
			return new String(in.readAllBytes(), StandardCharsets.UTF_8);
		}
	}

	/**
	 * Writes a whole UTF-8 text file (used for backups the player chose the location of).
	 */
	public static void writeText(Filepath file, String text) throws IOException
	{
		file.write(text, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
	}

	@Override
	public synchronized void write(String json) throws IOException
	{
		dir.createDirectories();
		Filepath target = dir.joinSegment(name);
		Filepath temp = dir.joinSegment(name + ".tmp");
		writeText(temp, json);
		if (!backedUp && target.isFile())
		{
			// the file as the last session left it: kept once, in case this session does something the player regrets
			target.copyTo(dir.joinSegment(name + ".bak"), StandardCopyOption.REPLACE_EXISTING);
			backedUp = true;
		}
		try
		{
			temp.moveTo(target, StandardCopyOption.ATOMIC_MOVE);
		}
		catch (AtomicMoveNotSupportedException ex)
		{
			temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	@Override
	public synchronized void quarantine() throws IOException
	{
		Filepath file = dir.joinSegment(name);
		if (file.isFile())
		{
			file.moveTo(dir.joinSegment(name + ".unreadable-" + System.currentTimeMillis()), StandardCopyOption.REPLACE_EXISTING);
		}
	}
}

package com.dropluckledger.plugin;

import java.awt.Component;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.client.util.Filepath;

/**
 * Everything the plugin asks of the running game and of RuneLite's services, in one place.
 * <p>
 * {@link RuneLiteGame} is the only class that talks to the real client; the rest of the plugin (and its tests) sees only this
 * interface.  Call the methods on the client thread unless a method says otherwise.
 */
public interface Game
{
	// ------------------------------------------------------------------ the player

	/**
	 * The hash that identifies the logged in account, or -1 when nobody is logged in.
	 */
	long accountHash();

	/**
	 * True while a character is logged in.
	 */
	boolean isLoggedIn();

	/**
	 * True on a normal world.  False on the worlds that keep a save of their own (Leagues, Deadman, ...).
	 */
	boolean isStandardWorld();

	/**
	 * The logged in character's name, or null.
	 */
	String playerName();

	/**
	 * The number of game ticks since the client started; messages and loot of one kill share a tick or are a tick apart.
	 */
	int tickCount();

	/**
	 * The player's unboosted level in a skill.
	 */
	int realLevel(Skill skill);

	/**
	 * A varbit's value: what the game tells the client about the player's state (0 when not set).
	 */
	default int varbit(int id)
	{
		return 0;
	}

	/**
	 * A varplayer's value (0 when not set).
	 */
	default int varp(int id)
	{
		return 0;
	}

	/**
	 * What an inventory of the game holds: item id to how many, over all its slots.  The server fills inventories the player never
	 * sees too: the items of the collection log page on screen come in one ({@code InventoryID.COLLECTION_TRANSMIT}).
	 *
	 * @param inventoryId an id from {@code InventoryID}
	 * @return null when the client has no such inventory
	 */
	default Map<Integer, Integer> inventory(int inventoryId)
	{
		return null;
	}

	/**
	 * True on a members' world.
	 */
	default boolean isMembersWorld()
	{
		return true;
	}

	/**
	 * False when the player has switched off RuneLite's Loot Tracker plugin, whose events carry the drops.
	 */
	default boolean isLootTrackerOn()
	{
		return true;
	}

	// ------------------------------------------------------------------ the game's screens

	/**
	 * A piece of the game's interface, as far as the plugin reads it.
	 */
	interface Node
	{
		/**
		 * The text shown, or null.
		 */
		String text();

		/**
		 * The pieces inside this one (entries may be null), or null when there is no list.
		 */
		List<Node> children();

		/**
		 * The piece at a position inside this one, or null.
		 */
		Node child(int index);

		/**
		 * The item shown, or -1 (or 0) when none.
		 */
		int itemId();

		int itemQuantity();

		/**
		 * 0 for fully drawn, up to 255 for invisible; the collection log fades the items the player does not have.
		 */
		int opacity();
	}

	/**
	 * The interface component with an id from {@code InterfaceID}, or null when it is not on screen.
	 */
	Node widget(int componentId);

	// ------------------------------------------------------------------ items

	/**
	 * What the game knows about an item.
	 */
	final class ItemInfo
	{
		/**
		 * The game's name for it ("null" for ids that are not items).
		 */
		public final String name;
		/**
		 * True for the noted (bank note) copy of another item.
		 */
		public final boolean noted;
		/**
		 * True for the bank placeholder of another item.
		 */
		public final boolean placeholder;

		public ItemInfo(String name, boolean noted, boolean placeholder)
		{
			this.name = name;
			this.noted = noted;
			this.placeholder = placeholder;
		}
	}

	/**
	 * An item found by searching for a name.
	 */
	final class ItemRef
	{
		public final int id;
		public final String name;

		public ItemRef(int id, String name)
		{
			this.id = id;
			this.name = name;
		}
	}

	/**
	 * What the game knows about an item id, or null when it has nothing for that id.
	 */
	ItemInfo item(int id);

	/**
	 * The game's name for an item, or null when the id is not an item.
	 */
	default String itemName(int id)
	{
		ItemInfo info = item(id);
		return info == null || info.name == null || info.name.isEmpty() || info.name.equals("null") ? null : info.name;
	}

	/**
	 * The id of the plain item behind a noted copy or a placeholder (other ids come back as they are).
	 */
	int canonicalItemId(int id);

	/**
	 * Tradeable items whose names contain the text.
	 */
	List<ItemRef> searchItems(String text);

	/**
	 * The item's picture.  The game fills it in a moment after returning it, and calls {@code whenLoaded} then.
	 * Can be called from any thread.
	 *
	 * @return null when there is no picture
	 */
	BufferedImage itemImage(int id, Runnable whenLoaded);

	// ------------------------------------------------------------------ what other RuneLite plugins saved

	/**
	 * Keys that start with a prefix, among the settings other plugins saved for the logged in profile (empty when there
	 * is no profile).  Can be called from any thread.
	 */
	List<String> savedKeys(String group, String keyPrefix);

	/**
	 * A whole number saved for the logged in profile, or null.  Can be called from any thread.
	 */
	Integer savedInt(String group, String key);

	/**
	 * A text saved for the logged in profile, or null.  Can be called from any thread.
	 */
	String savedText(String group, String key);

	// ------------------------------------------------------------------ chat, threads and files

	/**
	 * Puts a line in the player's chat box (RuneLite colour tags allowed).
	 */
	void gameMessage(String runeLiteFormattedMessage);

	/**
	 * Runs something on the client thread: at once when already there, otherwise as soon as the client thread is free.
	 * Can be called from any thread.
	 */
	void invoke(Runnable task);

	/**
	 * Runs something on the client thread, never at once.  Can be called from any thread.
	 */
	void invokeLater(Runnable task);

	/**
	 * Asks the player where to save a file.  Call on the Swing thread.
	 *
	 * @return the chosen file, or null when the player cancels
	 */
	Filepath chooseFileToSave(Component parent, String title, String fileName, String description, String extension);

	/**
	 * Asks the player which file to open.  Call on the Swing thread.
	 *
	 * @return the chosen file, or null when the player cancels
	 */
	Filepath chooseFileToOpen(Component parent, String title, String description, String extension);
}

package com.dropluckledger.plugin;

import com.dropluckledger.capture.KcMessages;
import com.dropluckledger.plugin.Game.Node;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.gameval.InterfaceID;

/**
 * Reads the game's own records off the screen when the player opens them: the Boss Kill Log and the pages of the collection log.
 * Only reads widgets; the caller decides what to do with the result.  Call on the client thread.
 */
public final class GameReader
{
	private static final Pattern ADVENTURE_LOG_TITLE = Pattern.compile("The Exploits of (.+)");
	/**
	 * A count line of a collection log page: "Zulrah kills: 1,234".
	 */
	private static final Pattern HEADER_COUNT = Pattern.compile("(.+?):\\s*([0-9][0-9,]*)");

	private GameReader()
	{
	}

	/**
	 * One page of the collection log as drawn: its title, the counts under it and the copies of each item the player has.
	 */
	public static final class LogPage
	{
		public final String title;
		/**
		 * The counts under the title as drawn, as the game words them ("Zulrah kills" to 1234).  The game can draw a page with the
		 * previous page's numbers: {@link #settledCounts} gives the ones it holds for the page once it has settled.
		 */
		public final Map<String, Integer> counts;
		/**
		 * Item name to the number of copies the player has (only items the player has).
		 */
		public final Map<String, Integer> items;
		/**
		 * Item name to item id for every item on the page, including the ones the player does not have yet.
		 */
		public final Map<String, Integer> ids;
		/**
		 * Item id to the number drawn for it: the copies, or 0 for an item drawn faded.
		 */
		public final Map<Integer, Integer> drawn;

		LogPage(String title, Map<String, Integer> counts, Map<String, Integer> items, Map<String, Integer> ids, Map<Integer, Integer> drawn)
		{
			this.title = title;
			this.counts = counts;
			this.items = items;
			this.ids = ids;
			this.drawn = drawn;
		}
	}

	/**
	 * The Boss Kill Log as shown on screen: boss name to kill count, 0 included (the server sends the whole log at once, so a 0 is
	 * the game's count too).
	 *
	 * @return null when the Boss Kill Log is not on screen (or not filled in yet)
	 */
	public static Map<String, Integer> killLog(Game game)
	{
		Node title = game.widget(InterfaceID.KillLog.INTERFACE_TITLE);
		Node names = game.widget(InterfaceID.KillLog.NAME);
		Node kills = game.widget(InterfaceID.KillLog.KILL);
		if (title == null || names == null || kills == null || !"Boss Kill Log".equals(title.text()))
		{
			return null;
		}
		List<Node> nameRows = names.children();
		List<Node> killRows = kills.children();
		if (nameRows == null || killRows == null)
		{
			return null;
		}
		Map<String, Integer> out = new LinkedHashMap<>();
		for (int i = 0; i < Math.min(nameRows.size(), killRows.size()); i++)
		{
			Node name = nameRows.get(i);
			Node kill = killRows.get(i);
			if (name == null || kill == null || name.text() == null || kill.text() == null)
			{
				continue;
			}
			String boss = KcMessages.stripTags(name.text()).replace(":", "").trim();
			String count = KcMessages.stripTags(kill.text()).replace(",", "").trim();
			try
			{
				int n = Integer.parseInt(count);
				if (!boss.isEmpty() && n >= 0)
				{
					out.put(boss, n);
				}
			}
			catch (NumberFormatException ex)
			{
				// a heading or an empty row
			}
		}
		return out;
	}

	/**
	 * The collection log page on screen: the items the player has, with how many.
	 *
	 * @return null when no page is on screen
	 */
	public static LogPage collectionPage(Game game)
	{
		Node header = game.widget(InterfaceID.Collection.HEADER_TEXT);
		if (header == null || header.children() == null)
		{
			return null;
		}
		Node titleNode = header.child(0);
		if (titleNode == null || titleNode.text() == null)
		{
			return null;
		}
		String title = KcMessages.stripTags(titleNode.text()).trim();
		Node list = game.widget(InterfaceID.Collection.ITEMS_CONTENTS);
		if (title.isEmpty() || list == null || list.children() == null)
		{
			return null;
		}
		Map<String, Integer> items = new LinkedHashMap<>();
		Map<String, Integer> ids = new LinkedHashMap<>();
		Map<Integer, Integer> drawn = new LinkedHashMap<>();
		for (Node child : list.children())
		{
			if (child == null || child.itemId() <= 0)
			{
				continue;
			}
			// items the player does not have are drawn faded (opacity above zero)
			int copies = child.opacity() == 0 ? Math.max(1, child.itemQuantity()) : 0;
			drawn.put(child.itemId(), copies);
			String name = game.itemName(child.itemId());
			if (name == null)
			{
				continue;
			}
			ids.putIfAbsent(name, child.itemId());
			if (copies > 0)
			{
				items.merge(name, copies, Integer::sum);
			}
		}
		return new LogPage(title, headerCounts(header), items, ids, drawn);
	}

	/**
	 * The counts in a collection log page's header, below the title: "Zulrah kills: 1,234" gives "Zulrah kills" and 1234, and
	 * "Thermonuclear Smoke Devil kills: 0" gives 0 (a boss with no kills is worth knowing too).  The "Obtained: 3/12" line is not a
	 * count.
	 */
	static Map<String, Integer> headerCounts(Node header)
	{
		Map<String, Integer> out = new LinkedHashMap<>();
		List<Node> lines = header.children();
		for (int i = 1; lines != null && i < lines.size(); i++)
		{
			Node line = lines.get(i);
			if (line == null || line.text() == null)
			{
				continue;
			}
			Matcher m = HEADER_COUNT.matcher(KcMessages.stripTags(line.text()).trim());
			if (!m.matches())
			{
				continue;
			}
			try
			{
				out.merge(m.group(1).trim(), Integer.parseInt(m.group(2).replace(",", "")), Math::max);
			}
			catch (NumberFormatException ex)
			{
				// too large to be a count
			}
		}
		return out;
	}

	/**
	 * The counts of a collection log page as the game holds them once the page has settled.  The game draws a page's counts from three
	 * player variables it reuses for every page ({@code VarPlayerID.COLLECTION_CATEGORY_COUNT} and the next two), and the server can
	 * send a page's values just after the page is drawn, so a page can first show the previous page's numbers under its own labels.
	 * Each count is matched to the variable it was drawn from by the value that variable had when the page was drawn, and takes the
	 * value it has now.  A count that matched no variable, or that matched two that no longer agree, is left out.
	 *
	 * @param shown  label to the number drawn
	 * @param atDraw the variables' values when the page was drawn
	 * @param now    the same variables' values now
	 */
	public static Map<String, Integer> settledCounts(Map<String, Integer> shown, int[] atDraw, int[] now)
	{
		Map<String, Integer> out = new LinkedHashMap<>();
		for (Map.Entry<String, Integer> e : shown.entrySet())
		{
			Integer value = null;
			boolean clash = false;
			for (int i = 0; i < atDraw.length && i < now.length; i++)
			{
				if (e.getValue() != null && atDraw[i] == e.getValue())
				{
					if (value == null)
					{
						value = now[i];
					}
					else if (value != now[i])
					{
						clash = true;
					}
				}
			}
			if (value != null && !clash)
			{
				out.put(e.getKey(), value);
			}
		}
		return out;
	}

	/**
	 * True when the items a page was drawn with are the ones the game holds for it now.  The game draws a page's items from an
	 * inventory the server fills ({@code InventoryID.COLLECTION_TRANSMIT}); a page drawn before the server sent its items shows
	 * another page's numbers.
	 *
	 * @param inventory    item id to how many the inventory holds now, or null when the client has none (then the page can only
	 *                     have been drawn with nothing owned)
	 * @param bodyTypeSwap the player's body type is the one the game draws a few items in another version for
	 *                     ({@code VarbitID.COLLECTION_PLAYER_BODYTYPE}): the version drawn is not the item id the inventory holds,
	 *                     so an owned item drawn under an id the inventory does not hold is not counted against the page
	 */
	public static boolean itemsMatch(LogPage page, Map<Integer, Integer> inventory, boolean bodyTypeSwap)
	{
		Map<Integer, Integer> held = inventory == null ? Collections.<Integer, Integer>emptyMap() : inventory;
		for (Map.Entry<Integer, Integer> e : page.drawn.entrySet())
		{
			Integer n = held.get(e.getKey());
			if (n == null && e.getValue() > 0 && bodyTypeSwap && inventory != null)
			{
				continue;
			}
			if ((n == null ? 0 : n) != e.getValue())
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Whose adventure log is open: the name after "The Exploits of".  The Boss Kill Log opens from the adventure log, and in
	 * a player-owned house it can be another player's.
	 *
	 * @return null when no adventure log is open
	 */
	public static String adventureLogOwner(Game game)
	{
		String owner = ownerIn(game, InterfaceID.MenuNew.TITLE);
		return owner != null ? owner : ownerIn(game, InterfaceID.Menu.LJ_LAYER2);
	}

	private static String ownerIn(Game game, int componentId)
	{
		Node container = game.widget(componentId);
		if (container == null)
		{
			return null;
		}
		String own = owner(container.text());
		if (own != null)
		{
			return own;
		}
		List<Node> children = container.children();
		if (children == null)
		{
			return null;
		}
		for (Node child : children)
		{
			if (child == null)
			{
				continue;
			}
			String found = owner(child.text());
			if (found != null)
			{
				return found;
			}
		}
		return null;
	}

	static String owner(String text)
	{
		if (text == null)
		{
			return null;
		}
		Matcher m = ADVENTURE_LOG_TITLE.matcher(KcMessages.stripTags(text));
		return m.find() ? m.group(1).trim() : null;
	}
}

package com.dropluckledger.plugin;

import com.dropluckledger.capture.BossIndex;
import com.dropluckledger.capture.BossIndex.KcLabel;
import com.dropluckledger.history.HistoryInput;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.List;
import java.util.Map;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Collects what RuneLite's own plugins saved about the player's history, for {@link com.dropluckledger.history.HistoryPlanner}:
 * <ul>
 * <li>the kill counts RuneLite's Chat Commands plugin saved from every kill-count message it has seen,</li>
 * <li>the totals the Loot Tracker plugin saved (items per boss, over the last year, if "Remember loot" is on).</li>
 * </ul>
 * None of these says which kill a drop came on, so history only ever brings in kill counts and owned copies.  (The game's own
 * screens, the Boss Kill Log and the collection log, are checked as the player opens them: {@code history.Catchup}.)
 */
public final class HistorySources
{
	public static final String SRC_KC = "RuneLite kill counts";
	public static final String SRC_LOOT = "Loot Tracker";

	private static final String KILLCOUNT_GROUP = "killcount";
	private static final String LOOT_TRACKER_GROUP = "loottracker";
	private static final String LOOT_PREFIX = "drops_";

	private static final Logger log = LoggerFactory.getLogger(HistorySources.class);

	private HistorySources()
	{
	}

	/**
	 * One saved Loot Tracker total (the part of its format the plugin needs; the rest is ignored).
	 */
	private static final class Aggregate
	{
		String type;
		String name;
		int kills;
		int[] drops;
	}

	/**
	 * Everything RuneLite's other plugins saved for the profile that is logged in.  Call on the client thread (item names are looked
	 * up in the game).
	 */
	public static HistoryInput collect(Game game, Gson gson, BossIndex index)
	{
		HistoryInput in = new HistoryInput();
		for (String key : game.savedKeys(KILLCOUNT_GROUP, ""))
		{
			Integer n = game.savedInt(KILLCOUNT_GROUP, key);
			if (n != null && n > 0)
			{
				in.addKc(key, n, SRC_KC);
			}
		}
		// a boss can have several Loot Tracker records (one per name its loot goes by): their kills add up
		Map<String, Integer> lootKills = new java.util.LinkedHashMap<>();
		for (String key : game.savedKeys(LOOT_TRACKER_GROUP, LOOT_PREFIX))
		{
			Aggregate a = parse(gson, game.savedText(LOOT_TRACKER_GROUP, key));
			if (a == null || a.name == null || a.drops == null || !("NPC".equals(a.type) || "EVENT".equals(a.type)))
			{
				continue;
			}
			String bossId = index.loot(a.name);
			if (bossId == null)
			{
				continue;
			}
			// the God Wars bodyguards' loot counts for the general, but their kills are not kills of the general
			if (a.kills > 0 && !index.isExtraLoot(bossId, a.name))
			{
				KcLabel label = index.kc(a.name);
				List<KcLabel> labels = index.labels(bossId);
				String name = label != null && label.bossId.equals(bossId) ? a.name : labels.isEmpty() ? null : labels.get(0).label;
				if (name != null)
				{
					lootKills.merge(name, a.kills, Integer::sum);
				}
			}
			for (int i = 0; i + 1 < a.drops.length; i += 2)
			{
				String item = game.itemName(a.drops[i]);
				if (item != null)
				{
					in.addOwned(bossId, null, item, a.drops[i + 1], SRC_LOOT);
				}
			}
		}
		for (Map.Entry<String, Integer> e : lootKills.entrySet())
		{
			in.addKc(e.getKey(), e.getValue(), SRC_LOOT);
		}
		return in;
	}

	private static Aggregate parse(Gson gson, String json)
	{
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, Aggregate.class);
		}
		catch (JsonParseException ex)
		{
			log.debug("Skipping a Loot Tracker record that could not be read", ex);
			return null;
		}
	}
}

package com.dropluckledger.plugin;

import com.dropluckledger.capture.Names;
import com.dropluckledger.plugin.Game.ItemInfo;
import com.dropluckledger.plugin.Game.ItemRef;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Finds the game's item picture for an item name.
 * <p>
 * Ids come from three places: items seen in loot and on collection log pages, a search of the tradeable items, and (for
 * what is left, mostly pets) a slow scan of the game's item list that runs a few ids per game tick.  What was found is kept
 * between sessions.
 */
public final class ItemIcons
{
	/**
	 * Item ids looked at per game tick by the scan; small enough not to be felt.
	 */
	static final int SCAN_PER_TICK = 100;
	/**
	 * Above the highest item id the game has.
	 */
	static final int SCAN_LIMIT = 40000;

	private final Game game;
	/**
	 * Flattened item name to item id.
	 */
	private final Map<String, Integer> ids = new ConcurrentHashMap<>();
	private final Set<String> searched = ConcurrentHashMap.newKeySet();
	private volatile boolean dirty;

	private Set<String> wanted = Collections.emptySet();
	private int scanNext = -1;
	private long scannedAt;

	public ItemIcons(Game game)
	{
		this.game = game;
	}

	// ------------------------------------------------------------------ what is known

	/**
	 * Remembers the id of an item seen in the game.
	 */
	public void learn(String name, int id)
	{
		if (name == null || id <= 0)
		{
			return;
		}
		String key = Names.flat(name);
		if (!key.isEmpty() && ids.putIfAbsent(key, id) == null)
		{
			dirty = true;
		}
	}

	/**
	 * The item id for a name, or 0 when it is not known.
	 */
	public int id(String name)
	{
		String key = Names.flat(name);
		Integer known = ids.get(key);
		if (known != null)
		{
			return known;
		}
		if (key.isEmpty() || !searched.add(key))
		{
			return 0;
		}
		int best = 0;
		for (ItemRef p : game.searchItems(name))
		{
			if (p.name.equalsIgnoreCase(name.trim()) && (best == 0 || p.id < best))
			{
				best = p.id;
			}
		}
		if (best > 0)
		{
			ids.put(key, best);
			dirty = true;
		}
		return best;
	}

	/**
	 * The item's picture (filled in by the game a moment after it is returned, when {@code whenLoaded} is called), or null
	 * when the id is not known.
	 */
	public BufferedImage image(String name, Runnable whenLoaded)
	{
		int id = id(name);
		return id > 0 ? game.itemImage(id, whenLoaded) : null;
	}

	// ------------------------------------------------------------------ saved between sessions

	/**
	 * True when something was learned since the last {@link #snapshot()}.
	 */
	public boolean isDirty()
	{
		return dirty;
	}

	/**
	 * What to save: flattened name to id, in name order.
	 */
	public synchronized Map<String, Integer> snapshot()
	{
		dirty = false;
		return new TreeMap<>(ids);
	}

	public synchronized long scannedAt()
	{
		return scannedAt;
	}

	public synchronized void restore(Map<String, Integer> saved, long scannedAtMillis)
	{
		for (Map.Entry<String, Integer> e : saved.entrySet())
		{
			if (e.getKey() != null && e.getValue() != null && e.getValue() > 0)
			{
				ids.putIfAbsent(e.getKey(), e.getValue());
			}
		}
		this.scannedAt = scannedAtMillis;
	}

	// ------------------------------------------------------------------ scan

	/**
	 * Starts looking through the game's items for the given names.  Does nothing when a scan is running.
	 *
	 * @param names the item names the ledger knows
	 */
	public synchronized void startScan(Iterable<String> names)
	{
		if (scanNext >= 0)
		{
			return;
		}
		Set<String> want = new HashSet<>();
		for (String n : names)
		{
			String key = Names.flat(n);
			if (!key.isEmpty() && !ids.containsKey(key))
			{
				want.add(key);
			}
		}
		if (want.isEmpty())
		{
			return;
		}
		wanted = want;
		scanNext = 1;
	}

	public synchronized boolean isScanning()
	{
		return scanNext >= 0;
	}

	/**
	 * Looks at the next few item ids.  Call on the client thread, once per game tick.
	 *
	 * @param now the time in milliseconds, kept as the time of the last finished scan
	 * @return true when the scan finished with this call
	 */
	public synchronized boolean scanTick(long now)
	{
		if (scanNext < 0)
		{
			return false;
		}
		int end = Math.min(SCAN_LIMIT, scanNext + SCAN_PER_TICK);
		for (int id = scanNext; id < end && !wanted.isEmpty(); id++)
		{
			ItemInfo c = game.item(id);
			if (c == null || c.name == null || c.noted || c.placeholder)
			{
				continue;
			}
			String key = Names.flat(c.name);
			if (wanted.remove(key))
			{
				if (ids.putIfAbsent(key, id) == null)
				{
					dirty = true;
				}
			}
		}
		scanNext = end;
		if (end >= SCAN_LIMIT || wanted.isEmpty())
		{
			scanNext = -1;
			wanted = Collections.emptySet();
			scannedAt = now;
			dirty = true;
			return true;
		}
		return false;
	}
}

package com.dropluckledger.plugin;

import java.awt.Component;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.Filepath;
import net.runelite.http.api.item.ItemPrice;

/**
 * {@link Game} over the real client and RuneLite's services.  This and the plugin class are the only places that use them;
 * everything here is a one-line hand-over.
 */
public final class RuneLiteGame implements Game
{
	private static final String RUNELITE_GROUP = "runelite";
	private static final String LOOT_TRACKER_KEY = "loottrackerplugin";

	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final ConfigManager configManager;
	private final ChatMessageManager chatMessageManager;

	public RuneLiteGame(Client client, ClientThread clientThread, ItemManager itemManager, ConfigManager configManager, ChatMessageManager chatMessageManager)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.configManager = configManager;
		this.chatMessageManager = chatMessageManager;
	}

	// ------------------------------------------------------------------ the player

	@Override
	public long accountHash()
	{
		return client.getAccountHash();
	}

	@Override
	public boolean isLoggedIn()
	{
		return client.getGameState() == GameState.LOGGED_IN;
	}

	@Override
	public boolean isStandardWorld()
	{
		return RuneScapeProfileType.getCurrent(client) == RuneScapeProfileType.STANDARD;
	}

	@Override
	public String playerName()
	{
		Player player = client.getLocalPlayer();
		return player == null ? null : player.getName();
	}

	@Override
	public int tickCount()
	{
		return client.getTickCount();
	}

	@Override
	public int realLevel(Skill skill)
	{
		return client.getRealSkillLevel(skill);
	}

	@Override
	public int varbit(int id)
	{
		return client.getVarbitValue(id);
	}

	@Override
	public int varp(int id)
	{
		return client.getVarpValue(id);
	}

	@Override
	public Map<Integer, Integer> inventory(int inventoryId)
	{
		ItemContainer container = client.getItemContainer(inventoryId);
		if (container == null)
		{
			return null;
		}
		Map<Integer, Integer> out = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				out.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return out;
	}

	@Override
	public boolean isMembersWorld()
	{
		return client.getWorldType().contains(WorldType.MEMBERS);
	}

	@Override
	public boolean isLootTrackerOn()
	{
		// RuneLite keeps whether a plugin is on under its class name in the "runelite" group; unset means its default (on)
		return !"false".equals(configManager.getConfiguration(RUNELITE_GROUP, LOOT_TRACKER_KEY));
	}

	// ------------------------------------------------------------------ the game's screens

	@Override
	public Node widget(int componentId)
	{
		return wrap(client.getWidget(componentId));
	}

	private static Node wrap(Widget widget)
	{
		return widget == null ? null : new WidgetNode(widget);
	}

	private static final class WidgetNode implements Node
	{
		private final Widget widget;

		WidgetNode(Widget widget)
		{
			this.widget = widget;
		}

		@Override
		public String text()
		{
			return widget.getText();
		}

		@Override
		public List<Node> children()
		{
			Widget[] children = widget.getChildren();
			if (children == null)
			{
				return null;
			}
			List<Node> out = new ArrayList<>(children.length);
			for (Widget child : children)
			{
				out.add(wrap(child));
			}
			return out;
		}

		@Override
		public Node child(int index)
		{
			return wrap(widget.getChild(index));
		}

		@Override
		public int itemId()
		{
			return widget.getItemId();
		}

		@Override
		public int itemQuantity()
		{
			return widget.getItemQuantity();
		}

		@Override
		public int opacity()
		{
			return widget.getOpacity();
		}
	}

	// ------------------------------------------------------------------ items

	@Override
	public ItemInfo item(int id)
	{
		try
		{
			ItemComposition c = itemManager.getItemComposition(id);
			return c == null ? null : new ItemInfo(c.getName(), c.getNote() != -1, c.getPlaceholderTemplateId() != -1);
		}
		catch (RuntimeException ex)
		{
			// ids the game has no item for
			return null;
		}
	}

	@Override
	public int canonicalItemId(int id)
	{
		return itemManager.canonicalize(id);
	}

	@Override
	public List<ItemRef> searchItems(String text)
	{
		List<ItemRef> out = new ArrayList<>();
		for (ItemPrice found : itemManager.search(text))
		{
			out.add(new ItemRef(found.getId(), found.getName()));
		}
		return out;
	}

	@Override
	public BufferedImage itemImage(int id, Runnable whenLoaded)
	{
		AsyncBufferedImage image = itemManager.getImage(id);
		if (image != null)
		{
			image.onLoaded(whenLoaded);
		}
		return image;
	}

	// ------------------------------------------------------------------ what other RuneLite plugins saved

	@Override
	public List<String> savedKeys(String group, String keyPrefix)
	{
		String profile = configManager.getRSProfileKey();
		return profile == null ? Collections.emptyList() : configManager.getRSProfileConfigurationKeys(group, profile, keyPrefix);
	}

	@Override
	public Integer savedInt(String group, String key)
	{
		return configManager.getRSProfileConfiguration(group, key, int.class);
	}

	@Override
	public String savedText(String group, String key)
	{
		return configManager.getRSProfileConfiguration(group, key);
	}

	// ------------------------------------------------------------------ chat, threads and files

	@Override
	public void gameMessage(String runeLiteFormattedMessage)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(runeLiteFormattedMessage)
			.build());
	}

	@Override
	public void invoke(Runnable task)
	{
		clientThread.invoke(task);
	}

	@Override
	public void invokeLater(Runnable task)
	{
		clientThread.invokeLater(task);
	}

	@Override
	public Filepath chooseFileToSave(Component parent, String title, String fileName, String description, String extension)
	{
		List<Filepath> files = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.setDialogTitle(title)
			.setFileName(fileName)
			.addExtensionFilter(description, extension)
			.setDefaultExtension(extension)
			.showDialog(parent);
		return files == null || files.isEmpty() ? null : files.get(0);
	}

	@Override
	public Filepath chooseFileToOpen(Component parent, String title, String description, String extension)
	{
		List<Filepath> files = new Filepath.Chooser()
			.setIsOpen()
			.setAcceptsFiles()
			.setDialogTitle(title)
			.addExtensionFilter(description, extension)
			.showDialog(parent);
		return files == null || files.isEmpty() ? null : files.get(0);
	}
}

package com.dropluckledger.plugin;

/**
 * Whether the plugin is recording at the moment, and if not why not (shown at the top of the side panel).
 */
public enum TrackingState
{
	/**
	 * The boss data is still being read.
	 */
	STARTING("Loading the boss data..."),
	/**
	 * Nobody is logged in, so there is no ledger to show.
	 */
	LOGGED_OUT("Log in to see and record your ledger."),
	/**
	 * Logged in on a world that has its own separate save (a Leagues, Deadman, tournament or beta world).
	 */
	PAUSED("Paused: this kind of world has its own save, so it is not recorded in your ledger."),
	/**
	 * Logged in and the ledger is being read from disk.
	 */
	LOADING("Loading your ledger..."),
	/**
	 * Recording.
	 */
	TRACKING("");

	private final String message;

	TrackingState(String message)
	{
		this.message = message;
	}

	/**
	 * What to tell the player; empty while recording.
	 */
	public String message()
	{
		return message;
	}
}

package com.dropluckledger.ui;

import com.dropluckledger.engine.Catalog;
import com.dropluckledger.engine.Data;
import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Env;
import com.dropluckledger.engine.Engine;
import com.dropluckledger.engine.Engine.ItemMeta;
import com.dropluckledger.engine.Luck;
import com.dropluckledger.ledger.BossState;
import com.dropluckledger.ledger.Drop;
import com.dropluckledger.ledger.Ledger;
import com.dropluckledger.ledger.Prefs;
import com.dropluckledger.plugin.ItemIcons;
import java.text.Collator;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Works out what the panel shows from the ledger.  The luck maths can take a moment, so this is meant to run on a
 * background thread; one call at a time (the maths keeps working state that must not be shared).  Results are kept
 * for as long as the part of the ledger they came from has not changed.
 */
final class Analyzer
{
	private static final Logger log = LoggerFactory.getLogger(Analyzer.class);

	private static final int MODELS = 24;
	private static final int ANALYSES = 1500;
	private static final int EXTRAS = 600;
	/**
	 * Stands for "worked out, and there is nothing to show".
	 */
	private static final Object NONE = new Object();
	/**
	 * The luck percentile from which an item counts as a spoon on the overview: "Slightly lucky" and up, the same line as the labels.
	 */
	private static final double SPOON_FROM = 0.60;
	/**
	 * Points on the chart.
	 */
	private static final int CHART_STEPS = 60;

	private final Ledger ledger;
	private final Data data;
	private final ItemIcons icons;
	private final Map<String, List<String>> logIndex;
	private final Map<String, Luck.Model> models = lru(MODELS);
	private final Map<String, Luck.ItemAnalysis> analyses = lru(ANALYSES);
	private final Map<String, Object> extras = lru(EXTRAS);

	Analyzer(Ledger ledger, ItemIcons icons)
	{
		this.ledger = ledger;
		this.data = ledger.data();
		this.icons = icons;
		this.logIndex = Catalog.logIndex(data);
	}

	private static <V> Map<String, V> lru(int max)
	{
		return new LinkedHashMap<String, V>(16, 0.75f, true)
		{
			private static final long serialVersionUID = 1L;

			@Override
			protected boolean removeEldestEntry(Map.Entry<String, V> eldest)
			{
				return size() > max;
			}
		};
	}

	/**
	 * Bosses whose collection log lists the item.
	 */
	List<String> bossesWith(String item)
	{
		List<String> l = logIndex.get(item);
		return l == null ? Collections.<String>emptyList() : l;
	}

	boolean shared(String item)
	{
		return bossesWith(item).size() > 1;
	}

	// ------------------------------------------------------------------ the maths, kept while nothing changes

	private Luck.Model model(String id, long rev)
	{
		String key = id + '|' + rev;
		Luck.Model m = models.get(key);
		if (m == null)
		{
			m = Luck.makeModel(data.boss(id), ledger.record(id), ledger.globals());
			models.put(key, m);
		}
		return m;
	}

	private Luck.ItemAnalysis analysis(String id, long rev, String name, int window)
	{
		String key = id + '|' + rev + '|' + name + '|' + window;
		Luck.ItemAnalysis a = analyses.get(key);
		if (a == null)
		{
			try
			{
				a = Luck.analyse(model(id, rev), name, window);
			}
			catch (RuntimeException ex)
			{
				log.warn("Could not work out {} at {}", name, id, ex);
				return null;
			}
			analyses.put(key, a);
		}
		return a;
	}

	private Views.AnyView anyUnique(String id, long rev, List<String> tracked, int window)
	{
		String key = "U|" + id + '|' + rev + '|' + window;
		Object c = extras.get(key);
		if (c != null)
		{
			return c == NONE ? null : (Views.AnyView) c;
		}
		Boss boss = data.boss(id);
		Catalog.AnyNames an = Catalog.anyNames(boss, tracked);
		Views.AnyView out = null;
		if (an.names.size() >= 2)
		{
			try
			{
				Luck.AnyUnique u = Luck.anyUnique(model(id, rev), an.names, window);
				if (u != null)
				{
					out = new Views.AnyView(u, an.names, an.sep, hasGold(boss, an.names));
				}
			}
			catch (RuntimeException ex)
			{
				log.warn("Could not work out the unique table of {}", id, ex);
			}
		}
		extras.put(key, out == null ? NONE : out);
		return out;
	}

	private static boolean hasGold(Boss boss, List<String> names)
	{
		Map<String, ItemMeta> m = boss.meta();
		for (String n : names)
		{
			ItemMeta im = m.get(n);
			if (im == null || im.seq == null)
			{
				continue;
			}
			for (ItemMeta other : m.values())
			{
				if (other.hidden && other.seq != null && other.seq.slot.equals(im.seq.slot))
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * The figures for an item that several bosses drop, pooled over the bosses the player has kills at.  Null when fewer than
	 * two such bosses, or when the selected boss is not one of them.
	 */
	private Luck.Pool pool(String name, String selected, int window)
	{
		List<String> ids = new ArrayList<>();
		for (String i : bossesWith(name))
		{
			if (ledger.kc(i) > 0)
			{
				ids.add(i);
			}
		}
		if (ids.size() < 2 || !ids.contains(selected))
		{
			return null;
		}
		StringBuilder k = new StringBuilder("P|").append(name).append('|').append(window);
		Map<String, Long> revs = new LinkedHashMap<>();
		for (String i : ids)
		{
			long r = ledger.revision(i);
			revs.put(i, r);
			k.append('|').append(i).append(':').append(r);
		}
		String key = k.toString();
		Object c = extras.get(key);
		if (c != null)
		{
			return c == NONE ? null : (Luck.Pool) c;
		}
		// the most recent receipt (counted in kills) decides where each boss's streak starts
		Map<String, Integer> bestStart = null;
		int bestTotal = -1;
		for (String i : ids)
		{
			for (Drop d : ledger.copyOf(i).drops)
			{
				if (!name.equals(d.item) || d.kc == null)
				{
					continue;
				}
				Map<String, Integer> start = new LinkedHashMap<>();
				int total = 0;
				for (String j : ids)
				{
					int s = j.equals(i) ? d.kc : (d.snap != null && d.snap.get(j) != null ? d.snap.get(j) : 0);
					start.put(j, s);
					total += s;
				}
				if (bestStart == null || total > bestTotal)
				{
					bestStart = start;
					bestTotal = total;
				}
			}
		}
		List<Luck.PoolMember> members = new ArrayList<>();
		for (String i : ids)
		{
			int snap = bestStart == null ? 0 : Math.min(bestStart.getOrDefault(i, 0), ledger.kc(i));
			members.add(new Luck.PoolMember(model(i, revs.get(i)), snap));
		}
		Luck.Pool out = null;
		try
		{
			out = Luck.analysePool(members, name, window);
		}
		catch (RuntimeException ex)
		{
			log.warn("Could not pool {}", name, ex);
		}
		extras.put(key, out == null ? NONE : out);
		return out;
	}

	// ------------------------------------------------------------------ a boss page

	/**
	 * The tracker tab of a boss; null when cancelled.
	 */
	synchronized Views.BossView boss(String id, BooleanSupplier cancelled)
	{
		Boss boss = data.boss(id);
		if (boss == null)
		{
			return null;
		}
		final long rev = ledger.revision(id);
		final int window = ledger.prefs().window;
		final BossState st = ledger.copyOf(id);
		final List<String> names = ledger.trackedNames(id);
		final Map<String, ItemMeta> meta = boss.meta();
		List<Views.ItemView> items = new ArrayList<>();
		for (String n : names)
		{
			if (cancelled.getAsBoolean())
			{
				return null;
			}
			ItemMeta m = meta.get(n);
			Luck.ItemAnalysis a = analysis(id, rev, n, window);
			Luck.Pool p = a != null ? pool(n, id, window) : null;
			String kind = Catalog.kindOf(boss, n);
			items.add(new Views.ItemView(n, kind.equals("other") ? "drop" : kind, m, a, p, shared(n)));
			if (icons != null)
			{
				icons.id(n);
			}
		}
		Views.AnyView any = st.kc > 0 ? anyUnique(id, rev, names, window) : null;
		Collator collator = Collator.getInstance(Locale.ENGLISH);
		List<String> addable = new ArrayList<>();
		Set<String> shown = new HashSet<>(names);
		for (Map.Entry<String, ItemMeta> e : meta.entrySet())
		{
			if (!shown.contains(e.getKey()) && !e.getValue().hidden)
			{
				addable.add(e.getKey());
			}
		}
		addable.sort(collator);
		if (icons != null)
		{
			for (Drop d : st.drops)
			{
				icons.id(d.item);
			}
		}
		return new Views.BossView(id, rev, st.kc, window, items, any, st, addable);
	}

	// ------------------------------------------------------------------ the overview

	/**
	 * The overview page; null when cancelled.  It lists the bosses ticked under "Bosses to show" only; an item several bosses drop
	 * still has the luck of all the player's kills at them, so it reads the same as on the boss pages.
	 */
	synchronized Views.OverviewView overview(BooleanSupplier cancelled)
	{
		final Prefs prefs = ledger.prefs();
		final int window = prefs.window;
		final Set<String> hidden = new HashSet<>(prefs.hiddenBosses);
		final long overall = ledger.revision();
		List<String> active = ledger.activeBosses();
		List<String> ids = new ArrayList<>();
		for (String id : active)
		{
			if (!hidden.contains(id))
			{
				ids.add(id);
			}
		}
		List<Views.Rank> rows = new ArrayList<>();
		Set<String> ranked = new HashSet<>();
		List<Views.BossRow> bosses = new ArrayList<>();
		for (String id : ids)
		{
			if (cancelled.getAsBoolean())
			{
				return null;
			}
			Boss boss = data.boss(id);
			long rev = ledger.revision(id);
			BossState st = ledger.copyOf(id);
			List<String> names = ledger.trackedNames(id);
			if (st.kc > 0)
			{
				// the pieces of a set (the Barrows equipment, a moon's set) are one line: with many rare pieces one of them is bound to
				// come early, so the set's luck is all its pieces against all the pieces expected
				Map<String, SetTotal> sets = new LinkedHashMap<>();
				Map<String, ItemMeta> meta = boss.meta();
				for (String n : names)
				{
					Luck.ItemAnalysis a = analysis(id, rev, n, window);
					ItemMeta im = meta.get(n);
					if (a != null && im != null && im.group != null && a.expected != null && !shared(n))
					{
						sets.computeIfAbsent(im.group, g -> new SetTotal()).add(n, a.O, a.expected);
						continue;
					}
					if (a == null || a.collected || !(a.pNext > 0) || im != null && im.noSpoon)
					{
						continue;
					}
					// an item several bosses drop is one line, with the luck of all of them together
					Luck.Pool p = shared(n) ? pool(n, id, window) : null;
					if (p != null)
					{
						if (ranked.add(n) && !Double.isNaN(p.pct))
						{
							rows.add(rankOf(p, hidden));
						}
					}
					else if (a.pct != null && a.expected != null && a.another != null)
					{
						rows.add(new Views.Rank(id, boss.name, n, a.O, a.expected, a.pct, a.another, a.label, false));
					}
					if (icons != null)
					{
						icons.id(n);
					}
				}
				for (Map.Entry<String, SetTotal> e : sets.entrySet())
				{
					SetTotal t = e.getValue();
					if (t.expected > 0)
					{
						double pct = Luck.poissonPct(t.got, t.expected);
						rows.add(new Views.Rank(id, boss.name, e.getKey(), t.got, t.expected, pct, Luck.poissonAtLeast(t.got + 1, t.expected),
							Luck.luckLabel(pct), false, t.pieces, t.icon));
					}
				}
			}
			Set<String> have = new HashSet<>();
			for (Drop d : st.drops)
			{
				have.add(d.item);
			}
			int got = 0;
			Set<String> logNames = boss.logSet();
			for (String n : logNames)
			{
				if (have.contains(n))
				{
					got++;
				}
			}
			Views.AnyView any = st.kc > 0 ? anyUnique(id, rev, names, window) : null;
			bosses.add(new Views.BossRow(id, boss.name, st.kc, got, logNames.size(), any == null ? null : any.u, st.u));
		}
		List<Views.Rank> spoons = new ArrayList<>();
		for (Views.Rank r : rows)
		{
			if (r.got > 0 && r.pct >= SPOON_FROM)
			{
				spoons.add(r);
			}
		}
		// luckiest first; at the same luck the one further ahead of its rate
		spoons.sort(Comparator.comparingDouble((Views.Rank r) -> r.pct).reversed().thenComparingDouble(r -> r.expected - r.got)
			.thenComparing(r -> r.item, String.CASE_INSENSITIVE_ORDER));
		bosses.sort(Comparator.comparingLong((Views.BossRow b) -> b.updated).reversed().thenComparing(b -> b.name, String.CASE_INSENSITIVE_ORDER));
		List<Luck.Pool> pooled = new ArrayList<>();
		Set<String> seen = new HashSet<>();
		for (String id : ids)
		{
			if (cancelled.getAsBoolean())
			{
				return null;
			}
			for (String n : ledger.trackedNames(id))
			{
				if (!shared(n) || !seen.add(n))
				{
					continue;
				}
				Luck.Pool p = pool(n, id, window);
				if (p != null)
				{
					pooled.add(p);
				}
			}
		}
		pooled.sort(Comparator.comparingDouble((Luck.Pool p) -> p.pct));
		return new Views.OverviewView(overall, ids.size(), active.size(), spoons, bosses, pooled);
	}

	/**
	 * The pieces of a set added up: the copies received, the copies expected, and the piece whose picture stands for the set (the
	 * first one received).
	 */
	private static final class SetTotal
	{
		int got;
		double expected;
		int pieces;
		String icon;

		void add(String item, int copies, double e)
		{
			if (icon == null || got == 0 && copies > 0)
			{
				icon = item;
			}
			got += copies;
			expected += e;
			pieces++;
		}
	}

	/**
	 * A ranking line for an item pooled over several bosses; it opens the shown boss the player has the most kills at.
	 */
	private static Views.Rank rankOf(Luck.Pool p, Set<String> hidden)
	{
		Luck.PoolPer main = null;
		for (Luck.PoolPer x : p.per)
		{
			if (!hidden.contains(x.id) && (main == null || x.K > main.K))
			{
				main = x;
			}
		}
		if (main == null)
		{
			main = p.per.get(0);
		}
		String where = main.name + (p.per.size() > 1 ? " +" + (p.per.size() - 1) + " more" : "");
		return new Views.Rank(main.id, where, p.name, p.O, p.expected, p.pct, p.another, p.label, true);
	}

	// ------------------------------------------------------------------ the drop table

	synchronized Views.TableView table(String id)
	{
		Boss boss = data.boss(id);
		if (boss == null)
		{
			return null;
		}
		Map<String, Object> vals = ledger.currentParams(id);
		Env env = Engine.makeEnv(boss, vals, ledger.globals(), Math.max(0, ledger.kc(id)));
		Map<String, Engine.ItemProb> probs = Engine.itemProbs(boss, env, null, null);
		Map<String, Views.RowInfo> info = Views.rowInfo(boss);
		Map<String, ItemMeta> meta = boss.meta();
		Set<String> logNames = boss.logSet();
		List<Views.TableRow> rows = new ArrayList<>();
		for (Map.Entry<String, Engine.ItemProb> e : probs.entrySet())
		{
			String n = e.getKey();
			Views.RowInfo ri = info.get(n);
			ItemMeta m = meta.get(n);
			if (m != null && m.hidden)
			{
				continue;
			}
			boolean notable = m != null && (m.isUnique() || m.isPet()) || logNames.contains(n);
			rows.add(new Views.TableRow(n, e.getValue().p, ri == null ? "" : ri.qty, ri == null ? new ArrayList<String>() : ri.rates,
				ri == null ? new ArrayList<String>() : ri.where, logNames.contains(n), notable));
			if (icons != null)
			{
				icons.id(n);
			}
		}
		// a tertiary or a pet whose rate is not published yet never rolls, but it is listed with the rest
		for (Map.Entry<String, ItemMeta> e : meta.entrySet())
		{
			String n = e.getKey();
			ItemMeta m = e.getValue();
			if (m.hidden || !m.rateUnknown() || probs.containsKey(n))
			{
				continue;
			}
			Views.RowInfo ri = info.get(n);
			rows.add(new Views.TableRow(n, 0, ri == null ? "" : ri.qty, ri == null ? new ArrayList<String>() : ri.rates,
				ri == null ? new ArrayList<String>() : ri.where, logNames.contains(n), m.isUnique() || m.isPet() || logNames.contains(n)));
		}
		rows.sort(Comparator.comparingDouble((Views.TableRow r) -> r.p).reversed());
		return new Views.TableView(id, boss.always, rows);
	}

	// ------------------------------------------------------------------ the chart

	/**
	 * The curve behind an item card: the chance of getting it within a number of kills after the last copy.
	 */
	synchronized Views.ChartData chart(String id, String item)
	{
		Boss boss = data.boss(id);
		if (boss == null)
		{
			return null;
		}
		final long rev = ledger.revision(id);
		final int window = ledger.prefs().window;
		Luck.ItemAnalysis a = analysis(id, rev, item, window);
		if (a == null)
		{
			return null;
		}
		Luck.Model m = model(id, rev);
		String nm = a.seq != null ? slotFirst(boss, a.seq.slot) : item;
		if (nm == null)
		{
			nm = item;
		}
		final int d = a.need;
		final int from = a.streakFrom;
		double xmax = Math.max(30, a.streak * 1.3);
		if (a.kto != null)
		{
			Double k99 = a.kto.get(0.99);
			if (k99 != null && !Double.isInfinite(k99) && !Double.isNaN(k99))
			{
				xmax = Math.max(xmax, a.streak + k99);
			}
		}
		xmax = Math.min(xmax, 3e6);
		double[] xs = new double[CHART_STEPS + 1];
		double[] ys = new double[CHART_STEPS + 1];
		for (int i = 0; i <= CHART_STEPS; i++)
		{
			int x = (int) Math.round(xmax * i / CHART_STEPS);
			xs[i] = x;
			ys[i] = x == 0 ? 0 : Luck.atLeast(d, m.runsFor(nm, from + 1, from + x));
		}
		return new Views.ChartData(item, xs, ys, xmax, a.streak);
	}

	private static String slotFirst(Boss boss, String slot)
	{
		for (Data.Table t : boss.tables)
		{
			for (Data.Row r : t.items)
			{
				if (r.seq != null && r.seq.slot.equals(slot))
				{
					return r.name;
				}
			}
		}
		return null;
	}
}

package com.dropluckledger.ui;

import com.dropluckledger.engine.Luck;
import java.awt.BorderLayout;
import java.awt.Color;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;

/**
 * "Any unique": how lucky the player has been with the boss's uniques as a whole (or with its unique table, where the boss rolls
 * the rest separately).  One compact row like an item card; the details are in the tooltip.
 */
@SuppressWarnings("serial")
final class AnyCard extends Column
{
	private final Meter meter = new Meter(5);

	AnyCard(Views.AnyView any)
	{
		super(3, true);
		setBackground(Look.CARD);
		setBorder(javax.swing.BorderFactory.createCompoundBorder(javax.swing.BorderFactory.createLineBorder(Look.GOLD, 1), Look.pad(4, 6, 4, 6)));
		final Luck.AnyUnique u = any.u;
		final boolean table = any.isTable();
		final boolean known = !Double.isNaN(u.pct) && u.label != null && !"na".equals(u.label.key);
		final Color color = known ? Look.luck(u.label.key) : Look.MUTED;
		final Color barColor = Look.chance(u.another);

		JPanel top = new JPanel(new BorderLayout(6, 0));
		top.setOpaque(false);
		JLabel name = Look.wrapped("<b>" + (table ? "Unique table" : "Any unique") + "</b> " + Look.dim(any.names.size() + " items"), Look.CARD_TEXT - 60,
			Look.body(), Look.TEXT);
		top.add(name, BorderLayout.CENTER);
		JLabel pc = Look.label(Fmt.pct(u.another), Look.bold().deriveFont(Look.bold().getSize2D() + 2f), barColor);
		pc.setHorizontalAlignment(SwingConstants.RIGHT);
		top.add(pc, BorderLayout.EAST);
		add(top);

		meter.set(u.another, barColor);
		add(meter);

		JPanel sub = new JPanel(new BorderLayout(4, 0));
		sub.setOpaque(false);
		sub.add(Look.label(Fmt.rate(u.pNext) + " · " + u.O + " vs " + Fmt.expected(u.expected) + " expected", Look.small(), Look.MUTED), BorderLayout.CENTER);
		if (known)
		{
			sub.add(Look.label(u.label.text, Look.small(), color), BorderLayout.EAST);
		}
		add(sub);
		setToolTipText(tip(any, table, known));
	}

	private static String tip(Views.AnyView any, boolean table, boolean known)
	{
		Luck.AnyUnique u = any.u;
		StringBuilder b = new StringBuilder("<b>").append(table ? "Unique table" : "Any unique").append("</b><br>").append(Look.esc(describe(any, table)));
		b.append("<br><b>").append(Fmt.pctHtml(u.another)).append("</b> chance of ").append(u.O > 0 ? "another " + (table ? "table hit" : "unique") : "one")
			.append(" by now, from all your kills. ").append(Look.dim("Kills past the rate carry over to the next one."));
		b.append("<br>Per kill: ").append(Look.esc(Fmt.rate(u.pNext)));
		b.append("<br>").append(table ? "Table hits" : "Uniques").append(": ").append(u.O).append(" vs ").append(Fmt.expected(u.expected)).append(" expected");
		if (known)
		{
			b.append("<br>Luck: ").append(Look.colored("<b>" + Look.esc(u.label.text) + "</b>", Look.luck(u.label.key))).append(" · luckier than ")
				.append(Fmt.pctHtml(u.pct)).append(" of players with the same kills");
		}
		b.append("<br>Chance of 1+ in all your kills: ").append(Fmt.pctHtml(u.cum));
		b.append("<br>Next ").append(u.window).append(" kills: ").append(Fmt.pctHtml(u.fwd.get(u.window)));
		if (u.streakKnown)
		{
			b.append("<br>Dry streak: ").append(Fmt.num(u.streak)).append(" kills since your last (").append(Fmt.pctHtml(u.meter)).append(" would have had another)");
		}
		else
		{
			b.append("<br>Dry streak: not known, because your last ").append(table ? "table hit" : "unique").append(" has no kill number.");
		}
		return Look.tip(b.toString());
	}

	private static String describe(Views.AnyView any, boolean table)
	{
		List<String> shown = any.names.subList(0, Math.min(6, any.names.size()));
		String list = String.join(", ", shown) + (any.names.size() > 6 ? "…" : "");
		if (table)
		{
			return "Chance of hitting the unique table: " + list + ". "
				+ (any.gold ? "The vestige slot counts on every one of its rolls (the first two drop gold rings, the third the vestige). " : "")
				+ String.join(", ", any.separate) + (any.separate.size() > 1 ? " are" : " is") + " rolled separately and has its own card.";
		}
		return "At least one of: " + list + ".";
	}
}

