	{
		Views.ChartData known = charts.get(item);
		if (known != null)
		{
			into.accept(known);
			return;
		}
		Jobs.Slot<Views.ChartData> slot = chartJobs.computeIfAbsent(item, k -> ctx.jobs().slot());
		slot.run(c -> ctx.analyzer().chart(id, item), d ->
