	 */
	List<JButton> noteButtons(String key)
	{
		Notice n = key == null ? (shown.isEmpty() ? null : shown.get(shown.size() - 1)) : keyed.get(key);
		List<JButton> out = new ArrayList<>();
		if (n != null)
		{
			for (Component c : n.buttons.getComponents())
			{
				out.add((JButton) c);
			}
