			.addItem(QUIVER, "Dizana's quiver (uncharged)").addItem(BLIGHTED_RESTORE, "Blighted super restore(4)")
			.addItem(BLIGHTED_MANTA, "Blighted manta ray").addItem(ETHER, "Revenant ether").addItem(TWISTED_BOW, "Twisted bow")
