		waitFor("the boss data", () -> tracker.core() != null);
		game.logIn(42);
		tracker.onGameStateChanged(GameState.LOGGED_IN);
		waitFor("tracking", () -> tracker.state() == TrackingState.TRACKING);
	}

	@After
	public void tearDown()
