		loot(LootRecordType.EVENT, "Fortis Colosseum", null, SPLINTERS, 900);
		BossState f = boss("fortis-colosseum");
		assertEquals(3, f.kc);
		assertEquals(7, num(param("fortis-colosseum", 1, "waves")));
