	@Test
	public void sampleSessionAcrossSeveralBosses()
	{
		int tick = 0;
		for (int i = 1; i <= 30; i++)
		{
			tick += 80;
			kc(zulrahKc(i), tick);
			capture.onLoot(loot("Zulrah", tick + 2, i % 10 == 0 ? new String[]{"Coins", "Magic fang"} : new String[]{"Coins"}));
			tick += 80;
			kc("Your Vorkath kill count is: <col=ff0000>" + i * 2 + "</col>.", tick);
			capture.onLoot(loot("Vorkath", tick + 1, "Bones"));
		}
		assertEquals(30, boss("zulrah").kc);
		assertEquals(60, boss("vorkath").kc);
		assertEquals(3, boss("zulrah").copies("Magic fang"));
		assertEquals(Arrays.asList(10, 20, 30), Arrays.asList(
			boss("zulrah").drops.get(0).kc, boss("zulrah").drops.get(1).kc, boss("zulrah").drops.get(2).kc));
		assertEquals(Arrays.asList("vorkath", "zulrah"), sorted(ledger.activeBosses()));
	}

	private static List<String> sorted(List<String> l)
	{
		List<String> c = new ArrayList<>(l);
		Collections.sort(c);
		return c;
	}

	// ------------------------------------------------------------------ the drop log

	private final List<String> lootLog = new ArrayList<>();

	private void logLoot()
	{
		capture.setLootLog((t, boss, kill, items, snap) ->
		{
			StringBuilder b = new StringBuilder(boss).append('@').append(kill).append(':');
			for (Stack st : items)
			{
				b.append(' ').append(st.name).append(" x").append(st.qty);
			}
			if (snap != null)
			{
				b.append(" snap").append(snap);
			}
			lootLog.add(b.toString());
		});
	}

	@Test
	public void everyLootIsLoggedWithAllItsItems()
	{
		logLoot();
		kc(zulrahKc(100), 10);
		capture.onLoot(new Loot("Zulrah", 1, Arrays.asList(new Stack("Coins", 40_000), new Stack("Zulrah's scales", 120)), null, 11));
		assertEquals(Collections.singletonList("zulrah@100: Coins x40000 Zulrah's scales x120"), lootLog);
		// nothing of it is tracked, so the ledger has none of it
		assertTrue(boss("zulrah").drops.isEmpty());
