	@Test
	public void aRaidsChestIsOpenedLongAfterItsCount()
	{
		kc("Chambers of Xeric Challenge Mode", 20, 100);
		// Olm dies, the team takes a few minutes to loot the chest
		capture.onTick(1500, true);
