package com.dropluckledger.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.dropluckledger.TestData;
import com.dropluckledger.engine.Data.Boss;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;

/**
 * A boss whose setting the game reveals for every kill (the Maggot King's reward, whose loot it was) can have a period per kill.
 * The figures must stay exact and quick.
 */
public class ManyPeriodsTest
{
	private final Data data = TestData.get();

	@Test
	public void aPeriodPerKillGivesTheSameFiguresQuickly()
	{
		Boss b = data.boss("maggot-king");
		int kills = 3000;
		Luck.BossRecord rec = new Luck.BossRecord();
		rec.kc = kills;
		for (int k = 1; k <= kills; k++)
		{
			Map<String, Object> p = new LinkedHashMap<>();
			p.put("choice", k % 3 == 0 ? "eggs" : "stomach");
			rec.segs.add(new Luck.Seg(k, p));
		}
		rec.drops.add(new Luck.DropRec("Elder venator fang", 1200));
		long t0 = System.nanoTime();
		Luck.Model m = Luck.makeModel(b, rec, new HashMap<>());
		Luck.ItemAnalysis fang = Luck.analyse(m, "Elder venator fang", 50);
		Luck.ItemAnalysis pet = Luck.analyse(m, "Maggot marquess", 50);
		long ms = (System.nanoTime() - t0) / 1_000_000;
		assertTrue("took " + ms + " ms", ms < 3000);
		// 2,000 open-stomach kills at 1/340 for the fang; the pet at 1/3,500 on those and 1/1,502.4 on the 1,000 egg-takes
		assertEquals(1 - Math.pow(1 - 1 / 340.0, 2000), fang.cum, 1e-9);
		assertEquals(1 - Math.pow(1 - 1 / 3500.0, 2000) * Math.pow(1 - 1 / 1502.4, 1000), pet.cum, 1e-9);
		assertEquals(2000 / 340.0, fang.expected, 1e-6);
	}
}

package com.dropluckledger.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.dropluckledger.TestData;
import com.dropluckledger.engine.Data.Boss;
import java.util.HashMap;
import org.junit.Test;

/**
 * Items with duplicate protection (the halberd pieces, the moon sets, the keris jewels...): only the pieces held the fewest of can
 * drop.  Their luck and their chances ahead follow the set as a whole.
 */
public class NoDuplicateLuckTest
{
	private final Data data = TestData.get();

	private Luck.Model araxxor(int kc, Object... drops)
	{
		Boss b = data.boss("araxxor");
		Luck.BossRecord rec = new Luck.BossRecord();
		rec.kc = kc;
		rec.segs.add(new Luck.Seg(1, Engine.defaultParams(b)));
		for (int i = 0; i < drops.length; i += 2)
		{
			rec.drops.add(new Luck.DropRec((String) drops[i], (Integer) drops[i + 1]));
		}
		return Luck.makeModel(b, rec, new HashMap<>());
	}

	@Test
	public void aPieceThatCannotDropNowCanOnceTheRestHave()
	{
		Luck.Model m = araxxor(1000, "Noxious pommel", 200, "Noxious point", 500);
		Luck.ItemAnalysis blade = Luck.analyse(m, "Noxious blade", 100);
		Luck.ItemAnalysis pommel = Luck.analyse(m, "Noxious pommel", 100);
		// the blade is the only piece left: it has the whole set's chance
		assertEquals(1 / 200.0, blade.pNext, 1e-12);
		assertEquals(1 - Math.pow(1 - 1 / 200.0, 100), blade.fwd.get(100), 1e-9);
		// a second pommel needs the blade first, but it is not impossible
		assertEquals(0, pommel.pNext, 0);
		assertTrue(pommel.fwd.get(1000) > 0.3);
		assertTrue(pommel.kto.get(0.5) < Double.POSITIVE_INFINITY);
	}

	@Test
	public void aPieceReceivedEarlyIsJudgedOverAllTheKills()
	{
		// one pommel in 300 kills.  Counting only the kills before the copy (after it the pommel cannot drop until the set is done)
		// would make it look lucky; the luck is that of the whole 300 kills, where the pommel's chance grows as the other pieces come
		Luck.Model m = araxxor(300, "Noxious pommel", 20);
		Luck.ItemAnalysis pommel = Luck.analyse(m, "Noxious pommel", 50);
		// by hand: the pommel is still to come while 0, 1 or 2 of the other pieces have dropped (3, 2 or 1 pieces share the 1/200)
		double[] st = {1, 0, 0};
		double got = 0;
		for (int k = 0; k < 300; k++)
		{
			double[] nx = new double[3];
			for (int i = 0; i < 3; i++)
			{
				double each = 1 / 200.0 / (3 - i);
				got += st[i] * each;
				nx[i] += st[i] * (1 - each * (3 - i));
				if (i < 2)
				{
					nx[i + 1] += st[i] * each * (2 - i);
				}
			}
			st = nx;
		}
		assertEquals(got, pommel.exceed, 1e-9);
		// mid-p: P(more than one) + half P(exactly one)
		assertEquals(pommel.another + 0.5 * (pommel.exceed - pommel.another), 1 - pommel.pct, 1e-9);
	}

	// ------------------------------------------------------------------ the keris partisan jewels (Tombs of Amascut)

	private static final String[] JEWELS = {"Eye of the Corruptor", "Jewel of the Sun", "Breach of the Scarab", "Jewel of Amascut"};

	/**
	 * The chance of each jewel per raid at a kill count, holding the copies given (jewel order as in {@link #JEWELS}).
	 */
	private double[] jewels(int kc, int... owned)
	{
		Boss b = data.boss("tombs-of-amascut");
		java.util.Map<String, Integer> have = new HashMap<>();
		for (int i = 0; i < owned.length; i++)
		{
			have.put(JEWELS[i], owned[i]);
		}
		Engine.Ctx ctx = new Engine.Ctx()
		{
			@Override
			public int owned(Data.Row row)
			{
				return have.getOrDefault(row.name, 0);
			}

			@Override
			public double since(Data.Row row)
			{
				return 0;
			}
		};
		java.util.Map<String, Engine.ItemProb> p = Engine.itemProbs(b, Engine.makeEnv(b, Engine.defaultParams(b), new HashMap<>(), kc), ctx, null);
		double[] out = new double[4];
		for (int i = 0; i < 4; i++)
		{
			Engine.ItemProb ip = p.get(JEWELS[i]);
			out[i] = ip == null ? 0 : ip.p;
		}
		return out;
	}

	@Test
	public void theJewelsRiseUntilAllFourAreOwnedThenGoBackToTheirBaseRate()
	{
		// 1/50 each at first, 3/50 each from 75 raids
		assertEquals(1 / 50.0, jewels(0)[0], 1e-12);
		assertEquals(3 / 50.0, jewels(75)[3], 1e-12);
		assertEquals(3 / 50.0, jewels(400)[1], 1e-12);
		// while any is missing a hit gives one not owned: 1/37.5, 1/25, 1/12.5 at the base rate
		double[] one = jewels(0, 1);
		assertEquals(0, one[0], 0);
		assertEquals(1 / 37.5, one[1], 1e-12);
		assertEquals(1 / 25.0, jewels(0, 1, 1)[3], 1e-12);
		assertEquals(1 / 12.5, jewels(0, 1, 1, 1)[3], 1e-12);
		assertEquals(12 / 50.0, jewels(75, 1, 1, 1)[3], 1e-12);
		// all four owned: back to 1/50 each whatever the kill count, and a duplicate can drop again
		for (double p : jewels(300, 1, 1, 1, 1))
		{
			assertEquals(1 / 50.0, p, 1e-12);
		}
		for (double p : jewels(300, 2, 1, 1, 1))
		{
			assertEquals(1 / 50.0, p, 1e-12);
		}
	}

	private Luck.Model toa(int kc, Object... drops)
	{
		Boss b = data.boss("tombs-of-amascut");
		Luck.BossRecord rec = new Luck.BossRecord();
		rec.kc = kc;
		java.util.Map<String, Object> params = Engine.defaultParams(b);
		params.put("raidLevel", 400);
		params.put("points", 30000);
		rec.segs.add(new Luck.Seg(1, params));
		for (int i = 0; i < drops.length; i += 2)
		{
			rec.drops.add(new Luck.DropRec((String) drops[i], (Integer) drops[i + 1]));
		}
		return Luck.makeModel(b, rec, new HashMap<>());
	}

	@Test
	public void theJewelsLuckFollowsTheSetAndThenTheBaseRate()
	{
		// the figures of the web page's luck model for the same raids
		Luck.Model m = toa(300, "Eye of the Corruptor", 10, "Jewel of the Sun", 20, "Breach of the Scarab", 30, "Jewel of Amascut", 40,
			"Eye of the Corruptor", 200);
		Luck.ItemAnalysis eye = Luck.analyse(m, "Eye of the Corruptor", 50);
		Luck.ItemAnalysis sun = Luck.analyse(m, "Jewel of the Sun", 50);
		assertEquals(6.328946321716795, eye.expected, 1e-9);
		assertEquals(0.01745852032777906, eye.pct, 1e-9);
		assertEquals(0.002366893501001721, sun.pct, 1e-9);
		assertEquals(1 / 50.0, sun.pNext, 1e-12);
		assertEquals(0.6358303199128831, sun.fwd.get(50), 1e-9);
		assertEquals(0.9947666512139663, sun.meter, 1e-9);
		// before, the rate stayed at 3/50 once all four were owned: three times too many expected
		assertTrue(eye.expected < 7);
		// a player still missing one jewel after 300 raids: it has the whole roll, 12/50
		Luck.ItemAnalysis last = Luck.analyse(toa(300, "Eye of the Corruptor", 10, "Jewel of the Sun", 20, "Breach of the Scarab", 30),
			"Jewel of Amascut", 50);
		assertEquals(6.328946321716858, last.expected, 1e-9);
		assertEquals(0.24, last.pNext, 1e-12);
		assertEquals(0.9999989018046156, last.fwd.get(50), 1e-9);
	}
}

package com.dropluckledger.engine;

import com.dropluckledger.engine.Data.Boss;
import com.dropluckledger.engine.Engine.ItemProb;
import com.dropluckledger.engine.Luck.AnyUnique;
import com.dropluckledger.engine.Luck.BossRecord;
import com.dropluckledger.engine.Luck.DropRec;
import com.dropluckledger.engine.Luck.ItemAnalysis;
import com.dropluckledger.engine.Luck.Model;
import com.dropluckledger.engine.Luck.Pool;
import com.dropluckledger.engine.Luck.PoolMember;
import com.dropluckledger.engine.Luck.Seg;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Checks the Java engine against vectors produced by the JavaScript engine it was ported from
 * (src/test/resources/parity.json, generated by tools/gen_parity.js of the web app).
 */
public class ParityTest
{
	private static Data data;
	private static JsonObject ref;
	private static final List<String> problems = new ArrayList<>();
	private static int checks;

	@BeforeClass
	public static void load() throws Exception
	{
		try (InputStream in = ParityTest.class.getResourceAsStream("/com/dropluckledger/data.json"))
		{
			data = Data.load(new Gson(), in);
		}
		try (InputStreamReader r = new InputStreamReader(ParityTest.class.getResourceAsStream("/parity.json"), StandardCharsets.UTF_8))
		{
			ref = new JsonParser().parse(r).getAsJsonObject();
		}
	}

	// ------------------------------------------------------------------ helpers
	private static double num(JsonElement e)
	{
		if (e == null || e.isJsonNull())
		{
			return Double.NaN;
		}
		String s = e.getAsString();
		switch (s)
		{
			case "Infinity":
				return Double.POSITIVE_INFINITY;
			case "-Infinity":
				return Double.NEGATIVE_INFINITY;
			case "NaN":
				return Double.NaN;
			default:
				return e.getAsDouble();
		}
	}

	private static void same(String where, double expected, double actual)
	{
		checks++;
		if (Double.isNaN(expected) && Double.isNaN(actual))
		{
			return;
		}
		if (expected == actual)
		{
			return;
		}
		double diff = Math.abs(expected - actual);
		double scale = Math.max(Math.abs(expected), Math.abs(actual));
		if (diff <= 1e-12 || diff <= 1e-9 * scale)
		{
			return;
		}
		problems.add(where + ": expected " + expected + " got " + actual);
	}

	private static void sameNullable(String where, JsonElement expected, Double actual)
	{
		checks++;
		boolean en = expected == null || expected.isJsonNull();
		if (en != (actual == null))
		{
			problems.add(where + ": expected " + (en ? "null" : expected) + " got " + actual);
			return;
		}
		if (!en)
		{
			same(where, num(expected), actual);
		}
	}

	private static void eq(String where, Object expected, Object actual)
	{
		checks++;
		if (expected == null ? actual != null : !expected.equals(actual))
		{
			problems.add(where + ": expected " + expected + " got " + actual);
		}
	}

	private static Map<String, Object> params(JsonObject o)
	{
		Map<String, Object> m = new LinkedHashMap<>();
		for (Map.Entry<String, JsonElement> e : o.entrySet())
		{
			com.google.gson.JsonPrimitive p = e.getValue().getAsJsonPrimitive();
			m.put(e.getKey(), p.isBoolean() ? (Object) p.getAsBoolean() : p.isNumber() ? (Object) p.getAsDouble() : p.getAsString());
		}
		return m;
	}

	private static Map<String, Double> globals(JsonObject o)
	{
		Map<String, Double> m = new HashMap<>();
		for (Map.Entry<String, JsonElement> e : o.entrySet())
		{
			m.put(e.getKey(), e.getValue().getAsDouble());
		}
		return m;
	}

	private static BossRecord record(JsonObject st)
	{
		BossRecord r = new BossRecord();
		r.kc = st.get("kc").getAsInt();
		for (JsonElement se : st.getAsJsonArray("segs"))
		{
			JsonObject s = se.getAsJsonObject();
			r.segs.add(new Seg(s.get("from").getAsInt(), params(s.getAsJsonObject("params"))));
		}
		for (JsonElement de : st.getAsJsonArray("drops"))
		{
			JsonObject d = de.getAsJsonObject();
			r.drops.add(new DropRec(d.get("item").getAsString(), d.get("kc").isJsonNull() ? null : d.get("kc").getAsInt()));
		}
		return r;
	}

	private static void finish(String what)
	{
		System.out.println(what + ": " + checks + " checks, " + problems.size() + " problems");
		if (!problems.isEmpty())
		{
			int n = Math.min(problems.size(), 40);
			for (int i = 0; i < n; i++)
			{
				System.out.println("  " + problems.get(i));
			}
			Assert.fail(problems.size() + " mismatches against the JavaScript reference (first: " + problems.get(0) + ")");
		}
	}

	// ------------------------------------------------------------------ tests
	@Test
	public void catalogueMatches()
	{
		problems.clear();
		checks = 0;
		JsonObject metas = ref.getAsJsonObject("metas");
		for (Map.Entry<String, JsonElement> e : metas.entrySet())
		{
			Boss boss = data.boss(e.getKey());
			Assert.assertNotNull("boss " + e.getKey(), boss);
			JsonObject m = e.getValue().getAsJsonObject();
			List<String> tracked = new ArrayList<>();
			for (JsonElement t : m.getAsJsonArray("tracked"))
			{
				tracked.add(t.getAsString());
			}
			eq(e.getKey() + " tracked", tracked, Catalog.defaultTracked(boss));
			Map<String, Engine.ItemMeta> meta = boss.meta();
			JsonArray arr = m.getAsJsonArray("meta");
			eq(e.getKey() + " meta size", arr.size(), meta.size());
			for (JsonElement me : arr)
			{
				JsonObject o = me.getAsJsonObject();
				String n = o.get("n").getAsString();
				Engine.ItemMeta im = meta.get(n);
				if (im == null)
				{
					problems.add(e.getKey() + ": missing meta for " + n);
					continue;
				}
				List<String> flags = new ArrayList<>();
				for (JsonElement f : o.getAsJsonArray("f"))
				{
					flags.add(f.getAsString());
				}
				eq(e.getKey() + "/" + n + " flags", flags, im.flags);
				eq(e.getKey() + "/" + n + " hidden", o.get("h").getAsBoolean(), im.hidden);
				eq(e.getKey() + "/" + n + " noany", o.get("na").getAsBoolean(), im.noany);
				eq(e.getKey() + "/" + n + " pity", o.get("p").getAsInt(), im.pity);
				if (o.get("s").isJsonNull())
				{
					eq(e.getKey() + "/" + n + " seq", null, im.seq);
				}
				else
				{
					JsonObject s = o.getAsJsonObject("s");
					checks++;
					if (im.seq == null || !im.seq.slot.equals(s.get("slot").getAsString()) || im.seq.n != s.get("n").getAsInt() || im.seq.len != s.get("len").getAsInt())
					{
						problems.add(e.getKey() + "/" + n + " seq differs");
					}
				}
			}
			List<String> log = new ArrayList<>();
			for (JsonElement l : m.getAsJsonArray("log"))
			{
				log.add(l.getAsString());
			}
			eq(e.getKey() + " log set", log, new ArrayList<>(boss.logSet()));
			JsonObject follow = m.getAsJsonObject("follow");
			Map<String, List<String>> fm = Engine.followMap(boss);
			eq(e.getKey() + " follow keys", follow.keySet().size(), fm.size());
		}
		finish("catalogue");
	}

	@Test
	public void perKillChancesMatch()
	{
		problems.clear();
		checks = 0;
		for (JsonElement ce : ref.getAsJsonArray("probCases"))
		{
			JsonObject c = ce.getAsJsonObject();
			Boss boss = data.boss(c.get("boss").getAsString());
			Env env = Engine.makeEnv(boss, params(c.getAsJsonObject("params")), globals(c.getAsJsonObject("globals")), c.get("kc").getAsInt());
			Map<String, ItemProb> probs = Engine.itemProbs(boss, env, null, null);
			String tag = boss.id + " kc" + c.get("kc").getAsInt();
			for (Map.Entry<String, JsonElement> e : c.getAsJsonObject("probs").entrySet())
			{
				ItemProb ip = probs.get(e.getKey());
				if (ip == null)
				{
					problems.add(tag + ": no probability for " + e.getKey());
					continue;
				}
				JsonObject o = e.getValue().getAsJsonObject();
				same(tag + " " + e.getKey(), num(o.get("p")), ip.p);
				List<String> kinds = new ArrayList<>();
				if (o.has("k"))
				{
					for (JsonElement k : o.getAsJsonArray("k"))
					{
						kinds.add(k.getAsString());
					}
				}
				else
				{
					kinds.add("table");
				}
				eq(tag + " " + e.getKey() + " kinds", kinds, ip.kinds);
				checks++;
				if (o.has("s") != (ip.seq != null))
				{
					problems.add(tag + " " + e.getKey() + " seq presence differs");
				}
			}
		}
		finish("per-kill chances");
	}

	@Test
	public void luckAnalysisMatches()
	{
		problems.clear();
		checks = 0;
		for (JsonElement ce : ref.getAsJsonArray("cases"))
		{
			JsonObject c = ce.getAsJsonObject();
			Boss boss = data.boss(c.get("boss").getAsString());
			int window = c.get("window").getAsInt();
			BossRecord rec = record(c.getAsJsonObject("state"));
			Model m = Luck.makeModel(boss, rec, globals(c.getAsJsonObject("globals")));
			String tag0 = boss.id + " kc" + rec.kc;
			for (Map.Entry<String, JsonElement> e : c.getAsJsonObject("items").entrySet())
			{
				String tag = tag0 + " " + e.getKey();
				JsonObject o = e.getValue().getAsJsonObject();
				ItemAnalysis a = Luck.analyse(m, e.getKey(), window);
				eq(tag + " O", o.get("O").getAsInt(), a.O);
				eq(tag + " unknown", o.get("unknown").getAsInt(), a.unknown);
				eq(tag + " hits", o.get("hits").isJsonNull() ? null : o.get("hits").getAsInt(), a.hits);
				eq(tag + " once", o.get("once").getAsBoolean(), a.once);
				eq(tag + " collected", o.get("collected").getAsBoolean(), a.collected);
				eq(tag + " need", o.get("need").getAsInt(), a.need);
				same(tag + " pNext", num(o.get("pNext")), a.pNext);
				sameNullable(tag + " expected", o.get("expected"), a.expected);
				sameNullable(tag + " pct", o.get("pct"), a.pct);
				sameNullable(tag + " exceed", o.get("exceed"), a.exceed);
				sameNullable(tag + " cum", o.get("cum"), a.cum);
				eq(tag + " label", o.getAsJsonObject("label").get("key").getAsString(), a.label.key);
				eq(tag + " streakFrom", o.get("streakFrom").getAsInt(), a.streakFrom);
				eq(tag + " streak", o.get("streak").getAsInt(), a.streak);
				same(tag + " meter", num(o.get("meter")), a.meter);
				JsonObject fwd = o.getAsJsonObject("fwd");
				eq(tag + " fwd keys", fwd.keySet().size(), a.fwd.size());
				for (Map.Entry<String, JsonElement> f : fwd.entrySet())
				{
					Double got = a.fwd.get(Integer.parseInt(f.getKey()));
					if (got == null)
					{
						problems.add(tag + " fwd[" + f.getKey() + "] missing");
					}
					else
					{
						same(tag + " fwd[" + f.getKey() + "]", num(f.getValue()), got);
					}
				}
				if (o.has("kto"))
				{
					for (Map.Entry<String, JsonElement> k : o.getAsJsonObject("kto").entrySet())
					{
						double want = num(k.getValue());
						double got = a.kto.get(Double.parseDouble(k.getKey()));
						checks++;
						// a kill count found by bisection can sit on the edge of a threshold: allow one kill of slack
						if (!(want == got || (Double.isFinite(want) && Math.abs(want - got) <= 1)))
						{
							problems.add(tag + " kto[" + k.getKey() + "] expected " + want + " got " + got);
						}
					}
				}
				else
				{
					eq(tag + " kto absent", null, a.kto);
				}
			}
			AnyUnique au = null;
			List<String> an = new ArrayList<>();
			for (JsonElement n : c.getAsJsonArray("anyNames"))
			{
				an.add(n.getAsString());
			}
			if (an.size() >= 2)
			{
				au = Luck.anyUnique(m, an, window);
			}
			JsonElement any = c.get("any");
			if (any == null || any.isJsonNull())
			{
				eq(tag0 + " any", null, au);
			}
			else if (au == null)
			{
				problems.add(tag0 + " any unique missing");
			}
			else
			{
				JsonObject o = any.getAsJsonObject();
				eq(tag0 + " any O", o.get("O").getAsInt(), au.O);
				same(tag0 + " any expected", num(o.get("expected")), au.expected);
				same(tag0 + " any pct", num(o.get("pct")), au.pct);
				same(tag0 + " any meter", num(o.get("meter")), au.meter);
				same(tag0 + " any cum", num(o.get("cum")), au.cum);
				eq(tag0 + " any streak", o.get("streak").getAsInt(), au.streak);
				same(tag0 + " any pNext", num(o.get("pNext")), au.pNext);
				eq(tag0 + " any events", o.get("events").getAsInt(), au.events);
				for (Map.Entry<String, JsonElement> f : o.getAsJsonObject("fwd").entrySet())
				{
					same(tag0 + " any fwd[" + f.getKey() + "]", num(f.getValue()), au.fwd.get(Integer.parseInt(f.getKey())));
				}
			}
		}
		finish("luck analysis");
	}

	@Test
	public void pooledAnalysisMatches()
	{
		problems.clear();
		checks = 0;
		for (JsonElement pe : ref.getAsJsonArray("pools"))
		{
			JsonObject p = pe.getAsJsonObject();
			String name = p.get("name").getAsString();
			Map<String, Double> g = globals(p.getAsJsonObject("globals"));
			List<PoolMember> members = new ArrayList<>();
			for (JsonElement me : p.getAsJsonArray("members"))
			{
				JsonObject mo = me.getAsJsonObject();
				members.add(new PoolMember(Luck.makeModel(data.boss(mo.get("id").getAsString()), record(mo.getAsJsonObject("rec")), g), mo.get("snap").getAsInt()));
			}
			Pool r = Luck.analysePool(members, name, 50);
			JsonElement want = p.get("res");
			if (want == null || want.isJsonNull())
			{
				eq("pool " + name, null, r);
				continue;
			}
			JsonObject o = want.getAsJsonObject();
			if (r == null)
			{
				problems.add("pool " + name + " missing");
				continue;
			}
			eq("pool " + name + " O", o.get("O").getAsInt(), r.O);
			same("pool " + name + " expected", num(o.get("expected")), r.expected);
			same("pool " + name + " pct", num(o.get("pct")), r.pct);
			same("pool " + name + " meter", num(o.get("meter")), r.meter);
			same("pool " + name + " cum", num(o.get("cum")), r.cum);
			eq("pool " + name + " streak", o.get("streak").getAsLong(), r.streak);
			eq("pool " + name + " kills", o.get("kills").getAsLong(), r.kills);
		}
		finish("pooled analysis");
	}
}

package com.dropluckledger.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Collections;
import org.junit.Test;

/**
 * A count taken as Poisson, as the luck of a set of pieces is (all the Barrows equipment together).
 */
public class PoissonTest
{
	@Test
	public void theTailsMatchTheirFormulas()
	{
		assertEquals(1, Luck.poissonAtLeast(0, 3), 0);
		assertEquals(-Math.expm1(-0.5), Luck.poissonAtLeast(1, 0.5), 1e-15);
		assertEquals(1 - Math.exp(-2) * (1 + 2), Luck.poissonAtLeast(2, 2), 1e-14);
		// far in the tail it keeps its digits: P(X >= 30) with 5 expected is about 2.8e-14
		double tail = Luck.poissonAtLeast(30, 5);
		double sum = 0;
		double t = Math.exp(-5);
		for (int k = 1; k <= 30; k++)
		{
			t *= 5.0 / k;
		}
		for (int k = 30; k < 200; k++)
		{
			sum += t;
			t *= 5.0 / (k + 1);
		}
		assertEquals(sum, tail, sum * 1e-9);
		assertTrue(tail + "", tail > 2e-14 && tail < 4e-14);
		// nothing expected: none is certain
		assertEquals(0, Luck.poissonAtLeast(1, 0), 0);
	}

	@Test
	public void thePercentileIsTheMidPoint()
	{
		// none of 0.5 expected: tied with the players who have none, behind those with one or more
		assertEquals(0.5 * Math.exp(-0.5), Luck.poissonPct(0, 0.5), 1e-15);
		// one of 0.5 expected: ahead of those with none, tied with those with one
		assertEquals(Math.exp(-0.5) + 0.5 * 0.5 * Math.exp(-0.5), Luck.poissonPct(1, 0.5), 1e-15);
		// as many as expected, for a big count: about average
		assertEquals(0.5, Luck.poissonPct(400, 400), 0.02);
		assertEquals("vdry", Luck.luckLabel(Luck.poissonPct(5, 30)).key);
		assertEquals("vlucky", Luck.luckLabel(Luck.poissonPct(50, 30)).key);
	}

	@Test
	public void manySmallChancesAreAboutPoisson()
	{
		// 300 kills at 1 in 350: the count of copies is all but Poisson with the same average
		java.util.List<Luck.Run> runs = Collections.singletonList(new Luck.Run(1 / 350.0, 300));
		for (int m = 0; m <= 4; m++)
		{
			assertEquals(Luck.atLeast(m, runs), Luck.poissonAtLeast(m, 300 / 350.0), 0.002);
		}
	}
}

package com.dropluckledger.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import com.dropluckledger.TestData;
import com.dropluckledger.engine.Data.Boss;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/**
 * Copies with no kill number (brought in from the collection log or the Loot Tracker) of items whose chance changes with the copies
 * already owned.  When they came is not known, so the maths gives them the kills a usual history would have; before, they counted
 * as owned only after the last kill, so every earlier kill was worked out as if the player had none.
 */
public class UnknownKillLuckTest
{
	private final Data data = TestData.get();

	/**
	 * @param drops item, kill number (null when unknown), item, kill number...
	 */
	private Luck.Model model(String id, int kc, Map<String, Object> settings, Object... drops)
	{
		Boss b = data.boss(id);
		Luck.BossRecord rec = new Luck.BossRecord();
		rec.kc = kc;
		Map<String, Object> v = Engine.defaultParams(b);
		v.putAll(settings);
		rec.segs.add(new Luck.Seg(1, v));
		for (int i = 0; i < drops.length; i += 2)
		{
			rec.drops.add(new Luck.DropRec((String) drops[i], (Integer) drops[i + 1]));
		}
		return Luck.makeModel(b, rec, new HashMap<>());
	}

	private static Map<String, Object> toa()
	{
		Map<String, Object> v = new HashMap<>();
		v.put("raidLevel", 150);
		v.put("points", 10000);
		return v;
	}

	private static final String THREAD = "Thread of Elidinis";

	@Test
	public void threadsWithNoKillNumberAreNotCountedAsMissingEveryRaid()
	{
		// three threads in 115 raids, all brought in from the collection log: the first thread is 1/10 rising to 3/10 until one is
		// owned, then 1/50, so about 1 + 110/50 were to be expected, not 3/10 a raid for every raid
		Luck.Model m = model("tombs-of-amascut", 115, toa(), THREAD, null, THREAD, null, THREAD, null);
		Luck.ItemAnalysis a = Luck.analyse(m, THREAD, 50);
		assertTrue("expected " + a.expected, a.expected > 2 && a.expected < 3.5);
		assertNotEquals("vdry", a.label.key);
		assertEquals(1 / 50.0, a.pNext, 1e-12);
		// still three copies with no kill number, and no dry streak
		assertEquals(3, a.O);
		assertEquals(3, a.unknown);
		assertFalse(a.streakKnown);
		assertTrue(m.known(THREAD).isEmpty());
		// the first goes where the expected copies reach a half
		double c = 0;
		int first = 0;
		for (int k = 1; k <= 115 && first == 0; k++)
		{
			c += m.pAt(THREAD, k, 0);
			if (c >= 0.5)
			{
				first = k;
			}
		}
		assertEquals(0, m.ownedAt(THREAD, first));
		assertEquals(1, m.ownedAt(THREAD, first + 1));
		// close to the same threads with their kills known
		Luck.ItemAnalysis known = Luck.analyse(model("tombs-of-amascut", 115, toa(), THREAD, 5, THREAD, 55, THREAD, 105), THREAD, 50);
		assertEquals(known.expected, a.expected, 0.3);
	}

	@Test
	public void unknownCopiesComeBeforeKnownOnesAndExtraOnesAtTheLastKill()
	{
		Luck.Model m = model("tombs-of-amascut", 115, toa(), THREAD, null, THREAD, 110);
		assertEquals(1, m.ownedAt(THREAD, 109));
		assertEquals(2, m.ownedAt(THREAD, 111));
		// more than a usual history holds: the rest count from the next kill
		Luck.Model many = model("tombs-of-amascut", 20, toa(), THREAD, null, THREAD, null, THREAD, null, THREAD, null, THREAD, null, THREAD, null);
		assertTrue(many.ownedAt(THREAD, 20) < 6);
		assertEquals(6, many.ownedAt(THREAD, 21));
		// no kills yet: owned from the first kill
		Luck.Model none = model("tombs-of-amascut", 0, toa(), THREAD, null);
		assertEquals(1, none.ownedAt(THREAD, 1));
		assertEquals(1 / 50.0, none.pAt(THREAD, 1), 1e-12);
	}

	@Test
	public void theDesertTreasureQuartzWithNoKillNumber()
	{
		// the quartz ramps from 1/200 to 1/50 by 300 kills until the first one, then goes back to 1/200
		Luck.ItemAnalysis a = Luck.analyse(model("duke-sucellus", 400, new HashMap<>(), "Ice quartz", null, "Ice quartz", null), "Ice quartz", 50);
		assertTrue("expected " + a.expected, a.expected > 1.5 && a.expected < 3);
		assertNotEquals("vdry", a.label.key);
	}

	@Test
	public void vorkathsHeadIsGuaranteedOnTheFiftiethKillOnly()
	{
		Luck.Model m = model("vorkath", 500, new HashMap<>());
		assertEquals(1 / 50.0, m.pAt("Vorkath's head", 49), 1e-12);
		assertEquals(1, m.pAt("Vorkath's head", 50), 0);
		assertEquals(1 / 50.0, m.pAt("Vorkath's head", 51), 1e-12);
		// not every 50 kills since the last head
		assertEquals(1 / 50.0, m.pAt("Vorkath's head", 100), 1e-12);
		assertEquals(1 + 499 / 50.0, Luck.analyse(m, "Vorkath's head", 50).expected, 1e-9);
		// heads with no kill number change nothing, and the next kill is not "guaranteed"
		Object[] heads = new Object[24];
		for (int i = 0; i < heads.length; i += 2)
		{
			heads[i] = "Vorkath's head";
		}
		Luck.ItemAnalysis a = Luck.analyse(model("vorkath", 500, new HashMap<>(), heads), "Vorkath's head", 50);
		assertEquals(1 + 499 / 50.0, a.expected, 1e-9);
		assertEquals(1 / 50.0, a.pNext, 1e-12);
	}

	@Test
	public void theSlepeyTabletAlwaysComesOnTheTwentyFifthKill()
	{
		Luck.Model m = model("phosanis-nightmare", 200, new HashMap<>());
		assertEquals(1 / 25.0, m.pAt("Slepey tablet", 24), 1e-12);
		assertEquals(1, m.pAt("Slepey tablet", 25), 0);
		assertEquals(1 / 25.0, m.pAt("Slepey tablet", 50), 1e-12);
	}

	@Test
	public void theKerisJewelsAndThePendantOfAtesAreNoSpoons()
	{
		Boss toa = data.boss("tombs-of-amascut");
		for (String j : new String[]{"Eye of the Corruptor", "Jewel of the Sun", "Breach of the Scarab", "Jewel of Amascut"})
		{
			assertTrue(j, toa.meta().get(j).noSpoon);
		}
		assertTrue(data.boss("amoxliatl").meta().get("Pendant of Ates (inert)").noSpoon);
		assertFalse(toa.meta().get(THREAD).noSpoon);
	}
}

package com.dropluckledger.history;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.dropluckledger.TestData;
import com.dropluckledger.capture.BossIndex;
import com.dropluckledger.engine.Data;
import com.dropluckledger.ledger.BossState;
import com.dropluckledger.ledger.Drop;
import com.dropluckledger.ledger.Ledger;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;

/**
 * An item tracked late gets its earlier copies from the drop log.
 */
public class BackfillTest
{
	private final Data data = TestData.get();
	private final BossIndex index = new BossIndex(data);
	private long now = 10_000L;
	private Ledger ledger;

	@Before
	public void setUp()
	{
		ledger = new Ledger(data, () -> now);
	}

	private static LoggedLoot loot(String boss, int kill, long t, String... items)
	{
		List<LoggedLoot.Item> l = new ArrayList<>();
		for (String i : items)
		{
			l.add(new LoggedLoot.Item(i, i.equals("Zulrah's scales") ? 150 : 1));
		}
		return new LoggedLoot(t, boss, kill, l, null);
	}

	private List<Integer> kills(String boss, String item)
	{
		List<Integer> out = new ArrayList<>();
		for (Drop d : ledger.copyOf(boss).drops)
		{
			if (d.item.equals(item))
			{
				out.add(d.kc);
			}
		}
		return out;
	}

	@Test
	public void theCopiesComeInAtTheKillsTheyCameOn()
	{
		ledger.setKc("zulrah", 200);
		List<LoggedLoot> log = Arrays.asList(
			loot("zulrah", 10, 1_000, "Coins", "Zulrah's scales"),
			loot("zulrah", 30, 2_000, "Coins", "Magic fang"),
			loot("vorkath", 31, 2_100, "Magic fang"), // another boss's log is not this one's
			loot("zulrah", 70, 3_000, "Magic fang", "Uncut onyx"));
		ledger.setTracked("zulrah", "Zulrah's scales", true);
		Backfill.Result r = Backfill.apply(ledger, index, "zulrah", "Magic fang", log);
		assertEquals(2, r.added);
		assertEquals(0, r.numbered);
		assertEquals(Arrays.asList(30, 70), kills("zulrah", "Magic fang"));
		for (Drop d : ledger.copyOf("zulrah").drops)
		{
			assertEquals(Drop.SRC_LIVE, d.src);
		}
		// a stack is one drop, with its quantity
		Backfill.apply(ledger, index, "zulrah", "Zulrah's scales", log);
		BossState z = ledger.copyOf("zulrah");
		assertEquals(1, z.copies("Zulrah's scales"));
		for (Drop d : z.drops)
		{
			if (d.item.equals("Zulrah's scales"))
			{
				assertEquals(150, d.qty);
			}
		}
		// looking again adds nothing
		assertTrue(Backfill.apply(ledger, index, "zulrah", "Magic fang", log).isEmpty());
		assertEquals(200, ledger.kc("zulrah"));
	}

	@Test
	public void aCopyTheLedgerHasAtThatKillIsNotAddedTwice()
	{
		ledger.setKc("zulrah", 100);
		ledger.logDrop("zulrah", "Magic fang", 30, 1, null, Drop.SRC_LIVE);
		List<LoggedLoot> log = Arrays.asList(loot("zulrah", 30, 2_000, "Magic fang"),
			// two in one loot are two drops
			loot("zulrah", 60, 3_000, "Magic fang", "Magic fang"));
		Backfill.Result r = Backfill.apply(ledger, index, "zulrah", "Magic fang", log);
		assertEquals(2, r.added);
		assertEquals(Arrays.asList(30, 60, 60), kills("zulrah", "Magic fang"));
	}

	@Test
	public void aCopyFromGameHistoryTakesTheKillNumberWhenItCountedThatLoot()
	{
		ledger.setKc("zulrah", 100);
		// the collection log was read (and its copy added) after the fang dropped: that copy is this one
		now = 5_000L;
		ledger.addOwned("zulrah", "Magic fang", 1);
		Backfill.Result r = Backfill.apply(ledger, index, "zulrah", "Magic fang", Arrays.asList(loot("zulrah", 40, 3_000, "Magic fang")));
		assertEquals(0, r.added);
		assertEquals(1, r.numbered);
		assertEquals(Arrays.asList(40), kills("zulrah", "Magic fang"));
		assertEquals(Drop.SRC_LIVE, ledger.copyOf("zulrah").drops.get(0).src);
	}

	@Test
	public void aCopyFromGameHistoryOlderThanTheLootIsAnotherCopy()
	{
		ledger.setKc("zulrah", 100);
		now = 1_000L;
		ledger.addOwned("zulrah", "Magic fang", 1);
		Backfill.Result r = Backfill.apply(ledger, index, "zulrah", "Magic fang", Arrays.asList(loot("zulrah", 40, 3_000, "Magic fang")));
		assertEquals(1, r.added);
		assertEquals(0, r.numbered);
		List<Integer> k = kills("zulrah", "Magic fang");
		assertEquals(2, k.size());
		assertNull(k.get(0));
		assertEquals(Integer.valueOf(40), k.get(1));
	}

	@Test
	public void lootPastTheKillCountBelongsToAnotherLedger()
	{
		// the ledger was replaced by an older backup: the log runs further than its kills
		ledger.setKc("zulrah", 50);
		Backfill.Result r = Backfill.apply(ledger, index, "zulrah", "Magic fang",
			Arrays.asList(loot("zulrah", 40, 1_000, "Magic fang"), loot("zulrah", 80, 2_000, "Magic fang")));
		assertEquals(1, r.added);
		assertEquals(Arrays.asList(40), kills("zulrah", "Magic fang"));
		assertEquals(50, ledger.kc("zulrah"));
	}

	@Test
	public void aSharedItemKeepsTheOtherBossesKillCountsThatMatter()
	{
		ledger.setKc("vardorvis", 100);
		Map<String, Integer> snap = new LinkedHashMap<>();
		snap.put("the-whisperer", 30);
		snap.put("zulrah", 500); // does not drop it
		List<LoggedLoot> log = Arrays.asList(new LoggedLoot(1_000, "vardorvis", 44,
			Arrays.asList(new LoggedLoot.Item("Virtus mask", 1)), snap));
		Backfill.apply(ledger, index, "vardorvis", "Virtus mask", log);
		Drop d = ledger.copyOf("vardorvis").drops.get(0);
		assertEquals(Integer.valueOf(44), d.kc);
		assertEquals(1, d.snap.size());
		assertEquals(Integer.valueOf(30), d.snap.get("the-whisperer"));
	}
}

package com.dropluckledger.history;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.dropluckledger.TestData;
import com.dropluckledger.capture.BossIndex;
import com.dropluckledger.capture.Capture;
import com.dropluckledger.engine.Data;
import com.dropluckledger.history.HistoryPlanner.ItemRow;
import com.dropluckledger.history.HistoryPlanner.KcRow;
import com.dropluckledger.history.HistoryPlanner.Plan;
import com.dropluckledger.ledger.BossState;
import com.dropluckledger.ledger.Drop;
import com.dropluckledger.ledger.Ledger;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;

/**
 * The ledger checked against what the game shows on screen (the Boss Kill Log for kill counts, collection log pages for items): what
 * would change is listed, and nothing changes until the list is added.
 */
public class CatchupTest
{
	private final Data data = TestData.get();
	private final BossIndex index = new BossIndex(data);
	private Ledger ledger;
	private Capture capture;
	private Catchup catchup;

	@Before
	public void setUp()
	{
		ledger = new Ledger(data, () -> 5_000L);
		capture = new Capture(ledger, index);
		catchup = new Catchup(ledger, capture, new HistoryPlanner(ledger, index), index);
	}

	private static Map<String, Integer> map(Object... kv)
	{
		Map<String, Integer> m = new LinkedHashMap<>();
		for (int i = 0; i < kv.length; i += 2)
		{
			m.put((String) kv[i], (Integer) kv[i + 1]);
		}
		return m;
	}

	/**
	 * Every item on a page, owned or not, as the game names them.
	 */
	private static List<String> names(String... names)
	{
		return Arrays.asList(names);
	}

	private static final List<String> ZULRAH_PAGE = names("Pet snakeling", "Tanzanite fang", "Magic fang", "Serpentine visage", "Uncut onyx",
		"Tanzanite mutagen", "Magma mutagen", "Jar of swamp");
	private static final List<String> SKOTIZO_PAGE = names("Skotos", "Jar of darkness", "Dark claw", "Dark totem", "Uncut onyx", "Ancient shard");

	/**
	 * This computer saw Zulrah up to kill 100, with a Tanzanite fang at kill 50.
	 */
	private void playedHere()
	{
		capture.onKillCount("Zulrah", 50, 0);
		capture.onLoot(new Capture.Loot("Zulrah", 1, Collections.singletonList(new Capture.Stack("Tanzanite fang", 1)), null, 2));
		capture.onKillCount("Zulrah", 100, 200);
		capture.onTick(1000, true);
	}

	private Plan pageOnly(String title, Map<String, Integer> items, List<String> listed)
	{
		catchup.clear();
		catchup.addPage(title, map(), items, listed, catchup.stamp());
		return catchup.plan();
	}

	private Plan killLogOnly(Object... kv)
	{
		catchup.clear();
		catchup.addKillLog(map(kv), catchup.stamp());
		return catchup.plan();
	}

	private static ItemRow row(Plan plan, String bossId, String item)
	{
		for (ItemRow r : plan.items)
		{
			if (r.bossId.equals(bossId) && r.item.equals(item))
			{
				return r;
			}
		}
		return null;
	}

	private static KcRow kcRow(Plan plan, String bossId)
	{
		for (KcRow r : plan.kc)
		{
			if (r.bossId.equals(bossId))
			{
				return r;
			}
		}
		return null;
	}

	// ------------------------------------------------------------------ nothing changes until the list is added

	@Test
	public void theRecordsListWhatTheLedgerIsMissingAndNothingChangesUntilItIsAdded()
	{
		playedHere();
		ledger.setTracked("zulrah", "Magic fang", false);
		catchup.addKillLog(map("Zulrah", 150), catchup.stamp());
		catchup.addPage("Zulrah", map(), map("Tanzanite fang", 2, "Pet snakeling", 1, "Magic fang", 1), ZULRAH_PAGE, catchup.stamp());
		Plan plan = catchup.plan();
		// only listed
		assertEquals(100, ledger.kc("zulrah"));
		assertEquals(1, ledger.copyOf("zulrah").copies("Tanzanite fang"));
		assertEquals(1, plan.kc.size());
		KcRow k = plan.kc.get(0);
		assertEquals(100, k.cur);
		assertEquals(150, k.to);
		assertTrue(k.on);
		assertFalse(k.lower);
		// the player does not track the magic fang: it is not listed
		assertEquals(2, plan.items.size());
		assertEquals(1, row(plan, "zulrah", "Pet Snakeling").add); // the data's spelling of the game's "Pet snakeling"
		assertEquals(1, row(plan, "zulrah", "Tanzanite fang").add);
		assertNull(row(plan, "zulrah", "Magic fang"));
		assertTrue(Catchup.worthShowing(plan));
		assertEquals("Boss Kill Log, Collection Log (Zulrah): kill count Zulrah 100 → 150; Pet Snakeling +1, Tanzanite fang +1. Nothing changes until "
			+ "you add them.", Catchup.describe(plan));

		assertEquals("{1, 2, 0}", text(catchup.apply(plan)));
		BossState z = ledger.copyOf("zulrah");
		assertEquals(150, z.kc);
		assertEquals(2, z.copies("Tanzanite fang"));
		assertEquals(1, z.importedUnknown("Tanzanite fang"));
		assertEquals(1, z.copies("Pet Snakeling"));
		assertEquals(0, z.copies("Magic fang"));
		// the reads the list was made from are let go: nothing is left to offer
		assertFalse(Catchup.worthShowing(catchup.plan()));
		// looking at the page again lists nothing
		assertFalse(Catchup.worthShowing(pageOnly("Zulrah", map("Tanzanite fang", 2, "Pet snakeling", 1), ZULRAH_PAGE)));
		// the next kill on this computer follows on from the game's count
		capture.onKillCount("Zulrah", 151, 2000);
		assertEquals(151, ledger.kc("zulrah"));
	}

	@Test
	public void aCollectionLogPageSetsTheKillCountsItShows()
	{
		playedHere();
		// a page that shows every count of a boss sets it, up or down: what an earlier version raised from a page drawn with another
		// page's numbers comes back down
		capture.onShownCount("Araxxor kills", 81);
		catchup.addPage("Araxxor", map("Araxxor kills", 0), map(), names("Noxious pommel", "Araxyte fang"), catchup.stamp());
		Plan plan = catchup.plan();
		KcRow r = kcRow(plan, "araxxor");
		assertTrue(r.lower);
		assertEquals(81, r.cur);
		assertEquals(0, r.to);
		assertEquals("Collection Log (Araxxor): kill count Araxxor 81 → 0. Nothing changes until you add it.", Catchup.describe(plan));
		catchup.apply(plan);
		assertEquals(0, ledger.kc("araxxor"));
		// and up, with the kills it was missing
		catchup.addPage("Zulrah", map("Zulrah kills", 130), map("Tanzanite fang", 1), ZULRAH_PAGE, catchup.stamp());
		assertEquals(130, kcRow(catchup.plan(), "zulrah").to);
	}

	@Test
	public void aPageWithOnlySomeOfABosssCountsIsNotUsedForItsKillCount()
	{
		// a Desert Treasure II boss's page has no awakened count: whether its count holds the awakened kills is not known
		catchup.addPage("Duke Sucellus", map("Duke Sucellus kills", 40), map(), names(), catchup.stamp());
		assertTrue(catchup.plan().kc.isEmpty());
		// a page's lines that are not a boss's count change nothing
		catchup.addPage("Hallowed Sepulchre", map("Grand Hallowed Coffins opened", 12), map(), names(), catchup.stamp());
		assertFalse(Catchup.worthShowing(catchup.plan()));
	}

	@Test
	public void theLatestLookAtACountIsTheOneUsed()
	{
		catchup.addKillLog(map("Vorkath", 30), catchup.stamp());
		catchup.addPage("Vorkath", map("Vorkath kills", 32), map(), names(), catchup.stamp());
		assertEquals(32, kcRow(catchup.plan(), "vorkath").to);
		catchup.addKillLog(map("Vorkath", 33), catchup.stamp());
		assertEquals(33, kcRow(catchup.plan(), "vorkath").to);
	}

	@Test
	public void linesLeftUntickedAreNotAdded()
	{
		playedHere();
		catchup.addKillLog(map("Zulrah", 150), catchup.stamp());
		catchup.addPage("Zulrah", map(), map("Tanzanite fang", 2), ZULRAH_PAGE, catchup.stamp());
		Plan plan = catchup.plan();
		plan.kc.get(0).on = false;
		assertEquals("Boss Kill Log, Collection Log (Zulrah): Tanzanite fang +1. 1 more line to look at. Nothing changes until you add it.",
			Catchup.describe(plan));
		assertEquals("{0, 1, 0}", text(catchup.apply(plan)));
		assertEquals(100, ledger.kc("zulrah"));
		assertEquals(2, ledger.copyOf("zulrah").copies("Tanzanite fang"));
	}

	@Test
	public void dismissingForgetsWhatWasRead()
	{
		playedHere();
		catchup.addKillLog(map("Zulrah", 150), catchup.stamp());
		Plan plan = catchup.plan();
		catchup.clear();
		assertFalse(Catchup.worthShowing(catchup.plan()));
		// a list made before is not added after all
		assertEquals("{0, 0, 0}", text(catchup.apply(plan)));
		assertEquals(100, ledger.kc("zulrah"));
	}

	@Test
	public void recordsReadAfterAListWaitForTheNextOne()
	{
		playedHere();
		catchup.addKillLog(map("Zulrah", 150), catchup.stamp());
