	@Test
	public void anItemSeveralBossesDropIsPooled()
	{
		Map<String, List<String>> idx = Catalog.logIndex(data);
		String shared = null;
		for (Map.Entry<String, List<String>> e : idx.entrySet())
		{
			if (e.getValue().size() >= 2)
			{
				shared = e.getKey();
				break;
			}
		}
