		l.setKc("barrows", 300);
		List<String> pieces = new java.util.ArrayList<>();
		for (String n : l.trackedNames("barrows"))
		{
			if ("Barrows equipment".equals(data.boss("barrows").meta().get(n).group))
			{
				pieces.add(n);
			}
		}
		assertEquals(24, pieces.size());
		// one each of 21 pieces: each is ahead of its own rate, but together they are about what 300 chests give (about 20.6)
		for (int i = 0; i < 21; i++)
		{
			l.logDrop("barrows", pieces.get(i), 10 + i * 10, 1, null, Drop.SRC_LIVE);
		}
		Views.OverviewView o = new Analyzer(l, null).overview(() -> false);
		for (Views.Rank r : o.spoons)
		{
			assertFalse(r.item, pieces.contains(r.item));
		}
		assertNull(spoon(o, "Barrows equipment"));
		// ten more and the set as a whole is ahead: one line for all of it
		for (int i = 0; i < 10; i++)
		{
			l.logDrop("barrows", pieces.get(i), 15 + i * 10, 1, null, Drop.SRC_LIVE);
		}
		o = new Analyzer(l, null).overview(() -> false);
		Views.Rank set = spoon(o, "Barrows equipment");
		assertNotNull(set);
		assertEquals(31, set.got);
		assertEquals(24, set.pieces);
		assertEquals(300 * 7 / 102.0, set.expected, 0.6);
		assertEquals(Luck.poissonPct(31, set.expected), set.pct, 1e-12);
		assertEquals(pieces.get(0), set.icon);
		for (Views.Rank r : o.spoons)
		{
			assertFalse(r.item, pieces.contains(r.item));
		}
		// the Barrows page still has every piece
		assertEquals(l.trackedNames("barrows").size(), an(l).boss("barrows", () -> false).items.size());
	}

	@Test
	public void eachMoonIsOneLineOfSpoons()
	{
		Ledger l = ledger();
		l.setKc("moons-of-peril", 100);
		l.logDrop("moons-of-peril", "Blue Moon spear", 5, 1, null, Drop.SRC_LIVE);
		l.logDrop("moons-of-peril", "Blue Moon helm", 20, 1, null, Drop.SRC_LIVE);
		l.logDrop("moons-of-peril", "Blue Moon chestplate", 40, 1, null, Drop.SRC_LIVE);
		l.logDrop("moons-of-peril", "Blue Moon tassets", 60, 1, null, Drop.SRC_LIVE);
		Views.OverviewView o = new Analyzer(l, null).overview(() -> false);
		Views.Rank blue = spoon(o, "Blue Moon set");
		assertNotNull(blue);
		assertEquals(4, blue.got);
		assertEquals(4, blue.pieces);
		assertNull(spoon(o, "Blue Moon spear"));
		assertNull(spoon(o, "Eclipse Moon set"));
	}

	private Analyzer an(Ledger l)
	{
		return new Analyzer(l, null);
	}

	@Test
	public void onlyItemsWithoutARateAreListedAsUnknown()
	{
		// every boss in the data has its rates; an item marked unknown is listed (and left out of the luck figures)
		for (Data.Boss b : data.bosses)
		{
			for (String n : Views.unknownRates(b))
			{
				assertTrue(b.id + " " + n, b.allRows().stream().anyMatch(r -> r.name.equals(n) && "unknown".equals(r.rate)));
			}
		}
		assertTrue(Views.unknownRates(data.boss("zulrah")).isEmpty());
	}
}

package com.dropluckledger.ui;

import java.awt.Component;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.JComponent;

/**
 * Stands in for the panel's windows: records what was asked and answers as the test says.
 */
final class FakeDialogs implements Dialogs
{
	final List<String> asked = new ArrayList<>();
	final List<String> messages = new ArrayList<>();
	boolean formAnswer = true;
	boolean confirmAnswer = true;
	int chooseAnswer = 0;
	/**
	 * Runs on a form before the "player" closes it, to fill it in.
	 */
	Consumer<JComponent> fill = f ->
	{
	};
	JComponent lastForm;
	String lastTitle;

	@Override
	public boolean form(Component parent, String title, JComponent form, String ok)
	{
		asked.add("form:" + title);
		lastForm = form;
		lastTitle = title;
		fill.accept(form);
		return formAnswer;
	}

	@Override
	public boolean confirm(Component parent, String title, String message, String yes)
	{
		asked.add("confirm:" + title);
		messages.add(message);
		return confirmAnswer;
	}

	@Override
	public int choose(Component parent, String title, String message, String... options)
	{
		asked.add("choose:" + title);
		messages.add(message);
		return chooseAnswer;
	}

	@Override
	public void note(Component parent, String title, String message)
	{
		asked.add("note:" + title);
		messages.add(message);
	}

	String last()
	{
		return messages.isEmpty() ? "" : messages.get(messages.size() - 1);
	}
}

package com.dropluckledger.ui;

import com.dropluckledger.history.HistoryPlanner;
import com.dropluckledger.ledger.Ledger;
import com.dropluckledger.plugin.TrackingState;
import java.awt.Component;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;

/**
 * Stands in for the plugin.
 */
final class FakeHost implements LedgerPanel.Host
{
	volatile TrackingState state = TrackingState.TRACKING;
	HistoryPlanner.Plan plan = new HistoryPlanner.Plan();
	Ledger backupToImport;
	int planRequests;
	int exports;
	int imports;
	final List<Ledger> replaced = new ArrayList<>();
	final List<String> backfilled = new ArrayList<>();
	int dropLogsErased;
	/**
	 * The lists from the game's records the panel asked to add, and what the plugin answers.
	 */
	final List<HistoryPlanner.Plan> synced = new ArrayList<>();
	int[] syncAnswer = {0, 0, 0, 0};
	int syncDismissals;

	@Override
	public TrackingState state()
	{
		return state;
	}

	@Override
	public void planHistory(Consumer<HistoryPlanner.Plan> then)
	{
		planRequests++;
		then.accept(plan);
	}

	@Override
	public int[] applySync(HistoryPlanner.Plan plan)
	{
		synced.add(plan);
		return syncAnswer;
	}

	@Override
	public void dismissSync()
	{
		syncDismissals++;
	}

	@Override
	public void exportBackup(Component parent)
	{
		exports++;
	}

	@Override
	public void importBackup(Component parent, Consumer<Ledger> confirm)
	{
		imports++;
		if (backupToImport != null)
		{
			confirm.accept(backupToImport);
		}
	}

	@Override
	public void replaceLedger(Ledger backup)
	{
		replaced.add(backup);
	}

	@Override
	public void backfill(String bossId, String item)
	{
		backfilled.add(bossId + ":" + item);
	}

	@Override
	public void eraseDropLog()
	{
		dropLogsErased++;
	}
}

package com.dropluckledger.ui;

import static org.junit.Assert.assertEquals;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * The formatting must print what the web app prints.  The expected texts were produced by the web app's own functions.
 */
public class FmtTest
{
	private static JsonObject fixture;

	@BeforeClass
	public static void load() throws IOException
	{
		try (InputStream in = FmtTest.class.getResourceAsStream("/fmt.json"))
		{
			fixture = new JsonParser().parse(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
		}
	}

	private static double number(JsonElement e)
	{
		if (e.getAsJsonPrimitive().isString())
		{
			assertEquals("inf", e.getAsString());
			return Double.POSITIVE_INFINITY;
		}
		return e.getAsDouble();
	}

	@Test
	public void numbersMatchTheWebApp()
	{
		JsonArray rows = fixture.getAsJsonArray("fmt");
		for (JsonElement r : rows)
		{
			JsonArray row = r.getAsJsonArray();
			double in = number(row.get(0));
			assertEquals("fmt(" + in + ")", row.get(1).getAsString(), Fmt.num(in));
		}
	}

	@Test
	public void percentagesMatchTheWebApp()
	{
		JsonArray rows = fixture.getAsJsonArray("pct");
		for (JsonElement r : rows)
		{
			JsonArray row = r.getAsJsonArray();
			JsonElement in = row.get(0);
			Double p;
			if (in.getAsJsonPrimitive().isString())
			{
				p = "nan".equals(in.getAsString()) ? Double.NaN : null;
			}
			else
			{
				p = in.getAsDouble();
			}
			assertEquals("pctStr(" + in + ")", row.get(1).getAsString(), Fmt.pct(p));
		}
	}

	@Test
	public void percentagesInMarkupKeepTheirSigns()
	{
		assertEquals("&lt;0.1%", Fmt.pctHtml(0.0004));
		assertEquals("&gt;99.9%", Fmt.pctHtml(0.9999));
		assertEquals("38%", Fmt.pctHtml(0.38));
		assertEquals("<0.1%", Swings.plain(Look.html(100, "x " + Fmt.pctHtml(0.0004))).replace("x ", ""));
	}

	@Test
	public void ratesMatchTheWebApp()
	{
		JsonArray rows = fixture.getAsJsonArray("rate");
		for (JsonElement r : rows)
		{
			JsonArray row = r.getAsJsonArray();
			JsonElement in = row.get(0);
			double p = in.getAsJsonPrimitive().isString() ? 0 : in.getAsDouble();
			assertEquals("rateStr(" + in + ")", row.get(1).getAsString(), Fmt.rate(p));
		}
	}

	@Test
	public void expectedCopiesUseTwoDecimalsUnderTen()
	{
		assertEquals("0.42", Fmt.expected(0.4213));
		assertEquals("9.99", Fmt.expected(9.994));
		assertEquals("12.3", Fmt.expected(12.34));
	}
}

package com.dropluckledger.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.dropluckledger.engine.Catalog;
